def generate_secret_key() -> str:
    return secrets.token_hex(32)

# One business per install. Registration is how that business is created, so
# it is open until it has been - and shut afterwards. Set to 1 only if this
# install is genuinely meant to host more than one company.
ALLOW_SELF_REGISTRATION = os.getenv("ALLOW_SELF_REGISTRATION", "0") == "1"

SECRET_KEY = os.getenv("SECRET_KEY", "")
if not SECRET_KEY or SECRET_KEY == "generate_a_random_secret_string":
    if database.IS_DEPLOYED:
        # On a container the generated key cannot be persisted, so it differs
        # on every boot and signs the whole tenancy out each redeploy. That is
        # a security setting quietly degrading rather than a missing one, so
        # the deploy stops here.
        raise RuntimeError(
            "SECRET_KEY is not set. Sessions are signed with it, so a "
            "generated one would change on every redeploy and sign every user "
            "out. Generate one with "
            "`python -c \"import secrets; print(secrets.token_hex(32))\"` and "
            "set it in the service Variables tab.")
    SECRET_KEY = generate_secret_key()
    # Writing to .env only helps on a machine with a persistent disk. On a
    # container platform the file is discarded on redeploy, so a generated key
    # differs every boot and every session is invalidated - all users are
    # silently signed out. Say so loudly rather than logging it as info.
    persisted = False
    try:
        env_path = os.path.join(os.path.dirname(__file__), ".env")
        with open(env_path, "a") as f:
            f.write(f"\nSECRET_KEY={SECRET_KEY}\n")
        persisted = True
    except Exception:
        pass
    logger.warning(
        "SECRET_KEY was not set, so a temporary one was generated%s. "
        "Every restart will sign all users out. Set SECRET_KEY in the "
        "environment to fix this.",
        " and written to .env" if persisted else "",
    )

def ensure_admin_user():
    try:
        with SessionLocal() as db:
            existing_admin = db.query(models.DBAdminUser).first()
            if not existing_admin:
                admin_pwd = os.getenv("ADMIN_PASSWORD", "admin")
                hashed = hash_password(admin_pwd)
                db.add(models.DBAdminUser(username="admin", password=hashed))
                db.commit()
                logger.info("Created default admin user (username=admin)")
            elif existing_admin.password and ':' not in existing_admin.password:
                existing_admin.password = hash_password(existing_admin.password)
                db.commit()
                logger.info("Upgraded admin password to hashed format")
    except Exception as e:
        logger.error(f"Admin user init failed: {e}")

# --- Rate Limiter (in-memory, per-IP) ---
class RateLimiter:
    """Fixed-memory sliding window.

    The previous version kept a dict entry for every key it ever saw and never
    removed them, so a long-running process grew without bound (one entry per
    distinct client IP, forever). Stale keys are now swept periodically.
    """

    SWEEP_INTERVAL = 300  # seconds
    MAX_KEYS = 10000

    def __init__(self):
        self._hits = defaultdict(list)
        self._lock = threading.Lock()
        self._last_sweep = time.time()

    def _sweep(self, now: float, window: int) -> None:
        cutoff = now - max(window, 3600)
        for key in [k for k, hits in self._hits.items() if not hits or hits[-1] < cutoff]:
            self._hits.pop(key, None)
        # Hard ceiling in case of a burst of unique keys between sweeps.
        if len(self._hits) > self.MAX_KEYS:
            for key in sorted(self._hits, key=lambda k: self._hits[k][-1])[: len(self._hits) - self.MAX_KEYS]:
                self._hits.pop(key, None)
        self._last_sweep = now

    def is_rate_limited(self, key: str, max_requests: int = 10, window: int = 60) -> bool:
        now = time.time()
        with self._lock:
            if now - self._last_sweep > self.SWEEP_INTERVAL:
                self._sweep(now, window)
            hits = [t for t in self._hits[key] if now - t < window]
            if len(hits) >= max_requests:
                self._hits[key] = hits
                return True
            hits.append(now)
            self._hits[key] = hits
            return False


rate_limiter = RateLimiter()

def esc(val) -> str:
    """HTML-escape a value for safe insertion into HTML."""
    if val is None:
        return ""
    return html_mod.escape(str(val))

# --- Money / tax helpers ---------------------------------------------------
# Line items carry a human-readable tax label ("20% VAT", "5% VAT",
# "0% Zero Rated", "No Tax"). Everything downstream must derive the rate from
# that label rather than assuming a single blanket rate.

DEFAULT_TAX_RATE = 0.20
_TAX_PCT_RE = re.compile(r"(\d+(?:\.\d+)?)\s*%")


def parse_tax_rate(label, default: float = DEFAULT_TAX_RATE) -> float:
    """Turn a tax label into a decimal rate. '5% VAT' -> 0.05, 'No Tax' -> 0.0."""
    s = str(label or "").strip()
    if not s:
        return default
    m = _TAX_PCT_RE.search(s)
    if m:
        try:
            return max(0.0, float(m.group(1))) / 100.0
        except ValueError:
            return default
    low = s.lower()
    if any(w in low for w in ("no tax", "none", "zero", "exempt", "outside")):
        return 0.0
    return default


def money(val) -> float:
    """Round to 2dp using banker's-free half-up, which is what invoices expect."""
    try:
        d = Decimal(str(val or 0))
    except (InvalidOperation, ValueError, TypeError):
        return 0.0
    return float(d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def days_after(on, days):
    """The date `days` after `on` (a date or a timestamp string), or "" when
    `on` is not a date. When a bill falls due, from when it was signed."""
    try:
        d = datetime.strptime(str(on or "")[:10], "%Y-%m-%d").date()
    except ValueError:
        return ""
    return (d + timedelta(days=int(days or 0))).isoformat()


def supplier_payment_days(db, client_id, name):
    """What the supplier list says this supplier is paid in; 30 days when it
    is not on the list or says nothing."""
    for x in db.query(models.DBSupplier).filter(models.DBSupplier.client_id == client_id).all():
        if norm_name(x.name) == norm_name(name):
            return x.payment_days if x.payment_days is not None else 30
    return 30


def qty_text(value) -> str:
    """A quantity as it is written in a sentence: 100, 117.6, 0.125 - not the
    float repr, which put "100.0 ordered" in front of the site engineer."""
    return ("%.3f" % float(value or 0)).rstrip("0").rstrip(".") or "0"


def inr(value) -> str:
    """A rupee figure the way it is read aloud here: 12,34,567.00.

    Indian grouping puts the first comma three from the right and every one
    after it two apart. The web formatter does this already; the server did
    not have one, so any figure the server wrote into a sentence came out as a
    bare float - "400000.0 the customer should already have paid" - which is
    the kind of thing that makes a screen look unfinished at a glance.
    """
    v = money(value)
    neg = v < 0
    whole, frac = divmod(abs(v), 1)
    digits = str(int(whole))
    if len(digits) > 3:
        head, tail = digits[:-3], digits[-3:]
        pairs = []
        while len(head) > 2:
            pairs.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pairs.insert(0, head)
        digits = ",".join(pairs + [tail])
    return "%s₹%s.%02d" % ("-" if neg else "", digits, int(round(frac * 100)))


def unit_rate(val) -> float:
    """A rate per unit, kept to four places.

    Two is enough for a sum of money and not enough for a multiplier. This
    trade quotes wire at 12.222 the metre; rounded to 12.22 and taken across
    the twelve thousand metres actually being laid, the budget walks away from
    the spreadsheet it was copied from - by six thousand rupees over one
    project, on lines that each looked right to the paisa.

    Only the multiplier is held this wide. Amounts, totals and anything that
    reaches an invoice are still money(), because those are sums of money and
    a bill cannot ask for a fraction of a paisa.
    """
    try:
        d = Decimal(str(val or 0))
    except (InvalidOperation, ValueError, TypeError):
        return 0.0
    return float(d.quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP))


def line_net_amount(qty, price, disc) -> float:
    """Amount for a single line after its percentage discount."""
    amount = float(qty or 0) * float(price or 0)
    d = float(disc or 0)
    if d:
        amount *= (1 - d / 100.0)
    return amount


def compute_invoice_totals(line_items, tax_type: str):
    """Subtotal / tax / total for a set of line items, honouring each line's own
    tax rate. `tax_type` is 'exclusive' (tax added on top), 'inclusive' (prices
    already contain tax) or anything else for no tax."""
    subtotal = 0.0
    tax = 0.0
    for item in line_items or []:
        amount = line_net_amount(
            getattr(item, "qty", None), getattr(item, "price", None), getattr(item, "disc", None)
        )
        rate = parse_tax_rate(getattr(item, "tax_rate", None))
        if tax_type == "exclusive":
            subtotal += amount
            tax += amount * rate
        elif tax_type == "inclusive":
            net = amount / (1 + rate) if rate else amount
            subtotal += net
            tax += amount - net
        else:
            subtotal += amount
    subtotal = money(subtotal)
    tax = money(tax)
    return subtotal, tax, money(subtotal + tax)


def _parse_date(value):
    """Parse a YYYY-MM-DD string, returning None when unusable."""
    if not value:
        return None
    try:
        return datetime.strptime(str(value)[:10], "%Y-%m-%d").date()
    except (ValueError, TypeError):
        return None


OPEN_INVOICE_STATUSES = ("Awaiting Payment", "Sent", "Partially Paid", "Overdue")


def invoice_overdue_days(inv, today=None) -> int:
    """Days past the due date for an unsettled invoice; 0 when not overdue."""
    if inv.status in ("Paid", "Draft", "Void"):
        return 0
    if (inv.due or 0) <= 0:
        return 0
    due = _parse_date(inv.due_date)
    if not due:
        return 0
    today = today or datetime.now().date()
    return max(0, (today - due).days)


def apply_payment_status(inv):
    """Keep status/paid/due consistent after a payment changes."""
    total = money((inv.paid or 0) + (inv.due or 0))
    if (inv.due or 0) <= 0.005 and total > 0:
        inv.due = 0.0
        inv.status = "Paid"
    elif (inv.paid or 0) > 0.005:
        inv.status = "Partially Paid"
    return inv


