@app.post("/api/wo/orders/{order_id}/cancel")
def wo_cancel(order_id: int, body: WoActionIn, request: Request,
              db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db, "subcontracts.approve")
    order = wo_or_404(db, client.id, order_id)
    if not (body.comments or "").strip():
        raise HTTPException(400, "Say why it is being cancelled.")
    wo_apply(db, client, order, "CANCEL", actor_id, actor_name, body.comments)
    db.commit()
    db.refresh(order)
    return {"order": wo_dict(db, order, detail=True),
            "message": order.wo_number + " cancelled."}


@app.post("/api/wo/orders/{order_id}/amend")
def wo_amend(order_id: int, body: WoActionIn, request: Request,
             db: Session = Depends(get_db)):
    """Supersede an order with a revision.

    The original is not edited and not deleted: it was signed, so it stays as
    it was signed. The revision is a new draft carrying everything across, and
    the two are linked so the history reads in one line.
    """
    client, actor_id, actor_name = wo_actor(request, db)
    order = wo_or_404(db, client.id, order_id)

    revision = models.DBSubcontractOrder(
        client_id=client.id, status="DRAFT",
        wo_number="%s-REV-%02d" % (
            re.sub(r"-REV-\d+$", "", order.wo_number or ""), (order.amendment_no or 0) + 1),
        amendment_no=(order.amendment_no or 0) + 1, supersedes_id=order.id,
        business_unit_id=order.business_unit_id, contractor_id=order.contractor_id,
        job_id=order.job_id, department=order.department, work_type=order.work_type,
        subject=order.subject, scope_of_work=order.scope_of_work,
        commencement_date=order.commencement_date, completion_date=order.completion_date,
        duration_months=order.duration_months,
        defect_liability_months=order.defect_liability_months,
        bank_guarantee_applicable=order.bank_guarantee_applicable,
        bank_guarantee_amount=order.bank_guarantee_amount,
        bank_guarantee_validity=order.bank_guarantee_validity,
        gst_rate=order.gst_rate, tds_rate=order.tds_rate,
        retention_percent=order.retention_percent,
        mobilization_advance_percent=order.mobilization_advance_percent,
        advance_recovery_percent=order.advance_recovery_percent,
        labour_cess_percent=order.labour_cess_percent,
        billing_cycle=order.billing_cycle, payment_days=order.payment_days,
        submitted_by=actor_id)
    db.add(revision)
    db.flush()
    wo_copy_lines(db, order, revision)
    db.flush()
    recost_order(db, revision)
    wo_apply(db, client, order, "AMEND", actor_id, actor_name,
             "Superseded by " + revision.wo_number)
    record_wo_action(db, client, revision, actor_id, actor_name, "CREATE", "",
                     "Amends " + (order.wo_number or ""))
    log_audit(db, client.id, "subcontract_amended", "subcontract_order", revision.id,
              revision.wo_number, "amends " + (order.wo_number or ""), request)
    db.commit()
    db.refresh(revision)
    return {"order": wo_dict(db, revision, detail=True),
            "message": revision.wo_number + " opened, amending " + order.wo_number + "."}


# ============================================================================
# TAKING IT AWAY
#
# Every list somebody works from is one they will eventually be asked to send
# on, print, or check against a figure from somewhere else. Without an export
# that means re-keying it into a spreadsheet, which is the habit this system
# is meant to be replacing rather than feeding.
# ============================================================================

@app.get("/api/erp/items.xlsx")
def erp_items_xlsx(request: Request, kind: str = "", q: str = "",
                   db: Session = Depends(get_db)):
    """The item master, filtered the same way the screen filters it."""
    client = require_erp_read(request, db)
    query = db.query(models.DBItem).filter(models.DBItem.client_id == client.id)
    if kind:
        query = query.filter(models.DBItem.kind == kind.upper())
    if q:
        query = query.filter(or_(models.DBItem.item_code.ilike("%" + q + "%"),
                                 models.DBItem.item_name.ilike("%" + q + "%")))
    rows = query.order_by(models.DBItem.item_code).all()
    return sheet_response(
        ["Item Code", "Item Name", "Kind", "Description", "Type",
         "Units Of Measure", "HSN Code", "Item Tax Type", "Make"],
        [[i.item_code or "", i.item_name or "", i.kind or "", i.description or "",
          i.item_type or "", i.units_of_measure or "", i.hsn_code or "",
          i.item_tax_type or "", i.make or ""] for i in rows],
        "item_master.xlsx",
        preamble=[["Item Master", "", "", "", "", "", "", "", client.company_name or ""],
                  ["%d code(s)" % len(rows) +
                   (" - %s only" % kind.upper() if kind else "")],
                  []])


@app.get("/api/erp/work-orders/{wo_id}/export.xlsx")
def erp_work_order_xlsx(wo_id: int, request: Request, db: Session = Depends(get_db)):
    """One work order: what was sold, and the budget behind it if there is one."""
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, wo_id)
    detail = work_order_to_dict(db, wo, detail=True)

    rows = [[l["fg_code"], l["item_name"], l["description"], l["uom"],
             l["qty"], l["rate"], l["amount"]] for l in detail.get("lines", [])]
    closing = [[], ["", "", "", "", "", "Order value", detail["total_value"]]]
    if detail.get("budgeted"):
        closing += [["", "", "", "", "", "Budgeted cost", detail["budget_cost"]],
                    ["", "", "", "", "", "Margin", detail["margin"]]]
        closing += [[], ["Budget - materials consumed"],
                    ["FG Code", "RM Code", "Description", "UOM", "Qty", "Rate", "Amount"]]
        closing += [[b["fg_code"], b["rm_code"], b["rm_name"], b["uom"],
                     b["qty"], b["rate"], b["amount"]] for b in detail.get("bom", [])]

    return sheet_response(
        ["FG Code", "Item Name", "Description", "UOM", "Qty", "Rate", "Amount"],
        rows, "work_order_%s.xlsx" % re.sub(r"[^A-Za-z0-9]+", "_", wo.number or ""),
        preamble=[["Work Order", "", "", "", "", "", client.company_name or ""],
                  ["No: " + (wo.number or "") + "   (" + (wo.status or "") + ")"],
                  ["Job: " + detail.get("job_name", "")],
                  ["Customer: " + detail.get("customer_name", "")],
                  ["Reference: " + (wo.reference or "")],
                  []],
        closing=closing)


@app.get("/api/purchase-orders/{po_id}/export.xlsx")
def purchase_order_xlsx(po_id: int, request: Request, db: Session = Depends(get_db)):
    """One purchase order, as sent to the supplier."""
    client = get_client_user(request, db)
    po = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.id == po_id,
        models.DBPurchaseOrder.client_id == client.id).first()
    if not po:
        raise HTTPException(404, "Purchase order not found")

    lines = db.query(models.DBPurchaseOrderLineItem).filter(
        models.DBPurchaseOrderLineItem.order_id == po.id).all()
    job = db.query(models.DBJob).filter(models.DBJob.id == po.job_id).first()

    return sheet_response(
        ["Description", "Qty", "Price", "Tax", "Amount"],
        [[l.description or "", money(l.qty), money(l.price), l.tax_rate or "",
          money((l.qty or 0) * (l.price or 0))] for l in lines],
        "purchase_order_%s.xlsx" % re.sub(r"[^A-Za-z0-9]+", "_", po.number or ""),
        preamble=[["Purchase Order", "", "", "", client.company_name or ""],
                  ["No: " + (po.number or "") + "   (" + (po.status or "") + ")"],
                  ["Supplier: " + (po.supplier_name or "")],
                  ["Job: " + (("%s %s" % (job.number, job.name)).strip() if job else "")],
                  ["Issued: " + (po.issue_date or "") +
                   ("   Needed by: " + po.needed_by if po.needed_by else "")],
                  []],
        closing=[[], ["", "", "", "Subtotal", money(po.amount)],
                 ["", "", "", "Tax", money(po.tax_amount)],
                 ["", "", "", "Total", money(po.total)]])



# ============================================================================
# WHERE THE MONEY IS, PER PROJECT
#
# Every figure in this system already exists somewhere - an order here, a bill
# there, a budget on a third screen. What nobody could do was see them on one
# line and answer the only question that matters on a running job: are we
# still making money on it.
# ============================================================================

# Contracting cost headings. A builder's costs do not sort into "office
# supplies" and "software"; they sort into who or what the money went on, and
# every cost report downstream is grouped by these.
COST_CATEGORIES = [
    ("labour", "Labour"),
    ("materials", "Materials"),
    ("subcontract", "Subcontract"),
    ("plant", "Plant & equipment"),
    ("other", "Other"),
]
COST_CATEGORY_KEYS = [c for c, _ in COST_CATEGORIES]

# Older bills carry the generic headings the app shipped with. Mapping them
# rather than migrating keeps history readable without rewriting anyone's data.
COST_CATEGORY_ALIASES = {
    "general": "other", "office": "other", "software": "other",
    "utilities": "other", "rent": "plant", "marketing": "other",
    "travel": "other", "professional": "subcontract",
    "material": "materials", "labor": "labour", "equipment": "plant",
    "hire": "plant", "sub": "subcontract",
}


def cost_category_of(raw) -> str:
    key = (raw or "").strip().lower()
    if key in COST_CATEGORY_KEYS:
        return key
    return COST_CATEGORY_ALIASES.get(key, "other")


def job_money(db, client_id, job, pre=None):
    """One project's money, from every direction it moves in.

    Three quantities, kept apart on purpose because they answer different
    questions and mixing them is how a job looks fine until it is finished:

      incurred    - bills that have arrived, plus the hours worked on site
      committed   - purchase and subcontract orders placed but not yet billed
      forecast    - what the whole job is expected to cost by the end

    A purchase order drops out of `committed` the moment a bill references it,
    so the same spend is never counted in both.
    """
    wos = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.client_id == client_id,
        models.DBWorkOrder.job_id == job.id).all()
    live_wos = [w for w in wos if (w.approval_status or "none") != "rejected"]
    wo_ids = [w.id for w in live_wos]

    sold = money(sum(w.total_value or 0 for w in live_wos))
    budgeted = money(sum(
        b.amount or 0 for b in db.query(models.DBBomLine).filter(
            models.DBBomLine.work_order_id.in_(wo_ids)).all())) if wo_ids else 0.0

    # --- what has actually been incurred ---------------------------------
    bills = db.query(models.DBBill).filter(
        models.DBBill.client_id == client_id,
        models.DBBill.job_id == job.id).all()
    real_bills = [b for b in bills
                  if (b.approval_status or "none") != "rejected"
                  and (b.status or "") != "Cancelled"]
    billed = money(sum(b.total or b.amount or 0 for b in real_bills))
    paid = money(sum(b.amount_paid or 0 for b in real_bills))
    awaiting = len([b for b in bills if (b.approval_status or "") == "pending"])

    attendance = db.query(models.DBAttendance).filter(
        models.DBAttendance.client_id == client_id,
        models.DBAttendance.job_id == job.id).all()
    rates = {}
    if attendance:
        rates = {e.id: (e.hourly_rate or 0.0) for e in db.query(models.DBEmployee).filter(
            models.DBEmployee.client_id == client_id).all()}
    labour_hours = round(sum(a.total_hours or 0.0 for a in attendance), 2)
    staff_time = money(sum((a.total_hours or 0.0) * rates.get(a.employee_id, 0.0)
                           for a in attendance))

    # What the site has actually cost, taken from the project's profit
    # account so the two screens say the same thing: this one read only
    # supplier bills and clock-in hours, and a job with a gang bill, a signed
    # diary and cement issued from the store showed nothing incurred at all.
    pre = pre or preload_pnl_for_job(db, client_id, job.id)
    pnl = project_pnl(db, client_id, job, pre=pre)
    c = pnl["cost"]
    labour = money(c["labour"] + staff_time)
    incurred = money(c["incurred"] + staff_time)

    # --- what is promised on top of it -----------------------------------
    pos = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.client_id == client_id,
        models.DBPurchaseOrder.job_id == job.id).all()
    # Once a bill names the order, the spend is in `incurred`. Leaving the
    # order in as well counted it twice and made every project look worse the
    # closer it got to finishing.
    billed_po_ids = {b.purchase_order_id for b in real_bills if b.purchase_order_id}
    open_pos = [p for p in pos
                if (p.status or "") not in ("Cancelled", "Rejected", "Closed")
                and p.id not in billed_po_ids]
    committed = money(sum(p.total or 0 for p in open_pos))

    subs = db.query(models.DBSubcontractOrder).filter(
        models.DBSubcontractOrder.client_id == client_id,
        models.DBSubcontractOrder.job_id == job.id).all()
    live_subs = [x for x in subs if (x.status or "") not in ("CANCELLED", "AMENDED")]
    # What the gangs have still to bill. Their bills are incurred already;
    # counting the whole order on top counted every rupee billed twice.
    gang_billed = {}
    for b in db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client_id,
            models.DBSubBill.job_id == job.id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).all():
        gang_billed[b.order_id] = money(gang_billed.get(b.order_id, 0.0) + (b.this_bill or 0))
    subcontracted = money(sum(max(0.0, (x.gross_amount or x.net_order_value or 0)
                                  - gang_billed.get(x.id, 0.0)) for x in live_subs))

    commitment = money(committed + subcontracted)

    # --- where it ends up -------------------------------------------------
    # Estimate at completion. Work still to come has usually not been ordered
    # yet, so where the budget is higher than everything known about, the
    # budget is the better forecast; past that point the known cost is.
    known = money(incurred + commitment)
    budget = money(job.budget or 0)
    # Two different budgets exist and they are not interchangeable. The BOM is
    # the estimate built line by line from what the work actually takes, so
    # where there is one it is the better answer; the figure typed on the
    # project form is the fallback for a job that never had a BOM.
    estimate = budgeted or budget
    forecast_cost = money(max(known, estimate)) if estimate else known

    # Percent complete measured by cost, which is what a contract with no
    # milestone schedule can actually be measured by.
    percent_complete = round(incurred / forecast_cost * 100, 1) if forecast_cost else 0.0
    cost_to_complete = money(forecast_cost - incurred)

    # --- the customer side ------------------------------------------------
    invoices = [i for i in db.query(models.DBInvoice).filter(
        models.DBInvoice.client_id == client_id,
        models.DBInvoice.job_id == job.id).all() if (i.status or "") != "Void"]
    # Certified RA bills are this business's invoices; counting only the
    # invoice module left every project "not yet invoiced".
    ra = db.query(models.DBRABill).filter(
        models.DBRABill.client_id == client_id, models.DBRABill.job_id == job.id,
        models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all()
    settled = settled_amounts(db, client_id)
    ra_received = money(sum(
        (b.net_payable or 0) if (b.status == "PAID" and not settled.get(("ra_bill", b.id)))
        else settled.get(("ra_bill", b.id), 0.0) for b in ra))
    invoiced = money(sum(invoice_total(i) for i in invoices) + sum(b.this_bill or 0 for b in ra))
    received = money(sum(i.paid or 0 for i in invoices) + ra_received)
    # What the client still owes is what each bill asks for less what came in
    # against it - the bill's net payable carries its GST, retention and TDS,
    # so "billed less received" mixed a figure before tax with cash after it.
    owed = money(sum(max(0.0, invoice_total(i) - (i.paid or 0)) for i in invoices)
                 + sum(max(0.0, (b.net_payable or 0) - settled.get(("ra_bill", b.id), 0.0))
                       for b in ra if b.status == "CERTIFIED"))

    contract_value = sold or money(job.quoted_value or 0)
    # Revenue earned by the work done, against revenue actually invoiced. A
    # job billed ahead of its progress is borrowing from its own future.
    earned = money(contract_value * percent_complete / 100) if contract_value else 0.0
    retention_percent = float(job.retention_percent or 0)
    # Released retention is no longer held: it is a claim of its own, owed
    # until it is received.
    rels = [r for r in _live_releases(db, client_id, "client") if r.job_id == job.id]
    retention_held = money(sum(invoice_total(i) for i in invoices) * retention_percent / 100
                           + sum(b.retention_amount or 0 for b in ra)
                           - sum(r.amount or 0 for r in rels))
    received = money(received + sum(settled.get(("retention_release", r.id), 0.0) for r in rels))
    owed = money(owed + sum(max(0.0, (r.net_amount or 0) - settled.get(("retention_release", r.id), 0.0))
                            for r in rels if r.status == "CERTIFIED"))

    # --- cost by heading --------------------------------------------------
    by_category = {key: 0.0 for key in COST_CATEGORY_KEYS}
    by_category["labour"] = labour
    stocked = pre.get("stocked") or {}
    for b in real_bills:
        key = cost_category_of(b.category)
        by_category[key] = money(by_category[key]
                                 + (b.total or b.amount or 0) * (1.0 - stocked.get(b.id, 0.0)))
    by_category["materials"] = money(by_category["materials"] + c["material_from_store"]
                                     - c["material_recovered_from_gangs"])
    by_category["subcontract"] = money(by_category["subcontract"] + c["subcontractors"] + subcontracted)
    by_category["plant"] = money(by_category["plant"] + c["plant"] + c["equipment"])
    for p in open_pos:
        by_category["materials"] = money(by_category["materials"] + (p.total or 0))

    return {
        "job_id": job.id, "number": job.number or "", "name": job.name or "",
        "customer_name": job.customer_name or "", "status": job.status or "",
        "quoted_value": money(job.quoted_value), "budget": budget,
        "sold": sold, "contract_value": contract_value, "budgeted_cost": budgeted,

        "committed": committed, "subcontracted": subcontracted,
        "commitment": commitment,
        "labour": labour, "labour_hours": labour_hours,
        "billed": billed, "paid": paid, "unpaid": money(billed - paid),
        "bills_awaiting_approval": awaiting,

        "incurred": incurred,
        # Kept under its old name so nothing reading this breaks, but it is now
        # everything the job has committed the business to, not just its orders.
        "cost": money(incurred + commitment),
        "forecast_cost": forecast_cost,
        "cost_to_complete": cost_to_complete,
        "percent_complete": percent_complete,

        "invoiced": invoiced, "received": received,
        "outstanding": owed,
        "retention_percent": retention_percent,
        "retention_held": retention_held,
        "earned": earned,
        # Positive means invoiced ahead of the work; negative means work done
        # that nobody has been asked to pay for yet.
        "over_billed": money(invoiced - earned),

        "margin": money(contract_value - forecast_cost),
        "margin_percent": (round((contract_value - forecast_cost) / contract_value * 100, 1)
                           if contract_value else 0.0),
        "estimate": estimate,
        "budget_variance": money(estimate - forecast_cost) if estimate else 0.0,
        "over_budget": (money(forecast_cost - estimate)
                        if estimate and forecast_cost > estimate else 0.0),

        "categories": [
            {"key": key, "label": label, "amount": money(by_category[key])}
            for key, label in COST_CATEGORIES
        ],
        "work_orders": len(wos), "purchase_orders": len(pos),
        "bills": len(bills), "subcontracts": len(subs),
    }


@app.get("/api/costs/by-project")
def costs_by_project(request: Request, db: Session = Depends(get_db)):
    """Every project on one screen, with the money on each."""
    client = require_items_access(request, db, "reports.view")
    jobs = db.query(models.DBJob).filter(
        models.DBJob.client_id == client.id).order_by(models.DBJob.id.desc()).all()
    pre = preload_pnl(db, client.id)          # once for every project, not per row
    rows = [job_money(db, client.id, j, pre=pre) for j in jobs]
    return {
        "projects": rows,
        "summary": {
            "projects": len(rows),
            "sold": money(sum(r["contract_value"] for r in rows)),
            "incurred": money(sum(r["incurred"] for r in rows)),
            "commitment": money(sum(r["commitment"] for r in rows)),
            "cost": money(sum(r["cost"] for r in rows)),
            "forecast_cost": money(sum(r["forecast_cost"] for r in rows)),
            "margin": money(sum(r["margin"] for r in rows)),
            "labour": money(sum(r["labour"] for r in rows)),
            "invoiced": money(sum(r["invoiced"] for r in rows)),
            "received": money(sum(r["received"] for r in rows)),
            "outstanding": money(sum(r["outstanding"] for r in rows)),
            "retention_held": money(sum(r["retention_held"] for r in rows)),
            "over_billed": money(sum(r["over_billed"] for r in rows)),
            "billed": money(sum(r["billed"] for r in rows)),
            "unpaid": money(sum(r["unpaid"] for r in rows)),
            "awaiting_approval": sum(r["bills_awaiting_approval"] for r in rows),
            "over_budget": len([r for r in rows if r["over_budget"] > 0]),
            "categories": [
                {"key": key, "label": label,
                 "amount": money(sum(
                     next((c["amount"] for c in r["categories"] if c["key"] == key), 0.0)
                     for r in rows))}
                for key, label in COST_CATEGORIES
            ],
        },
    }


@app.get("/api/costs/by-project/{job_id}")
def costs_for_project(job_id: int, request: Request, db: Session = Depends(get_db)):
    """One project, with the documents behind each figure.

    The totals are only worth anything if you can get from them to the papers
    they came from, so every one of them lists what it is made of.
    """
    client = require_items_access(request, db, "reports.view")
    job = job_or_404(db, client.id, job_id)
    row = job_money(db, client.id, job)

    row["work_order_list"] = [
        {"id": w.id, "number": w.number, "status": w.status or "",
         "value": money(w.total_value), "approval": w.approval_status or "none"}
        for w in db.query(models.DBWorkOrder).filter(
            models.DBWorkOrder.client_id == client.id,
            models.DBWorkOrder.job_id == job.id).all()]
    row["purchase_order_list"] = [
        {"id": p.id, "number": p.number or "", "supplier": p.supplier_name or "",
         "total": money(p.total), "status": p.status or ""}
        for p in db.query(models.DBPurchaseOrder).filter(
            models.DBPurchaseOrder.client_id == client.id,
            models.DBPurchaseOrder.job_id == job.id).all()]
    row["bill_list"] = [
        {"id": b.id, "number": b.number or "", "supplier": b.vendor_name or "",
         "total": money(b.total or b.amount), "status": b.status or "",
         "approval": b.approval_status or "none"}
        for b in db.query(models.DBBill).filter(
            models.DBBill.client_id == client.id,
            models.DBBill.job_id == job.id).all()]
    row["subcontract_list"] = [
        {"id": s.id, "number": s.wo_number or "", "status": s.status or "",
         "net": money(s.net_order_value)}
        for s in db.query(models.DBSubcontractOrder).filter(
            models.DBSubcontractOrder.client_id == client.id,
            models.DBSubcontractOrder.job_id == job.id).all()]
    return row


@app.get("/api/costs/by-project.xlsx")
def costs_by_project_xlsx(request: Request, db: Session = Depends(get_db)):
    client = require_items_access(request, db, "reports.view")
    jobs = db.query(models.DBJob).filter(
        models.DBJob.client_id == client.id).order_by(models.DBJob.id.desc()).all()
    pre = preload_pnl(db, client.id)
    rows = [job_money(db, client.id, j, pre=pre) for j in jobs]
    return sheet_response(
        ["Project", "Name", "Customer", "Sold", "Budgeted cost", "Committed",
         "Subcontracted", "Total cost", "Margin", "Margin %", "Billed", "Unpaid"],
        [[r["number"], r["name"], r["customer_name"], r["sold"], r["budgeted_cost"],
          r["committed"], r["subcontracted"], r["cost"], r["margin"],
          r["margin_percent"], r["billed"], r["unpaid"]] for r in rows],
        "cost_by_project.xlsx",
        preamble=[["Cost by project", "", "", "", "", "", "", "", "", "", "",
                   client.company_name or ""],
                  ["As at " + datetime.now().strftime("%d/%m/%Y %H:%M")], []])



# ============================================================================
# MEASUREMENT AND RUNNING ACCOUNT BILLS
#
# Work is measured on site, the measurements accumulate, and each bill claims
# the difference between what has been measured to date and what has already
# been claimed. That subtraction is the arithmetic a site office gets wrong by
# hand every month, and it is the whole reason this exists.
# ============================================================================

# ============================================================================
# GST, DONE THE WAY THE RETURN NEEDS IT
#
# The bills carried a flat tax percentage. A return does not: it wants to
# know whether the supply was inside our state - CGST and SGST, half each -
# or across a border - all of it IGST - and it wants that per rate, per
# month, with the HSN or SAC against every line. For a works contract the
# place of supply is where the property is, not where the client's head
# office sits, so the site's state is what the split is decided on.
# ============================================================================

# GST state codes: the first two digits of every GSTIN.
GST_STATES = {
    "01": "Jammu & Kashmir", "02": "Himachal Pradesh", "03": "Punjab",
    "04": "Chandigarh", "05": "Uttarakhand", "06": "Haryana", "07": "Delhi",
    "08": "Rajasthan", "09": "Uttar Pradesh", "10": "Bihar", "11": "Sikkim",
    "12": "Arunachal Pradesh", "13": "Nagaland", "14": "Manipur", "15": "Mizoram",
    "16": "Tripura", "17": "Meghalaya", "18": "Assam", "19": "West Bengal",
    "20": "Jharkhand", "21": "Odisha", "22": "Chhattisgarh", "23": "Madhya Pradesh",
    "24": "Gujarat", "26": "Dadra & Nagar Haveli and Daman & Diu", "27": "Maharashtra",
    "29": "Karnataka", "30": "Goa", "31": "Lakshadweep", "32": "Kerala",
    "33": "Tamil Nadu", "34": "Puducherry", "35": "Andaman & Nicobar",
    "36": "Telangana", "37": "Andhra Pradesh", "38": "Ladakh",
}
# Works contract services under GST.
WORKS_CONTRACT_SAC = "9954"


def state_from_gstin(gstin):
    g = (gstin or "").strip().upper()
    return g[:2] if len(g) >= 2 and g[:2].isdigit() and g[:2] in GST_STATES else ""


def split_gst(taxable, rate_percent, our_state, supply_state):
    """The one place the CGST/SGST-or-IGST decision is made.

    Same state: half and half. Different states, or either unknown: IGST -
    because a wrong IGST is a reconciliation, and a wrong CGST/SGST across a
    border is a penalty.
    """
    total = money((taxable or 0) * (rate_percent or 0) / 100.0)
    if our_state and supply_state and our_state == supply_state:
        half = money(total / 2.0)
        return {"cgst": half, "sgst": money(total - half), "igst": 0.0,
                "total": total, "intra_state": True}
    return {"cgst": 0.0, "sgst": 0.0, "igst": total, "total": total,
            "intra_state": False}


def our_state(db, client_id):
    c = db.query(models.DBClient).filter(models.DBClient.id == client_id).first()
    if not c:
        return ""
    return (c.state_code or "").strip() or state_from_gstin(c.gstin)


# The first digits of a PIN code and the GST state they lie in - only where
# the postal circle and the state are the same thing. Where a circle spans two
# states (605 is Puducherry and Tamil Nadu, 24x is Uttar Pradesh and
# Uttarakhand) nothing is guessed and the project's state has to be picked.
PIN_STATES = {"11": "07", "30": "08", "31": "08", "32": "08", "33": "08", "34": "08",
              "36": "24", "37": "24", "38": "24", "39": "24",
              "40": "27", "41": "27", "42": "27", "43": "27", "44": "27",
              "50": "36", "51": "37", "52": "37", "53": "37",
              "56": "29", "57": "29", "58": "29", "59": "29",
              "60": "33", "61": "33", "62": "33", "63": "33", "64": "33",
              "67": "32", "68": "32", "69": "32"}
PIN_EXCEPTIONS = {"403": "30", "605": ""}


def state_from_pin(text):
    """The GST state of an address, from its six-digit PIN, when that is
    certain; "" when there is no PIN or its circle crosses a state line."""
    m = re.search(r"\b(\d{6})\b", text or "")
    if not m:
        return ""
    pin = m.group(1)
    if pin[:3] in PIN_EXCEPTIONS:
        return PIN_EXCEPTIONS[pin[:3]]
    return PIN_STATES.get(pin[:2], "")


def supply_state_for_job(db, job_id):
    """Where a project's work is supplied, for the GST split.

    Projects raised from the quick-add box, or before the state could be set,
    had none - and every bill on them went out as IGST, even for a site in
    the contractor's own city. The site address usually carries a PIN that
    settles it; only when it does not is the state left unknown (and IGST,
    the safe side, applies)."""
    if not job_id:
        return ""
    j = db.query(models.DBJob).filter(models.DBJob.id == job_id).first()
    if not j:
        return ""
    return (j.state_code or "").strip() or state_from_pin(j.site_address)


class CompanyGstIn(BaseModel):
    gstin: Optional[str] = ""
    state_code: Optional[str] = ""


@app.get("/api/gst/settings")
def gst_settings(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    code = our_state(db, client.id)
    return {"gstin": client.gstin or "", "state_code": code,
            "state": GST_STATES.get(code, ""), "states": GST_STATES,
            "works_contract_sac": WORKS_CONTRACT_SAC}


@app.put("/api/gst/settings")
def set_gst_settings(body: CompanyGstIn, request: Request, db: Session = Depends(get_db)):
    """Our GSTIN. The state falls out of it, so it cannot disagree with it."""
    client = get_client_user(request, db)
    g = (body.gstin or "").strip().upper()
    if g and (len(g) != 15 or not g[:2].isdigit() or g[:2] not in GST_STATES):
        raise HTTPException(400, "A GSTIN is fifteen characters and starts with a "
                                 "state code - %s is not one." % (g[:2] or "that"))
    client.gstin = g
    client.state_code = state_from_gstin(g) or (body.state_code or "").strip()
    if client.state_code and client.state_code not in GST_STATES:
        raise HTTPException(400, "Not a GST state code: %s" % client.state_code)
    db.commit()
    return {"ok": True, "gstin": client.gstin, "state_code": client.state_code,
            "state": GST_STATES.get(client.state_code, "")}


class JobStateIn(BaseModel):
    state_code: str


@app.put("/api/jobs/{job_id}/place-of-supply")
def set_job_state(job_id: int, body: JobStateIn, request: Request,
                  db: Session = Depends(get_db)):
    client = get_client_user(request, db)
    job = job_or_404(db, client.id, job_id)
    code = (body.state_code or "").strip()
    if code and code not in GST_STATES:
        raise HTTPException(400, "Not a GST state code: %s" % code)
    job.state_code = code
    db.commit()
    return {"ok": True, "state_code": code, "state": GST_STATES.get(code, "")}


# --- The summaries a return is filed from ------------------------------------

def _month_key(d):
    return (d or "")[:7]


@app.get("/api/gst/outward")
def gst_outward(request: Request, date_from: str = "", date_to: str = "",
                db: Session = Depends(get_db)):
    """What we charged, by month and rate, split the way GSTR-1 wants it.

    Outward supplies are the client's certified RA bills and the invoices.
    Grouped by month because that is how the return is filed, and by rate
    because that is how the return's tables are laid out.
    """
    client = require_erp_read(request, db)
    rows = []
    for b in db.query(models.DBRABill).filter(
            models.DBRABill.client_id == client.id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all():
        on = (b.certified_at or b.created_at or "")[:10]
        if date_from and on < date_from:
            continue
        if date_to and on > date_to:
            continue
        job = db.query(models.DBJob).filter(models.DBJob.id == b.job_id).first()
        taxable = money(b.this_bill - (b.retention_amount or 0) -
                        (b.advance_recovery or 0) - (b.other_deductions or 0))
        rows.append({
            "kind": "RA bill", "number": b.number or "", "date": on,
            "party": job.customer_name if job else "", "project": job.name if job else "",
            "place_of_supply": b.place_of_supply or "",
            "sac": WORKS_CONTRACT_SAC, "rate": b.tax_percent or 0,
            "taxable": taxable, "cgst": money(b.cgst_amount), "sgst": money(b.sgst_amount),
            "igst": money(b.igst_amount), "tax": money(b.tax_amount),
            "total": money(taxable + (b.tax_amount or 0)),
        })
    rows.extend(release_gst_rows(db, client.id, "client", date_from, date_to))
    irns = {r.doc_number: r.irn for r in db.query(models.DBEinvoiceIrn).filter(
        models.DBEinvoiceIrn.client_id == client.id, models.DBEinvoiceIrn.status == "ACTIVE").all()}
    for r in rows:
        r["irn"] = irns.get(r["number"], "")
    by_month, by_rate = {}, {}
    for r in rows:
        m = by_month.setdefault(_month_key(r["date"]), {
            "month": _month_key(r["date"]), "taxable": 0.0, "cgst": 0.0, "sgst": 0.0,
            "igst": 0.0, "tax": 0.0, "bills": 0})
        for k in ("taxable", "cgst", "sgst", "igst", "tax"):
            m[k] = money(m[k] + r[k])
        m["bills"] += 1
        rt = by_rate.setdefault(r["rate"], {"rate": r["rate"], "taxable": 0.0, "tax": 0.0})
        rt["taxable"] = money(rt["taxable"] + r["taxable"])
        rt["tax"] = money(rt["tax"] + r["tax"])
    rows.sort(key=lambda r: r["date"], reverse=True)
    return {
        "supplies": rows,
        "by_month": sorted(by_month.values(), key=lambda m: m["month"], reverse=True),
        "by_rate": sorted(by_rate.values(), key=lambda r: r["rate"]),
        "summary": {
            "taxable": money(sum(r["taxable"] for r in rows)),
            "cgst": money(sum(r["cgst"] for r in rows)),
            "sgst": money(sum(r["sgst"] for r in rows)),
            "igst": money(sum(r["igst"] for r in rows)),
            "tax": money(sum(r["tax"] for r in rows)),
            "bills": len(rows),
            "missing_place_of_supply": len([r for r in rows if not r["place_of_supply"]]),
            "without_irn": len([r for r in rows if not r["irn"]]),
        },
    }


@app.get("/api/gst/inward")
def gst_inward(request: Request, date_from: str = "", date_to: str = "",
               db: Session = Depends(get_db)):
    """What we were charged - the input credit side. Subcontractor bills and
    supplier bills."""
    client = require_erp_read(request, db)
    rows = []
    contractors = {c.id: c for c in db.query(models.DBContractor).filter(
        models.DBContractor.client_id == client.id).all()}
    for b in db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client.id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).all():
        on = (b.certified_at or b.created_at or "")[:10]
        if date_from and on < date_from:
            continue
        if date_to and on > date_to:
            continue
        con = contractors.get(b.contractor_id)
        taxable = money(b.this_bill - (b.retention_amount or 0) -
                        (b.advance_recovery or 0) - (b.other_deductions or 0))
        rows.append({
            "kind": "Subcontractor bill", "number": b.number or "", "date": on,
            "party": con.company_name if con else "",
            "party_gstin": (con.gst_number or "") if con else "",
            "sac": WORKS_CONTRACT_SAC, "rate": b.gst_percent or 0,
            "taxable": taxable, "cgst": money(b.cgst_amount), "sgst": money(b.sgst_amount),
            "igst": money(b.igst_amount), "tax": money(b.gst_amount),
        })
    rows.extend(release_gst_rows(db, client.id, "contractor", date_from, date_to))
    # The supplier's GSTIN is on the supplier list; the bill only has a name.
    # Without it every supplier bill sat in the register with no GSTIN and
    # its tax in one lump - nothing to reconcile the input credit against.
    supplier_gstin = {norm_name(x.name): (x.gstin or "").strip().upper()
                      for x in db.query(models.DBSupplier).filter(
                          models.DBSupplier.client_id == client.id).all()}
    home = our_state(db, client.id)
    for b in db.query(models.DBBill).filter(
            models.DBBill.client_id == client.id).all():
        if (b.status or "") in ("Cancelled", "Rejected", "Draft"):
            continue
        on = (b.issue_date or b.created_at or "")[:10]
        if date_from and on < date_from:
            continue
        if date_to and on > date_to:
            continue
        gstin = supplier_gstin.get(norm_name(b.vendor_name), "")
        tax = money(b.tax_amount)
        taxable = money(b.amount)
        # Same state as us: CGST and SGST. Another state, or a supplier whose
        # state is not known: IGST, the side a mistake is cheaper on.
        intra = bool(home and gstin and state_from_gstin(gstin) == home)
        half = money(tax / 2.0) if intra else 0.0
        rows.append({
            "kind": "Supplier bill", "number": b.number or "", "date": on,
            "party": b.vendor_name or "", "party_gstin": gstin,
            "sac": "", "rate": round(tax / taxable * 100.0, 2) if taxable else 0,
            "taxable": taxable, "cgst": half, "sgst": money(tax - half) if intra else 0.0,
            "igst": 0.0 if intra else tax, "tax": tax,
        })
    rows.sort(key=lambda r: r["date"], reverse=True)
    return {
        "supplies": rows,
        "summary": {
            "taxable": money(sum(r["taxable"] for r in rows)),
            "tax": money(sum(r["tax"] for r in rows)),
            "cgst": money(sum(r["cgst"] for r in rows)),
            "sgst": money(sum(r["sgst"] for r in rows)),
            "igst": money(sum(r["igst"] for r in rows)),
            "bills": len(rows),
            # Input credit needs the supplier's GSTIN on the bill. Without it
            # the credit is at risk, so say how many are missing.
            "missing_party_gstin": len([r for r in rows if not r["party_gstin"]]),
        },
    }


@app.get("/api/gst/outward.xlsx")
def gst_outward_export(request: Request, date_from: str = "", date_to: str = "",
                       db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    d = gst_outward(request, date_from, date_to, db)
    rows = [(r["date"], r["number"], r["party"], r["project"], r["place_of_supply"],
             r["sac"], r["rate"], r["taxable"], r["cgst"], r["sgst"], r["igst"],
             r["tax"], r["total"]) for r in d["supplies"]]
    s = d["summary"]
    return sheet_response(
        ("Date", "Bill", "Client", "Project", "Place of supply", "SAC", "Rate %",
         "Taxable", "CGST", "SGST", "IGST", "Tax", "Total"),
        rows, "gst_outward.xlsx",
        preamble=[("OUTWARD SUPPLIES", client.company_name or ""),
                  ("GSTIN", client.gstin or "", "Period",
                   "%s to %s" % (date_from or "start", date_to or "today")), ()],
        closing=[(), ("Total", "", "", "", "", "", "", s["taxable"], s["cgst"],
                      s["sgst"], s["igst"], s["tax"])])


RA_TRANSITIONS = {
    "DRAFT":     {"SUBMIT": "SUBMITTED", "CANCEL": "CANCELLED"},
    "SUBMITTED": {"CERTIFY": "CERTIFIED", "REJECT": "DRAFT", "CANCEL": "CANCELLED"},
    "CERTIFIED": {"PAY": "PAID", "CANCEL": "CANCELLED"},
    "PAID":      {},
    "CANCELLED": {},
}
# Only a draft may be recomputed. Once it has been submitted the quantities are
# what somebody is being asked to certify, and a bill that changes underneath
# an approver is worse than no bill.
RA_EDITABLE = ("DRAFT",)


def measured_to_date(db, work_order_id):
    """Quantity measured against each line, summed over the whole book."""
    totals = {}
    for m in db.query(models.DBMeasurement).filter(
            models.DBMeasurement.work_order_id == work_order_id).all():
        totals[m.line_id] = totals.get(m.line_id, 0.0) + (m.quantity or 0.0)
    return totals


def measured_and_billed_for_all(db, client_id):
    """Measured and billed quantity per line, across every order at once.

    The dashboard used to ask this two queries at a time per order. For a
    hundred orders that was two hundred queries before it had drawn a single
    number; now it is two.
    """
    from sqlalchemy import func
    measured = {}
    for line_id, qty in db.query(models.DBMeasurement.line_id,
                                 func.sum(models.DBMeasurement.quantity)).filter(
            models.DBMeasurement.client_id == client_id).group_by(
                models.DBMeasurement.line_id).all():
        measured[line_id] = float(qty or 0.0)
    billed = {}
    live_ids = [b.id for b in db.query(models.DBRABill.id).filter(
        models.DBRABill.client_id == client_id,
        models.DBRABill.status != "CANCELLED").all()]
    if live_ids:
        for line_id, qty in db.query(models.DBRABillLine.line_id,
                                     func.sum(models.DBRABillLine.this_bill_qty)).filter(
                models.DBRABillLine.ra_bill_id.in_(live_ids)).group_by(
                    models.DBRABillLine.line_id).all():
            billed[line_id] = float(qty or 0.0)
    return measured, billed


def billed_qty_to_date(db, work_order_id, exclude_bill_id=None):
    """Quantity already claimed on earlier bills.

    A cancelled bill claimed nothing, so it must not hold quantity back from
    the next one - that is how work gets measured, cancelled, and then never
    paid for.
    """
    live = db.query(models.DBRABill).filter(
        models.DBRABill.work_order_id == work_order_id,
        models.DBRABill.status != "CANCELLED").all()
    ids = [b.id for b in live if b.id != exclude_bill_id]
    totals = {}
    if not ids:
        return totals
    for l in db.query(models.DBRABillLine).filter(
            models.DBRABillLine.ra_bill_id.in_(ids)).all():
        totals[l.line_id] = totals.get(l.line_id, 0.0) + (l.this_bill_qty or 0.0)
    return totals


def claimable_lines(db, work_order, exclude_bill_id=None):
    """Each ordered line with something measured that no live bill has claimed.

    Returned as (position, line, measured, already billed, this claim) so the
    caller can build rows from it without repeating the subtraction, which is
    the one piece of arithmetic in this module that must not be written twice.
    """
    measured = measured_to_date(db, work_order.id)
    billed = billed_qty_to_date(db, work_order.id, exclude_bill_id=exclude_bill_id)
    out = []
    for index, l in enumerate(db.query(models.DBWorkOrderLine).filter(
            models.DBWorkOrderLine.work_order_id == work_order.id).all()):
        done = money(measured.get(l.id, 0.0))
        already = money(billed.get(l.id, 0.0))
        this = money(done - already)
        if this <= 0:                     # nothing new measured on this line
            continue
        out.append((index, l, done, already, this))
    return out


def write_ra_bill_lines(db, bill, claimable):
    """Replace a bill's lines with what it may claim now."""
    db.query(models.DBRABillLine).filter(
        models.DBRABillLine.ra_bill_id == bill.id).delete()
    for index, l, done, already, this in claimable:
        db.add(models.DBRABillLine(
            ra_bill_id=bill.id, line_id=l.id, fg_code=l.fg_code or "",
            description=l.description or l.item_name or "", uom=l.uom or "",
            ordered_qty=money(l.qty), measured_to_date=done,
            previously_billed_qty=already, this_bill_qty=this,
            rate=unit_rate(l.rate), amount=money(this * unit_rate(l.rate)),
            display_order=index))
    db.flush()
    return recost_ra_bill(db, bill)


def ra_bill_or_404(db, client_id, bill_id):
    row = db.query(models.DBRABill).filter(
        models.DBRABill.id == bill_id,
        models.DBRABill.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Bill not found")
    return row


def recost_ra_bill(db, bill):
    """Total the lines, then apply the deductions in the order they are made.

    Retention comes off the work, tax goes on top of it, and TDS is withheld
    from the lot. Getting that order wrong is worth real money on a large
    bill, so it is written once, here.
    """
    lines = db.query(models.DBRABillLine).filter(
        models.DBRABillLine.ra_bill_id == bill.id).all()
    this_bill = money(sum(l.amount or 0 for l in lines))

    bill.this_bill = this_bill
    bill.gross_to_date = money(bill.previously_billed + this_bill)
    bill.retention_amount = money(this_bill * (bill.retention_percent or 0) / 100.0)

    after_retention = money(this_bill - bill.retention_amount -
                            (bill.advance_recovery or 0) - (bill.other_deductions or 0))
    # Split the way the return needs it. Place of supply for a works contract
    # is the site, so the job's state is what our state is compared with.
    supply = supply_state_for_job(db, bill.job_id)
    gst = split_gst(after_retention, bill.tax_percent or 0,
                    our_state(db, bill.client_id), supply)
    bill.tax_amount = gst["total"]
    bill.cgst_amount, bill.sgst_amount, bill.igst_amount = gst["cgst"], gst["sgst"], gst["igst"]
    bill.place_of_supply = supply
    bill.tds_amount = money(this_bill * (bill.tds_percent or 0) / 100.0)
    bill.net_payable = money(after_retention + bill.tax_amount - bill.tds_amount)
    bill.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return bill


def company_address(db, client):
    """The company's address: the record, else what Settings holds (companies
    that saved it there before Settings wrote through to the record)."""
    if client and (client.address or "").strip():
        return client.address
    row = db.query(models.DBSettings).filter(models.DBSettings.client_id == client.id,
                                             models.DBSettings.key == "company_address").first() if client else None
    return (row.value if row else "") or ""


def our_party(db, client_id):
    c = db.query(models.DBClient).filter(models.DBClient.id == client_id).first()
    if not c:
        return {}
    return {"name": c.company_name or "", "gstin": c.gstin or "",
            "address": company_address(db, c), "phone": c.phone_number or "",
            "email": c.email or "", "logo_url": c.logo_url or ""}


def ra_bill_dict(db, bill, detail=False):
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == bill.work_order_id).first()
    job = db.query(models.DBJob).filter(models.DBJob.id == bill.job_id).first()
    row = {
        "id": bill.id, "number": bill.number or "", "sequence": bill.sequence or 1,
        "work_order_id": bill.work_order_id,
        "work_order": wo.number if wo else "",
        "job_id": bill.job_id, "project": ("%s %s" % (job.number, job.name)).strip() if job else "",
        "status": bill.status or "DRAFT",
        "period_from": bill.period_from or "", "period_to": bill.period_to or "",
        "gross_to_date": money(bill.gross_to_date),
        "previously_billed": money(bill.previously_billed),
        "this_bill": money(bill.this_bill),
        "retention_percent": bill.retention_percent or 0,
        "retention_amount": money(bill.retention_amount),
        "advance_recovery": money(bill.advance_recovery),
        "other_deductions": money(bill.other_deductions),
        "deduction_notes": bill.deduction_notes or "",
        "tax_percent": bill.tax_percent or 0, "tax_amount": money(bill.tax_amount),
        "cgst_amount": money(bill.cgst_amount), "sgst_amount": money(bill.sgst_amount),
        "igst_amount": money(bill.igst_amount), "place_of_supply": bill.place_of_supply or "",
        "tds_percent": bill.tds_percent or 0, "tds_amount": money(bill.tds_amount),
        "net_payable": money(bill.net_payable),
        "certified_by_name": bill.certified_by_name or "",
        "certified_at": bill.certified_at or "", "paid_at": bill.paid_at or "",
        "remarks": bill.remarks or "",
        "editable": (bill.status or "DRAFT") in RA_EDITABLE,
        "actions": sorted(RA_TRANSITIONS.get(bill.status or "DRAFT", {}).keys()),
        "created_at": bill.created_at or "",
    }
    if detail:
        row["lines"] = [{
            "id": l.id, "line_id": l.line_id, "fg_code": l.fg_code or "",
            "description": (l.description or "").split("\n")[0],
            "uom": l.uom or "", "ordered_qty": money(l.ordered_qty),
            "measured_to_date": money(l.measured_to_date),
            "previously_billed_qty": money(l.previously_billed_qty),
            "this_bill_qty": money(l.this_bill_qty),
            "rate": unit_rate(l.rate), "amount": money(l.amount),
            "upto_date_amount": money(money(l.measured_to_date) * unit_rate(l.rate)),
        } for l in db.query(models.DBRABillLine).filter(
            models.DBRABillLine.ra_bill_id == bill.id).order_by(
                models.DBRABillLine.display_order, models.DBRABillLine.id).all()]
        # What the printed bill needs beyond the figures: who it is from, who
        # it is to, where the work is, and the amount stated twice.
        row["our"] = our_party(db, bill.client_id)
        row["client_party"] = {"name": job.customer_name if job else "",
                               "site": job.site_address if job else ""}
        row["place_of_supply_name"] = GST_STATES.get(bill.place_of_supply or "", "")
        row["amount_in_words"] = amount_in_words(bill.net_payable)
        row["work_order_detail"] = ({"number": wo.number, "date": wo.order_date or "",
                                     "reference": wo.reference or "",
                                     "value": money(wo.total_value)} if wo else {})
        row["einvoice"] = irn_brief(db, bill.client_id, "ra_bill", bill.id)
    return row


# --- The measurement book ---------------------------------------------------

class DimensionIn(BaseModel):
    """One line of the book: what, how many, how long, how wide, how deep."""
    particulars: Optional[str] = ""
    nos: Optional[float] = None
    length: Optional[float] = None
    breadth: Optional[float] = None
    depth: Optional[float] = None
    deduct: Optional[bool] = False


class MeasurementIn(BaseModel):
    line_id: int
    # The total, when it is typed as one. Ignored when dimensions are given,
    # because then the total is what the dimensions come to.
    quantity: Optional[float] = 0
    dimensions: Optional[List[DimensionIn]] = None
    measured_on: Optional[str] = ""
    mb_ref: Optional[str] = ""
    remarks: Optional[str] = ""
    witnessed_by: Optional[str] = ""


def dimension_quantity(d):
    """No x L x B x D, using only the dimensions that were given.

    A blank dimension is one that does not apply - an area has no depth, a
    count has no length - not a zero. A zero that was typed is a zero: it is
    a line that measures nothing, and it is refused below rather than
    silently multiplied away.
    """
    given = [v for v in (d.length, d.breadth, d.depth) if v is not None]
    qty = float(d.nos) if d.nos is not None else 1.0
    for v in given:
        qty *= float(v)
    return round(qty, 3)


def dimension_total(dims):
    """What the dimension lines come to, signed, having checked each one.

    A row with no figures on it is a row somebody meant to fill in, and a
    negative figure is a deduction written the wrong way; both are refused
    rather than quietly multiplied into the total.
    """
    total = 0.0
    for index, d in enumerate(dims or []):
        if all(v is None for v in (d.nos, d.length, d.breadth, d.depth)):
            raise HTTPException(400, "Dimension line %d has no figures on it." % (index + 1))
        for name, v in (("nos", d.nos), ("length", d.length),
                        ("breadth", d.breadth), ("depth", d.depth)):
            if v is not None and v < 0:
                raise HTTPException(400, "Dimension line %d: %s cannot be negative. "
                                         "Mark the line as a deduction instead."
                                         % (index + 1, name))
        qty = dimension_quantity(d)
        if not qty:
            raise HTTPException(400, "Dimension line %d comes to nothing." % (index + 1))
        total += -qty if d.deduct else qty
    return round(total, 3)


def write_dimensions(db, client_id, dims, measurement_id=None, sub_measurement_id=None):
    """The dimension lines, written against the entry they belong to."""
    for index, d in enumerate(dims or []):
        qty = dimension_quantity(d)
        db.add(models.DBMeasurementDimension(
            client_id=client_id, measurement_id=measurement_id,
            sub_measurement_id=sub_measurement_id,
            particulars=(d.particulars or "").strip(), nos=d.nos, length=d.length,
            breadth=d.breadth, depth=d.depth, deduct=bool(d.deduct),
            quantity=-qty if d.deduct else qty, display_order=index))


def dimensions_for(db, entry_ids, column):
    """The dimension lines of many entries in one query, keyed by entry."""
    out = {}
    if not entry_ids:
        return out
    for d in db.query(models.DBMeasurementDimension).filter(
            column.in_(entry_ids)).order_by(
                models.DBMeasurementDimension.display_order,
                models.DBMeasurementDimension.id).all():
        out.setdefault(getattr(d, column.key), []).append({
            "particulars": d.particulars or "", "nos": d.nos, "length": d.length,
            "breadth": d.breadth, "depth": d.depth, "deduct": bool(d.deduct),
            "quantity": d.quantity or 0,
        })
    return out


@app.get("/api/mb/{work_order_id}")
def measurement_book(work_order_id: int, request: Request,
                     db: Session = Depends(get_db)):
    """Every ordered line, with what has been measured and what is left.

    The balance is the number somebody on site actually wants: how much of
    this item is still to do.
    """
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, work_order_id)
    measured = measured_to_date(db, wo.id)
    billed = billed_qty_to_date(db, wo.id)

    lines = []
    for l in db.query(models.DBWorkOrderLine).filter(
            models.DBWorkOrderLine.work_order_id == wo.id).all():
        done = money(measured.get(l.id, 0.0))
        claimed = money(billed.get(l.id, 0.0))
        lines.append({
            "line_id": l.id, "fg_code": l.fg_code or "",
            "description": (l.description or l.item_name or "").split("\n")[0],
            "uom": l.uom or "", "ordered_qty": money(l.qty),
            "rate": unit_rate(l.rate),
            "measured_to_date": done, "billed_to_date": claimed,
            "unbilled": money(done - claimed),
            "balance_to_measure": money(money(l.qty) - done),
            "percent_measured": round(done / l.qty * 100, 1) if l.qty else 0.0,
            "over_measured": money(done - money(l.qty)) if done > money(l.qty) else 0.0,
        })

    rows = db.query(models.DBMeasurement).filter(
        models.DBMeasurement.work_order_id == wo.id).order_by(
            models.DBMeasurement.id.desc()).limit(400).all()
    dims = dimensions_for(db, [m.id for m in rows],
                          models.DBMeasurementDimension.measurement_id)
    entries = [{
        "id": m.id, "line_id": m.line_id, "fg_code": m.fg_code or "",
        "measured_on": m.measured_on or "", "quantity": money(m.quantity),
        "mb_ref": m.mb_ref or "", "remarks": m.remarks or "",
        "recorded_by_name": m.recorded_by_name or "",
        "witnessed_by": m.witnessed_by or "",
        "billed": bool(m.ra_bill_id), "created_at": m.created_at or "",
        "dimensions": dims.get(m.id, []),
    } for m in rows]

    return {
        "work_order": work_order_to_dict(db, wo),
        "lines": lines, "entries": entries,
        "summary": {
            "ordered_value": money(wo.total_value),
            "measured_value": money(sum(l["measured_to_date"] * l["rate"] for l in lines)),
            "unbilled_value": money(sum(l["unbilled"] * l["rate"] for l in lines)),
            "lines_over_measured": len([l for l in lines if l["over_measured"] > 0]),
        },
    }


@app.post("/api/mb/{work_order_id}/entries")
def record_measurement(work_order_id: int, body: MeasurementIn, request: Request,
                       db: Session = Depends(get_db)):
    """Write one entry into the book."""
    client, actor_id, actor_name = wo_actor(request, db)
    wo = work_order_or_404(db, client.id, work_order_id)
    if (wo.status or "") == "Draft":
        raise HTTPException(
            409, "Nothing is measured against an order that has not been placed.")

    line = db.query(models.DBWorkOrderLine).filter(
        models.DBWorkOrderLine.id == body.line_id,
        models.DBWorkOrderLine.work_order_id == wo.id).first()
    if not line:
        raise HTTPException(404, "That line is not on this order")
    # Dimensions, where given, are the measurement; the total is their sum.
    # A bare total is still accepted - a count of manholes has no dimensions.
    quantity = money(body.quantity or 0)
    if body.dimensions:
        quantity = money(dimension_total(body.dimensions))
    if not quantity:
        raise HTTPException(400, "A measurement of nothing is not a measurement")

    entry = models.DBMeasurement(
        client_id=client.id, work_order_id=wo.id, line_id=line.id,
        fg_code=line.fg_code or "", quantity=quantity,
        measured_on=(body.measured_on or datetime.now().strftime("%Y-%m-%d")),
        mb_ref=(body.mb_ref or "").strip(), remarks=(body.remarks or "").strip(),
        witnessed_by=(body.witnessed_by or "").strip(),
        recorded_by=actor_id, recorded_by_name=actor_name)
    db.add(entry)
    db.flush()
    write_dimensions(db, client.id, body.dimensions, measurement_id=entry.id)
    log_audit(db, client.id, "measurement_recorded", "work_order", wo.id, wo.number,
              "%s %s %s" % (line.fg_code, quantity, line.uom or ""), request)
    db.commit()

    measured = money(measured_to_date(db, wo.id).get(line.id, 0.0))
    ordered = money(line.qty)
    return {
        "ok": True, "measured_to_date": measured,
        "balance_to_measure": money(ordered - measured),
        # Not refused: site conditions genuinely differ from the schedule, and
        # a variation is agreed afterwards. Said plainly so nobody bills past
        # the order without knowing they have.
        "over_measured": money(measured - ordered) if measured > ordered else 0.0,
        "message": ("Recorded. %s measured against %s of %s ordered."
                    % (qty_text(measured), line.fg_code, qty_text(ordered))),
    }


@app.delete("/api/mb/entries/{entry_id}")
def delete_measurement(entry_id: int, request: Request, db: Session = Depends(get_db)):
    """Only while it is unbilled. Once claimed it is part of a bill's history."""
    client, actor_id, actor_name = wo_actor(request, db)
    entry = db.query(models.DBMeasurement).filter(
        models.DBMeasurement.id == entry_id,
        models.DBMeasurement.client_id == client.id).first()
    if not entry:
        raise HTTPException(404, "Entry not found")
    if entry.ra_bill_id:
        raise HTTPException(
            409, "This measurement has been billed. Record a correcting entry "
                 "instead - a book that can be rubbed out is not a record.")
    db.query(models.DBMeasurementDimension).filter(
        models.DBMeasurementDimension.measurement_id == entry.id).delete()
    db.delete(entry)
    db.commit()
    return {"ok": True, "message": "Entry removed."}


# --- Running account bills --------------------------------------------------

class RABillIn(BaseModel):
    work_order_id: int
    period_from: Optional[str] = ""
    period_to: Optional[str] = ""
    retention_percent: Optional[float] = 5.0
    advance_recovery: Optional[float] = 0.0
    other_deductions: Optional[float] = 0.0
    deduction_notes: Optional[str] = ""
    tax_percent: Optional[float] = 18.0
    tds_percent: Optional[float] = 1.0


class RAActionIn(BaseModel):
    comments: Optional[str] = ""


@app.post("/api/ra-bills")
def raise_ra_bill(body: RABillIn, request: Request, db: Session = Depends(get_db)):
    """Draw up the next bill on an order.

    Nothing is typed. The bill is what has been measured to date minus what
    earlier bills already claimed, which is the one calculation nobody should
    be doing on paper.
    """
    client, actor_id, actor_name = wo_actor(request, db)
    wo = work_order_or_404(db, client.id, body.work_order_id)
    if (wo.status or "") == "Draft":
        raise HTTPException(409, "Place the order before billing against it.")

    open_bill = db.query(models.DBRABill).filter(
        models.DBRABill.work_order_id == wo.id,
        models.DBRABill.status.in_(("DRAFT", "SUBMITTED"))).first()
    if open_bill:
        raise HTTPException(
            409, "%s is still open on this order. Finish or cancel it before "
                 "raising another - two live bills claiming the same "
                 "measurements is how work gets paid for twice." % open_bill.number)

    measured = measured_to_date(db, wo.id)
    billed = billed_qty_to_date(db, wo.id)
    lines = db.query(models.DBWorkOrderLine).filter(
        models.DBWorkOrderLine.work_order_id == wo.id).all()

    claimable = claimable_lines(db, wo)
    if not claimable:
        raise HTTPException(
            409, "Nothing has been measured since the last bill. Record the "
                 "work in the measurement book first.")

    seq = db.query(models.DBRABill).filter(
        models.DBRABill.work_order_id == wo.id).count() + 1
    bill = models.DBRABill(
        client_id=client.id, work_order_id=wo.id, job_id=wo.job_id,
        number="%s/RA-%02d" % (wo.number or "WO", seq), sequence=seq,
        period_from=(body.period_from or "").strip(),
        period_to=(body.period_to or datetime.now().strftime("%Y-%m-%d")),
        status="DRAFT",
        previously_billed=money(sum(
            money(billed.get(l.id, 0.0)) * unit_rate(l.rate) for l in lines)),
        retention_percent=body.retention_percent if body.retention_percent is not None else 5.0,
        advance_recovery=money(body.advance_recovery or 0),
        other_deductions=money(body.other_deductions or 0),
        deduction_notes=(body.deduction_notes or "").strip(),
        tax_percent=body.tax_percent if body.tax_percent is not None else 18.0,
        tds_percent=body.tds_percent if body.tds_percent is not None else 1.0)
    db.add(bill)
    db.flush()

    write_ra_bill_lines(db, bill, claimable)
    log_audit(db, client.id, "ra_bill_raised", "ra_bill", bill.id, bill.number,
              "%s, %d line(s)" % (wo.number, len(claimable)), request)
    db.commit()
    db.refresh(bill)
    return {"bill": ra_bill_dict(db, bill, detail=True),
            "message": "%s drawn up for %s." % (bill.number, inr(bill.this_bill))}


@app.get("/api/ra-bills")
def list_ra_bills(request: Request, work_order_id: int = 0, status: str = "",
                  db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBRABill).filter(models.DBRABill.client_id == client.id)
    if work_order_id:
        q = q.filter(models.DBRABill.work_order_id == work_order_id)
    if status:
        q = q.filter(models.DBRABill.status == status.upper())
    rows = [ra_bill_dict(db, b) for b in q.order_by(models.DBRABill.id.desc()).limit(300).all()]
    live = [r for r in rows if r["status"] not in ("CANCELLED",)]
    return {
        "bills": rows,
        "summary": {
            "bills": len(rows),
            "awaiting_certification": len([r for r in rows if r["status"] == "SUBMITTED"]),
            "certified_unpaid": money(sum(r["net_payable"] for r in rows
                                          if r["status"] == "CERTIFIED")),
            "claimed": money(sum(r["this_bill"] for r in live)),
            "retention_held": money(sum(r["retention_amount"] for r in live)),
            "paid": money(sum(r["net_payable"] for r in rows if r["status"] == "PAID")),
        },
    }


@app.get("/api/ra-bills/{bill_id}")
def get_ra_bill(bill_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return {"bill": ra_bill_dict(db, ra_bill_or_404(db, client.id, bill_id), detail=True)}


@app.put("/api/ra-bills/{bill_id}")
def update_ra_bill(bill_id: int, body: RABillIn, request: Request,
                   db: Session = Depends(get_db)):
    """The deductions are a judgement; the quantities are not, so only the
    deductions can be changed here."""
    client, actor_id, actor_name = wo_actor(request, db)
    bill = ra_bill_or_404(db, client.id, bill_id)
    if bill.status not in RA_EDITABLE:
        raise HTTPException(
            409, "%s is %s and cannot be changed." % (bill.number, bill.status.lower()))
    if body.retention_percent is not None:
        bill.retention_percent = body.retention_percent
    if body.tax_percent is not None:
        bill.tax_percent = body.tax_percent
    if body.tds_percent is not None:
        bill.tds_percent = body.tds_percent
    bill.advance_recovery = money(body.advance_recovery or 0)
    bill.other_deductions = money(body.other_deductions or 0)
    bill.deduction_notes = (body.deduction_notes or "").strip()
    bill.period_from = (body.period_from or bill.period_from or "").strip()
    bill.period_to = (body.period_to or bill.period_to or "").strip()
    recost_ra_bill(db, bill)
    db.commit()
    db.refresh(bill)
    return {"bill": ra_bill_dict(db, bill, detail=True), "message": "Saved."}


def ra_apply(db, client, bill, action, actor_id, actor_name, comments=""):
    """One door for every state change on a bill."""
    was = bill.status or "DRAFT"
    allowed = RA_TRANSITIONS.get(was, {})
    if action not in allowed:
        raise HTTPException(
            409, "%s is %s; it cannot be %s from there." %
                 (bill.number, was.lower(),
                  {"SUBMIT": "submitted", "CERTIFY": "certified", "REJECT": "sent back",
                   "PAY": "paid", "CANCEL": "cancelled"}.get(action, action.lower())))
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    if action == "SUBMIT":
        # Redrawn from the book as it stands, because a draft can sit for days
        # while the site corrects what it measured. Submitting the figures the
        # draft was born with would send an approver a claim for work the book
        # no longer says was done.
        wo = db.query(models.DBWorkOrder).filter(
            models.DBWorkOrder.id == bill.work_order_id).first()
        if wo:
            write_ra_bill_lines(db, bill, claimable_lines(
                db, wo, exclude_bill_id=bill.id))
        if money(bill.this_bill) <= 0:
            raise HTTPException(
                400, "There is nothing left to claim - the measurements behind "
                     "this bill have been withdrawn since it was drawn up.")
        # The measurements behind it are pinned to the bill, so a later entry
        # cannot quietly join a claim that has already gone up for signature.
        for line in db.query(models.DBRABillLine).filter(
                models.DBRABillLine.ra_bill_id == bill.id).all():
            db.query(models.DBMeasurement).filter(
                models.DBMeasurement.work_order_id == bill.work_order_id,
                models.DBMeasurement.line_id == line.line_id,
                models.DBMeasurement.ra_bill_id.is_(None)).update(
                    {"ra_bill_id": bill.id}, synchronize_session=False)
    elif action == "REJECT":
        if not (comments or "").strip():
            raise HTTPException(400, "Say why it is going back, so it can be corrected.")
        bill.remarks = (comments or "").strip()
        db.query(models.DBMeasurement).filter(
            models.DBMeasurement.ra_bill_id == bill.id).update(
                {"ra_bill_id": None}, synchronize_session=False)
    elif action == "CERTIFY":
        bill.certified_by, bill.certified_by_name = actor_id, actor_name
        bill.certified_at = now
        bill.remarks = (comments or "").strip() or bill.remarks
    elif action == "PAY":
        bill.paid_at = now
    elif action == "CANCEL":
        if not (comments or "").strip():
            raise HTTPException(400, "Say why it is being cancelled.")
        bill.remarks = (comments or "").strip()
        # The work was still done; it goes back to the pool for the next bill.
        db.query(models.DBMeasurement).filter(
            models.DBMeasurement.ra_bill_id == bill.id).update(
                {"ra_bill_id": None}, synchronize_session=False)

    bill.status = allowed[action]
    bill.updated_at = now
    return bill


def refuse_cancel_with_money(db, client_id, doc_type, bill, verb):
    """A bill with money against it is not cancelled out from under it: the
    receipts would stay in the ledger and the bank book against a bill that
    no longer counts, and the party's balance would be off by exactly them."""
    got = money(settled_on(db, client_id, doc_type, bill.id))
    if got > 0:
        raise HTTPException(409, "%s has %s %s against it. Void those entries under "
                                 "Payments & Ledgers before cancelling it."
                                 % (bill.number, inr(got), verb))


def _ra_action(bill_id, action, body, request, db, permission="workorders.manage"):
    client, actor_id, actor_name = wo_actor(request, db, permission)
    bill = ra_bill_or_404(db, client.id, bill_id)
    if action == "CANCEL":
        refuse_cancel_with_money(db, client.id, "ra_bill", bill, "received")
        refuse_cancel_with_irn(db, client.id, "ra_bill", bill)
    ra_apply(db, client, bill, action, actor_id, actor_name, body.comments)
    log_audit(db, client.id, "ra_bill_" + action.lower(), "ra_bill", bill.id,
              bill.number, (body.comments or "").strip(), request)
    db.commit()
    db.refresh(bill)
    if action in ("SUBMIT", "CERTIFY"):
        job = db.query(models.DBJob).filter(models.DBJob.id == bill.job_id).first()
        if action == "SUBMIT":
            notify(db, client.id, "ra_bill_submitted", "%s is waiting to be certified" % bill.number,
                   "%s of work claimed on %s." % (inr(bill.this_bill), job.name if job else "the project"),
                   view="measurement-view", ref_type="ra_bill", ref_id=bill.id, severity="action")
        else:
            notify(db, client.id, "ra_bill_certified", "%s certified" % bill.number,
                   "%s to receive from %s, net of retention and TDS." % (
                       inr(bill.net_payable), (job.customer_name if job else "") or "the client"),
                   view="ledger-view", ref_type="ra_bill", ref_id=bill.id, severity="money")
        db.refresh(bill)
    return {"bill": ra_bill_dict(db, bill, detail=True),
            "message": "%s %s." % (bill.number, bill.status.lower())}


@app.post("/api/ra-bills/{bill_id}/submit")
def submit_ra_bill(bill_id: int, body: RAActionIn, request: Request,
                   db: Session = Depends(get_db)):
    return _ra_action(bill_id, "SUBMIT", body, request, db)


