@app.get("/api/ra-bills/{bill_id}/export.xlsx")
def ra_bill_xlsx(bill_id: int, request: Request, db: Session = Depends(get_db)):
    """The bill as it is presented for certification."""
    client = require_erp_read(request, db)
    bill = ra_bill_or_404(db, client.id, bill_id)
    d = ra_bill_dict(db, bill, detail=True)
    rows = [[l["fg_code"], l["description"], l["uom"], l["ordered_qty"],
             l["measured_to_date"], l["previously_billed_qty"], l["this_bill_qty"],
             l["rate"], l["amount"]] for l in d["lines"]]
    return sheet_response(
        ["Item", "Description", "UOM", "Ordered", "Measured to date",
         "Previously billed", "This bill", "Rate", "Amount"],
        rows, "ra_bill_%s.xlsx" % re.sub(r"[^A-Za-z0-9]+", "_", d["number"]),
        preamble=[["Running Account Bill", "", "", "", "", "", "", "", client.company_name or ""],
                  ["No: " + d["number"] + "   (" + d["status"] + ")"],
                  ["Work order: " + d["work_order"]],
                  ["Project: " + d["project"]],
                  ["Period to: " + d["period_to"]],
                  []],
        closing=[[], ["", "", "", "", "", "", "", "This bill", d["this_bill"]],
                 ["", "", "", "", "", "", "", "Retention @ %s%%" % d["retention_percent"],
                  -d["retention_amount"]],
                 ["", "", "", "", "", "", "", "Advance recovery", -d["advance_recovery"]],
                 ["", "", "", "", "", "", "", "Other deductions", -d["other_deductions"]],
                 ["", "", "", "", "", "", "", "GST @ %s%%" % d["tax_percent"], d["tax_amount"]],
                 ["", "", "", "", "", "", "", "TDS @ %s%%" % d["tds_percent"], -d["tds_amount"]],
                 ["", "", "", "", "", "", "", "Net payable", d["net_payable"]]])



# ============================================================================
# GOODS RECEIPT AND THE THREE-WAY MATCH
#
# A purchase order says what was agreed. A bill says what is being charged.
# Neither says what actually came off the lorry, and without that third number
# nobody can tell the difference between a supplier who delivered and a
# supplier who invoiced. The receipt note supplies it, and the match report
# puts the three side by side.
# ============================================================================

GRN_TRANSITIONS = {
    "DRAFT":     {"POST": "POSTED", "CANCEL": "CANCELLED"},
    # A posted receipt is not editable. Somebody has asserted that this is what
    # arrived, and a bill is about to be paid against it.
    "POSTED":    {"CANCEL": "CANCELLED"},
    "CANCELLED": {},
}
GRN_EDITABLE = ("DRAFT",)

# A receipt may only be taken against an order that was actually placed -
# see order_is_committed. Receiving against a draft would let material arrive
# for something nobody ever committed to buy.


def allocate_grn_number(db, client_id) -> str:
    last = db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.client_id == client_id).order_by(
            models.DBGoodsReceipt.id.desc()).first()
    if last and last.number:
        try:
            return "GRN-%04d" % (int(str(last.number).replace("GRN-", "")) + 1)
        except (ValueError, TypeError):
            pass
    return "GRN-0001"


def grn_or_404(db, client_id, grn_id):
    row = db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.id == grn_id,
        models.DBGoodsReceipt.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Goods receipt not found")
    return row


def received_to_date(db, purchase_order_id, exclude_grn_id=None):
    """Quantity accepted against each order line, over every live receipt.

    Cancelled receipts are excluded: a delivery that was cancelled did not
    arrive, and holding its quantity back would stop the replacement delivery
    from ever being recorded.
    """
    live = db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.purchase_order_id == purchase_order_id,
        models.DBGoodsReceipt.status != "CANCELLED").all()
    ids = [g.id for g in live if g.id != exclude_grn_id]
    totals = {}
    if not ids:
        return totals
    for l in db.query(models.DBGoodsReceiptLine).filter(
            models.DBGoodsReceiptLine.goods_receipt_id.in_(ids)).all():
        totals[l.po_line_id] = totals.get(l.po_line_id, 0.0) + (l.accepted_qty or 0.0)
    return totals


def recost_grn(db, grn):
    lines = db.query(models.DBGoodsReceiptLine).filter(
        models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all()
    grn.received_value = money(sum((l.received_qty or 0) * (l.rate or 0) for l in lines))
    grn.accepted_value = money(sum((l.accepted_qty or 0) * (l.rate or 0) for l in lines))
    grn.rejected_value = money(sum((l.rejected_qty or 0) * (l.rate or 0) for l in lines))
    for l in lines:
        l.amount = money((l.accepted_qty or 0) * (l.rate or 0))
    grn.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return grn


def grn_dict(db, grn, detail=False):
    po = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.id == grn.purchase_order_id).first()
    job = db.query(models.DBJob).filter(models.DBJob.id == grn.job_id).first()
    row = {
        "id": grn.id, "number": grn.number or "",
        "purchase_order_id": grn.purchase_order_id,
        "purchase_order": po.number if po else "",
        "job_id": grn.job_id,
        "project": ("%s %s" % (job.number, job.name)).strip() if job else "",
        "supplier_name": grn.supplier_name or "",
        "received_on": grn.received_on or "",
        "challan_number": grn.challan_number or "",
        "invoice_number": grn.invoice_number or "",
        "vehicle_number": grn.vehicle_number or "",
        "status": grn.status or "DRAFT",
        "received_value": money(grn.received_value),
        "accepted_value": money(grn.accepted_value),
        "rejected_value": money(grn.rejected_value),
        "received_by_name": grn.received_by_name or "",
        "inspected_by": grn.inspected_by or "",
        "store_location": grn.store_location or "",
        "remarks": grn.remarks or "",
        "posted_at": grn.posted_at or "",
        "created_at": grn.created_at or "",
        "editable": (grn.status or "DRAFT") in GRN_EDITABLE,
        "actions": sorted(GRN_TRANSITIONS.get(grn.status or "DRAFT", {}).keys()),
    }
    if detail:
        row["lines"] = [{
            "id": l.id, "po_line_id": l.po_line_id,
            "item_code": l.item_code or "", "description": l.description or "",
            "uom": l.uom or "", "ordered_qty": money(l.ordered_qty),
            "previously_received": money(l.previously_received),
            "received_qty": money(l.received_qty),
            "accepted_qty": money(l.accepted_qty),
            "rejected_qty": money(l.rejected_qty),
            "rejection_reason": l.rejection_reason or "",
            "rate": unit_rate(l.rate), "amount": money(l.amount),
        } for l in db.query(models.DBGoodsReceiptLine).filter(
            models.DBGoodsReceiptLine.goods_receipt_id == grn.id).order_by(
                models.DBGoodsReceiptLine.display_order,
                models.DBGoodsReceiptLine.id).all()]
    return row


def grn_actor(request, db):
    """The tenant plus who is at the gate, for the receipt's signature."""
    return wo_actor(request, db, "stores.receive")


@app.get("/api/grn/open-orders")
def grn_open_orders(request: Request, db: Session = Depends(get_db)):
    """Orders that still have material to come, so a storekeeper can pick one.

    An order that is fully received is dropped from the list: offering it
    invites somebody to receive the same delivery twice.
    """
    client = require_erp_read(request, db)
    out = []
    for po in db.query(models.DBPurchaseOrder).filter(
            models.DBPurchaseOrder.client_id == client.id).order_by(
                models.DBPurchaseOrder.id.desc()).limit(200).all():
        if not order_is_committed(po):
            continue
        got = received_to_date(db, po.id)
        lines = db.query(models.DBPurchaseOrderLineItem).filter(
            models.DBPurchaseOrderLineItem.order_id == po.id).all()
        pending = money(sum(max(0.0, (l.qty or 0) - got.get(l.id, 0.0)) * (l.price or 0)
                            for l in lines))
        if lines and pending <= 0:
            continue
        job = db.query(models.DBJob).filter(models.DBJob.id == po.job_id).first()
        out.append({
            "id": po.id, "number": po.number or "",
            "supplier_name": po.supplier_name or "",
            "project": ("%s %s" % (job.number, job.name)).strip() if job else "",
            "ordered_value": money(po.total or po.amount),
            "pending_value": pending, "line_count": len(lines),
        })
    return {"orders": out}


@app.get("/api/grn")
def list_goods_receipts(request: Request, db: Session = Depends(get_db),
                        purchase_order_id: int = 0, status: str = ""):
    client = require_erp_read(request, db)
    q = db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.client_id == client.id)
    if purchase_order_id:
        q = q.filter(models.DBGoodsReceipt.purchase_order_id == purchase_order_id)
    if status:
        q = q.filter(models.DBGoodsReceipt.status == status.upper())
    rows = [grn_dict(db, g) for g in
            q.order_by(models.DBGoodsReceipt.id.desc()).limit(500).all()]
    live = [r for r in rows if r["status"] != "CANCELLED"]
    return {
        "goods_receipts": rows,
        "summary": {
            "count": len(rows),
            "awaiting_posting": len([r for r in rows if r["status"] == "DRAFT"]),
            "received_value": money(sum(r["received_value"] for r in live)),
            "accepted_value": money(sum(r["accepted_value"] for r in live)),
            "rejected_value": money(sum(r["rejected_value"] for r in live)),
        },
    }


class GRNIn(BaseModel):
    purchase_order_id: int
    received_on: Optional[str] = ""
    challan_number: Optional[str] = ""
    invoice_number: Optional[str] = ""
    vehicle_number: Optional[str] = ""
    store_location: Optional[str] = ""
    inspected_by: Optional[str] = ""
    remarks: Optional[str] = ""


@app.post("/api/grn")
def create_goods_receipt(body: GRNIn, request: Request, db: Session = Depends(get_db)):
    """Open a receipt against an order, pre-filled with what is still to come.

    The quantities default to the outstanding balance because that is what a
    full delivery looks like; the storekeeper's job is then to correct the
    lines that came up short, not to type the whole order back in.
    """
    client, actor_id, actor_name = grn_actor(request, db)
    po = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.id == body.purchase_order_id,
        models.DBPurchaseOrder.client_id == client.id).first()
    if not po:
        raise HTTPException(404, "Purchase order not found")
    if not order_is_committed(po):
        raise HTTPException(
            409, "Only an approved order can be received against. This one is %s."
                 % (po.status or "Draft"))

    grn = models.DBGoodsReceipt(
        client_id=client.id, purchase_order_id=po.id, job_id=po.job_id,
        number=allocate_grn_number(db, client.id),
        supplier_name=po.supplier_name or "", status="DRAFT",
        received_on=(body.received_on or datetime.now().strftime("%Y-%m-%d")),
        challan_number=(body.challan_number or "").strip(),
        invoice_number=(body.invoice_number or "").strip(),
        vehicle_number=(body.vehicle_number or "").strip(),
        store_location=(body.store_location or "").strip(),
        inspected_by=(body.inspected_by or "").strip(),
        remarks=(body.remarks or "").strip(),
        received_by=actor_id, received_by_name=actor_name)
    db.add(grn)
    db.flush()

    got = received_to_date(db, po.id)
    order = 0
    for l in db.query(models.DBPurchaseOrderLineItem).filter(
            models.DBPurchaseOrderLineItem.order_id == po.id).order_by(
                models.DBPurchaseOrderLineItem.id).all():
        had = money(got.get(l.id, 0.0))
        balance = money(max(0.0, (l.qty or 0) - had))
        order += 1
        db.add(models.DBGoodsReceiptLine(
            goods_receipt_id=grn.id, po_line_id=l.id,
            item_code=getattr(l, "item_code", "") or "",
            description=(l.description or "")[:500],
            uom=getattr(l, "uom", "") or "",
            ordered_qty=money(l.qty), previously_received=had,
            received_qty=balance, accepted_qty=balance, rejected_qty=0.0,
            rate=unit_rate(l.price), amount=money(balance * (l.price or 0)),
            display_order=order))
    db.flush()
    recost_grn(db, grn)
    log_audit(db, client.id, "grn_created", "goods_receipt", grn.id, grn.number,
              "against %s" % (po.number or ""), request)
    db.commit()
    db.refresh(grn)
    return grn_dict(db, grn, detail=True)


class GRNLineIn(BaseModel):
    id: Optional[int] = None
    received_qty: Optional[float] = 0.0
    accepted_qty: Optional[float] = None
    rejected_qty: Optional[float] = None
    rejection_reason: Optional[str] = ""


class GRNUpdateIn(BaseModel):
    received_on: Optional[str] = None
    challan_number: Optional[str] = None
    invoice_number: Optional[str] = None
    vehicle_number: Optional[str] = None
    store_location: Optional[str] = None
    inspected_by: Optional[str] = None
    remarks: Optional[str] = None
    lines: Optional[List[GRNLineIn]] = None


@app.put("/api/grn/{grn_id}")
def update_goods_receipt(grn_id: int, body: GRNUpdateIn, request: Request,
                         db: Session = Depends(get_db)):
    client, actor_id, actor_name = grn_actor(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    if (grn.status or "DRAFT") not in GRN_EDITABLE:
        raise HTTPException(
            409, "A %s receipt cannot be changed. Cancel it and take a new one."
                 % (grn.status or "").lower())

    for field in ("received_on", "challan_number", "invoice_number",
                  "vehicle_number", "store_location", "inspected_by", "remarks"):
        val = getattr(body, field)
        if val is not None:
            setattr(grn, field, str(val).strip())

    if body.lines is not None:
        rows = {l.id: l for l in db.query(models.DBGoodsReceiptLine).filter(
            models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all()}
        for inp in body.lines:
            row = rows.get(inp.id)
            if not row:
                continue
            received = money(max(0.0, inp.received_qty or 0.0))
            rejected = money(max(0.0, inp.rejected_qty or 0.0))
            # Accepted is derived when it is not given, because the two numbers
            # have to add up to what arrived. A store that can record eight
            # accepted and three rejected out of ten is a store whose figures
            # nobody can use.
            accepted = (money(inp.accepted_qty) if inp.accepted_qty is not None
                        else money(received - rejected))
            if accepted < 0:
                raise HTTPException(400, "More rejected than arrived on %s"
                                    % (row.description or row.item_code or "a line"))
            if money(accepted + rejected) > received:
                raise HTTPException(
                    400, "Accepted and rejected come to more than arrived on %s"
                         % (row.description or row.item_code or "a line"))
            row.received_qty, row.accepted_qty, row.rejected_qty = (
                received, accepted, rejected)
            row.rejection_reason = (inp.rejection_reason or "")[:300]
    recost_grn(db, grn)
    db.commit()
    db.refresh(grn)
    return grn_dict(db, grn, detail=True)


def grn_apply(db, client_id, grn, action, request=None, actor_name="", comments=""):
    """The single door every status change goes through."""
    state = grn.status or "DRAFT"
    allowed = GRN_TRANSITIONS.get(state, {})
    if action not in allowed:
        raise HTTPException(
            409, "A %s receipt cannot be %sed." % (state.lower(), action.lower()))
    grn.status = allowed[action]
    if action == "POST":
        grn.posted_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        # Accepted material becomes stock here, and only here. Rejected
        # material never enters the store, so it is not booked in and does
        # not have to be found and taken out again later.
        for l in db.query(models.DBGoodsReceiptLine).filter(
                models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all():
            if (l.accepted_qty or 0) > 0:
                stock_movement(db, client_id, l.item_code or "", "RECEIPT",
                               l.accepted_qty, l.rate, item_name=l.description,
                               uom=l.uom, store=grn.store_location or "Main store",
                               moved_on=grn.received_on, source_type="goods_receipt",
                               source_id=grn.id, source_ref=grn.number or "",
                               job_id=grn.job_id, recorded_by_name=actor_name)
    if action == "CANCEL" and state == "POSTED":
        # Cancelling a posted receipt takes the material back out, otherwise
        # the store keeps stock that was never really there.
        for l in db.query(models.DBGoodsReceiptLine).filter(
                models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all():
            if (l.accepted_qty or 0) > 0:
                stock_movement(db, client_id, l.item_code or "", "ADJUSTMENT",
                               -l.accepted_qty, l.rate, item_name=l.description,
                               uom=l.uom, store=grn.store_location or "Main store",
                               source_type="goods_receipt", source_id=grn.id,
                               source_ref=(grn.number or "") + " cancelled",
                               remarks="Receipt cancelled",
                               recorded_by_name=actor_name)
    grn.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_audit(db, client_id, "grn_%s" % action.lower(), "goods_receipt",
              grn.id, grn.number or "", ("%s %s" % (actor_name, comments)).strip(),
              request)
    return grn


@app.post("/api/grn/{grn_id}/post")
def post_goods_receipt(grn_id: int, request: Request, db: Session = Depends(get_db)):
    client, actor_id, actor_name = grn_actor(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    lines = db.query(models.DBGoodsReceiptLine).filter(
        models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all()
    if not any((l.received_qty or 0) for l in lines):
        raise HTTPException(400, "Nothing arrived on this receipt.")
    recost_grn(db, grn)
    grn_apply(db, client.id, grn, "POST", request, actor_name)
    db.commit()

    # Said rather than refused: a lorry that brings more than the order is a
    # real event, and the buyer needs to know before the bill turns up.
    over = []
    for l in lines:
        total = money((l.previously_received or 0) + (l.accepted_qty or 0))
        if total > money(l.ordered_qty or 0):
            over.append("%s by %s" % (l.item_code or l.description or "line",
                                      money(total - money(l.ordered_qty))))
    msg = "%s posted. %s accepted into the store." % (grn.number, inr(grn.accepted_value))
    if over:
        msg += " Over the order: %s." % "; ".join(over[:4])
    return {"ok": True, "over_received": over,
            "goods_receipt": grn_dict(db, grn, detail=True), "message": msg}


class GRNActionIn(BaseModel):
    comments: Optional[str] = ""


@app.post("/api/grn/{grn_id}/cancel")
def cancel_goods_receipt(grn_id: int, request: Request, body: GRNActionIn = None,
                         db: Session = Depends(get_db)):
    """Cancelling returns the quantity, so the delivery can be recorded again."""
    client, actor_id, actor_name = grn_actor(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    body = body or GRNActionIn()
    if not (body.comments or "").strip():
        raise HTTPException(400, "Say why this receipt is being cancelled.")
    grn_apply(db, client.id, grn, "CANCEL", request, actor_name, body.comments)
    grn.remarks = ("%s\nCancelled: %s" % (grn.remarks or "", body.comments)).strip()
    db.commit()
    return {"ok": True, "message": "%s cancelled." % grn.number}


@app.delete("/api/grn/{grn_id}")
def delete_goods_receipt(grn_id: int, request: Request, db: Session = Depends(get_db)):
    client, actor_id, actor_name = grn_actor(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    if (grn.status or "DRAFT") != "DRAFT":
        raise HTTPException(
            409, "A posted receipt is a record of what arrived. Cancel it instead.")
    db.query(models.DBGoodsReceiptLine).filter(
        models.DBGoodsReceiptLine.goods_receipt_id == grn.id).delete()
    number = grn.number
    db.delete(grn)
    log_audit(db, client.id, "grn_deleted", "goods_receipt", grn_id, number or "",
              "draft discarded", request)
    db.commit()
    return {"ok": True, "message": "%s discarded." % number}


@app.get("/api/grn/{grn_id}/export.xlsx")
def export_goods_receipt(grn_id: int, request: Request, db: Session = Depends(get_db)):
    """The receipt as a workbook, for the file the store keeps by the gate."""
    client = require_erp_read(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    d = grn_dict(db, grn, detail=True)
    return sheet_response(
        ["#", "Item code", "Description", "UOM", "Ordered", "Already received",
         "Arrived", "Accepted", "Rejected", "Reason", "Rate", "Value"],
        [[i, l["item_code"], l["description"], l["uom"], l["ordered_qty"],
          l["previously_received"], l["received_qty"], l["accepted_qty"],
          l["rejected_qty"], l["rejection_reason"], l["rate"], l["amount"]]
         for i, l in enumerate(d["lines"], 1)],
        "%s.xlsx" % d["number"],
        preamble=[["GOODS RECEIPT NOTE"],
                  ["GRN number", d["number"], "", "Purchase order", d["purchase_order"]],
                  ["Supplier", d["supplier_name"], "", "Project", d["project"]],
                  ["Received on", d["received_on"], "", "Challan", d["challan_number"]],
                  ["Supplier invoice", d["invoice_number"], "",
                   "Vehicle", d["vehicle_number"]],
                  ["Store", d["store_location"], "", "Status", d["status"]],
                  ["Received by", d["received_by_name"], "",
                   "Inspected by", d["inspected_by"]],
                  []],
        closing=[[],
                 ["", "", "", "", "", "", "", "", "", "", "Arrived", d["received_value"]],
                 ["", "", "", "", "", "", "", "", "", "", "Accepted", d["accepted_value"]],
                 ["", "", "", "", "", "", "", "", "", "", "Rejected", d["rejected_value"]]])


@app.get("/api/grn/{grn_id}")
def get_goods_receipt(grn_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return grn_dict(db, grn_or_404(db, client.id, grn_id), detail=True)


# --- The three-way match ----------------------------------------------------

def billed_against_po(db, purchase_order_id):
    """Value and quantity billed against an order, ignoring rejected bills.

    A bill that was thrown out is not a claim on anything, and counting it
    would make an order look fully billed when nobody has been paid.
    """
    bills = db.query(models.DBBill).filter(
        models.DBBill.purchase_order_id == purchase_order_id,
        models.DBBill.status != "Rejected").all()
    ids = [b.id for b in bills]
    per_line = {}
    if ids:
        for l in db.query(models.DBBillLineItem).filter(
                models.DBBillLineItem.bill_id.in_(ids)).all():
            key = getattr(l, "po_line_id", None)
            if key:
                per_line[key] = per_line.get(key, 0.0) + (l.qty or 0.0)
    return {
        "bills": bills,
        # Before tax, as the ordered and received figures it is set against
        # are. Counted with GST, every bill drawn from a receipt looked
        # over-billed by exactly its tax.
        "value": money(sum((b.amount if b.amount else b.total) or 0 for b in bills)),
        "paid": money(sum(b.amount_paid or 0 for b in bills)),
        "per_line": per_line,
    }


def match_verdict(ordered, received, billed):
    """What the three numbers say, in the order a buyer would ask.

    The two that cost money come first, most specific one leading: a bill with
    nothing at all received is a different conversation from a bill that runs
    ahead of a part delivery, and saying so is more use than a figure.
    """
    if received <= 0.01 and billed > 0.01:
        return ("AWAITING_RECEIPT",
                "Billed with nothing recorded as received. Check the gate before paying.")
    if billed > received + 0.01:
        return ("OVER_BILLED",
                "Billed for more than was received. Do not pay until this is explained.")
    if received > ordered + 0.01:
        return ("OVER_RECEIVED",
                "More arrived than was ordered. Agree a variation before billing it.")
    if received <= 0.01 and billed <= 0.01:
        return ("AWAITING_DELIVERY", "Ordered. Nothing has arrived yet.")
    if billed <= 0.01:
        return ("AWAITING_BILL", "Received and not yet billed. An accrual is owed.")
    if billed < received - 0.01:
        return ("PART_BILLED", "Part billed against what was received.")
    return ("MATCHED", "Ordered, received and billed agree.")


@app.get("/api/match/three-way")
def three_way_match(request: Request, db: Session = Depends(get_db),
                    job_id: int = 0, only_exceptions: bool = False):
    """Every order with what was ordered, what arrived and what was billed.

    This is the report that stops a business paying for material it never
    received, which is the single most expensive thing a site office gets
    wrong.
    """
    client = require_erp_read(request, db)
    q = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.client_id == client.id,
        models.DBPurchaseOrder.status != "Cancelled")
    if job_id:
        q = q.filter(models.DBPurchaseOrder.job_id == job_id)

    rows = []
    for po in q.order_by(models.DBPurchaseOrder.id.desc()).limit(500).all():
        lines = db.query(models.DBPurchaseOrderLineItem).filter(
            models.DBPurchaseOrderLineItem.order_id == po.id).all()
        got = received_to_date(db, po.id)
        billed = billed_against_po(db, po.id)
        receipts = db.query(models.DBGoodsReceipt).filter(
            models.DBGoodsReceipt.purchase_order_id == po.id,
            models.DBGoodsReceipt.status != "CANCELLED").count()

        ordered_value = money(sum((l.qty or 0) * (l.price or 0) for l in lines))
        received_value = money(sum(got.get(l.id, 0.0) * (l.price or 0) for l in lines))
        verdict, note = match_verdict(ordered_value, received_value, billed["value"])
        job = db.query(models.DBJob).filter(models.DBJob.id == po.job_id).first()
        rows.append({
            "purchase_order_id": po.id, "number": po.number or "",
            "supplier_name": po.supplier_name or "",
            "status": po.status or "",
            "project": ("%s %s" % (job.number, job.name)).strip() if job else "",
            "ordered_value": ordered_value,
            "received_value": received_value,
            "billed_value": billed["value"], "paid_value": billed["paid"],
            "bill_count": len(billed["bills"]), "receipt_count": receipts,
            "unbilled_receipts": (money(received_value - billed["value"])
                                  if received_value > billed["value"] else 0.0),
            "verdict": verdict, "note": note,
        })

    exceptions = [r for r in rows if r["verdict"] in
                  ("OVER_BILLED", "OVER_RECEIVED", "AWAITING_RECEIPT")]
    return {
        "orders": exceptions if only_exceptions else rows,
        "summary": {
            "orders": len(rows),
            "matched": len([r for r in rows if r["verdict"] == "MATCHED"]),
            "exceptions": len(exceptions),
            "over_billed": money(sum(r["billed_value"] - r["received_value"]
                                     for r in rows if r["verdict"] == "OVER_BILLED")),
            # What has arrived and not been billed is a cost already incurred.
            # Left off the books it makes a month look cheaper than it was.
            "accrual_owed": money(sum(r["unbilled_receipts"] for r in rows)),
            "ordered_value": money(sum(r["ordered_value"] for r in rows)),
            "received_value": money(sum(r["received_value"] for r in rows)),
            "billed_value": money(sum(r["billed_value"] for r in rows)),
        },
    }


@app.get("/api/match/three-way/{po_id}")
def three_way_match_detail(po_id: int, request: Request, db: Session = Depends(get_db)):
    """The same comparison, line by line, for one order."""
    client = require_erp_read(request, db)
    po = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.id == po_id,
        models.DBPurchaseOrder.client_id == client.id).first()
    if not po:
        raise HTTPException(404, "Purchase order not found")

    got = received_to_date(db, po.id)
    billed = billed_against_po(db, po.id)
    lines = []
    for l in db.query(models.DBPurchaseOrderLineItem).filter(
            models.DBPurchaseOrderLineItem.order_id == po.id).order_by(
                models.DBPurchaseOrderLineItem.id).all():
        rec = money(got.get(l.id, 0.0))
        bil = money(billed["per_line"].get(l.id, 0.0))
        verdict, note = match_verdict(money(l.qty), rec, bil)
        lines.append({
            "po_line_id": l.id, "item_code": getattr(l, "item_code", "") or "",
            "description": l.description or "", "uom": getattr(l, "uom", "") or "",
            "ordered_qty": money(l.qty), "received_qty": rec, "billed_qty": bil,
            "rate": unit_rate(l.price),
            "ordered_value": money((l.qty or 0) * (l.price or 0)),
            "received_value": money(rec * (l.price or 0)),
            "billed_value": money(bil * (l.price or 0)),
            "verdict": verdict, "note": note,
        })

    return {
        "purchase_order": purchase_order_to_dict(db, po),
        "lines": lines,
        "goods_receipts": [grn_dict(db, g) for g in
                           db.query(models.DBGoodsReceipt).filter(
                               models.DBGoodsReceipt.purchase_order_id == po.id).order_by(
                                   models.DBGoodsReceipt.id.desc()).all()],
        "bills": [{"id": b.id, "number": b.number or "", "status": b.status or "",
                   "total": money(b.total), "amount_paid": money(b.amount_paid),
                   "issue_date": b.issue_date or ""} for b in billed["bills"]],
        # Only meaningful when the bill lines name the order lines they settle.
        # Without that the totals still compare; the per line figures do not.
        "line_level_available": bool(billed["per_line"]),
    }




# ============================================================================
# VARIATION ORDERS
#
# The measurement book already knows which lines ran past their ordered
# quantity - it prints "5 over the order" against them. Until now that was
# where it stopped, and extra work stayed done, measured and unpaid.
#
# A variation drafts itself from that flag: the app proposes the lines, the
# quantities and the money without anybody retyping them, and approving it
# raises the order so the over-run disappears and the work becomes billable.
# ============================================================================

VO_TRANSITIONS = {
    "DRAFT":     {"SUBMIT": "SUBMITTED", "CANCEL": "CANCELLED"},
    "SUBMITTED": {"APPROVE": "APPROVED", "REJECT": "DRAFT", "CANCEL": "CANCELLED"},
    "APPROVED":  {},
    "REJECTED":  {},
    "CANCELLED": {},
}


def next_vo_number(db, work_order):
    n = db.query(models.DBVariationOrder).filter(
        models.DBVariationOrder.work_order_id == work_order.id).count() + 1
    return "%s/VO-%02d" % (work_order.number or "WO", n), n


def vo_or_404(db, client_id, vo_id):
    row = db.query(models.DBVariationOrder).filter(
        models.DBVariationOrder.id == vo_id,
        models.DBVariationOrder.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Variation not found")
    return row


def over_measured_lines(db, work_order):
    """Every line the site has built past its ordered quantity.

    This is the whole input to a variation, and it is already sitting in the
    measurement book. Nobody should have to read it off a screen and type it
    back in.
    """
    measured = measured_to_date(db, work_order.id)
    out = []
    for l in db.query(models.DBWorkOrderLine).filter(
            models.DBWorkOrderLine.work_order_id == work_order.id).order_by(
                models.DBWorkOrderLine.id).all():
        done, ordered = money(measured.get(l.id, 0.0)), money(l.qty)
        if done > ordered:
            extra = money(done - ordered)
            out.append({
                "line_id": l.id, "fg_code": l.fg_code or "",
                "description": (l.description or l.item_name or "").split("\n")[0],
                "uom": l.uom or "", "ordered_qty": ordered, "measured_qty": done,
                "extra_qty": extra, "rate": unit_rate(l.rate),
                "amount": money(extra * unit_rate(l.rate)),
            })
    return out


def recost_variation(db, vo):
    lines = db.query(models.DBVariationLine).filter(
        models.DBVariationLine.variation_order_id == vo.id).all()
    vo.value = money(sum(l.amount or 0 for l in lines))
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == vo.work_order_id).first()
    vo.order_value_before = money(wo.total_value if wo else 0)
    vo.order_value_after = money(vo.order_value_before + vo.value)
    vo.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return vo


def vo_dict(db, vo, detail=False):
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == vo.work_order_id).first()
    row = {
        "id": vo.id, "number": vo.number or "", "sequence": vo.sequence or 1,
        "work_order_id": vo.work_order_id, "work_order": wo.number if wo else "",
        "status": vo.status or "DRAFT", "origin": vo.origin or "manual",
        "reason": vo.reason or "", "value": money(vo.value),
        "order_value_before": money(vo.order_value_before),
        "order_value_after": money(vo.order_value_after),
        "raised_by_name": vo.raised_by_name or "",
        "approved_by_name": vo.approved_by_name or "",
        "approved_at": vo.approved_at or "",
        "rejection_reason": vo.rejection_reason or "",
        "actions": sorted(VO_TRANSITIONS.get(vo.status or "DRAFT", {}).keys()),
        "editable": (vo.status or "DRAFT") == "DRAFT",
        "created_at": vo.created_at or "",
    }
    if detail:
        row["lines"] = [{
            "id": l.id, "line_id": l.line_id, "fg_code": l.fg_code or "",
            "description": l.description or "", "uom": l.uom or "",
            "ordered_qty": money(l.ordered_qty), "measured_qty": money(l.measured_qty),
            "extra_qty": money(l.extra_qty), "rate": unit_rate(l.rate),
            "amount": money(l.amount),
            "is_new_item": l.line_id is None,
        } for l in db.query(models.DBVariationLine).filter(
            models.DBVariationLine.variation_order_id == vo.id).order_by(
                models.DBVariationLine.display_order, models.DBVariationLine.id).all()]
    return row


class VariationIn(BaseModel):
    work_order_id: int
    reason: Optional[str] = ""
    lines: Optional[list] = None          # omit to let the book fill it in


@app.get("/api/variations")
def list_variations(request: Request, work_order_id: int = 0,
                    db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBVariationOrder).filter(
        models.DBVariationOrder.client_id == client.id)
    if work_order_id:
        q = q.filter(models.DBVariationOrder.work_order_id == work_order_id)
    rows = [vo_dict(db, v) for v in q.order_by(
        models.DBVariationOrder.id.desc()).limit(200).all()]
    live = [r for r in rows if r["status"] not in ("CANCELLED", "REJECTED")]
    return {
        "variations": rows,
        "summary": {
            "raised": len(rows),
            "awaiting_approval": len([r for r in rows if r["status"] == "SUBMITTED"]),
            "approved_value": money(sum(r["value"] for r in rows
                                        if r["status"] == "APPROVED")),
            "pending_value": money(sum(r["value"] for r in live
                                       if r["status"] != "APPROVED")),
        },
    }


@app.get("/api/variations/suggest/{work_order_id}")
def suggest_variation(work_order_id: int, request: Request,
                      db: Session = Depends(get_db)):
    """What the app would raise, without raising it.

    The screen asks this to decide whether to offer the button at all, so a
    site with nothing over-run is never nagged about a variation it does not
    need.
    """
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, work_order_id)
    lines = over_measured_lines(db, wo)
    return {"lines": lines, "value": money(sum(l["amount"] for l in lines)),
            "count": len(lines)}


@app.post("/api/variations")
def create_variation(body: VariationIn, request: Request,
                     db: Session = Depends(get_db)):
    """Draw one up - from the measurement book unless lines are supplied."""
    client, actor_id, actor_name = wo_actor(request, db)
    wo = work_order_or_404(db, client.id, body.work_order_id)
    if (wo.status or "") == "Draft":
        raise HTTPException(409, "Vary the order after it has been placed, not before.")

    supplied = body.lines
    origin = "manual" if supplied else "measured"
    rows = supplied if supplied else over_measured_lines(db, wo)
    if not rows:
        raise HTTPException(
            409, "Nothing is over the ordered quantity, so there is nothing to vary. "
                 "Measure the extra work first, or add the lines yourself.")

    number, seq = next_vo_number(db, wo)
    vo = models.DBVariationOrder(
        client_id=client.id, work_order_id=wo.id, job_id=wo.job_id,
        number=number, sequence=seq, status="DRAFT", origin=origin,
        reason=(body.reason or "").strip(),
        raised_by=actor_id, raised_by_name=actor_name)
    db.add(vo)
    db.flush()

    for i, r in enumerate(rows):
        extra = money(r.get("extra_qty") or 0)
        rate = unit_rate(r.get("rate") or 0)
        if not extra:
            continue
        db.add(models.DBVariationLine(
            variation_order_id=vo.id, line_id=r.get("line_id"),
            fg_code=(r.get("fg_code") or "")[:120],
            description=(r.get("description") or "")[:500],
            uom=(r.get("uom") or "")[:40],
            ordered_qty=money(r.get("ordered_qty") or 0),
            measured_qty=money(r.get("measured_qty") or 0),
            extra_qty=extra, rate=rate, amount=money(extra * rate),
            display_order=i))
    db.flush()
    recost_variation(db, vo)
    log_audit(db, client.id, "variation_raised", "work_order", wo.id, wo.number or "",
              "%s %s %s" % (number, origin, inr(vo.value)), request)
    db.commit()
    db.refresh(vo)
    return {"ok": True, "variation": vo_dict(db, vo, detail=True),
            "message": ("%s drawn up from the measurement book - %s of extra work."
                        % (number, inr(vo.value)) if origin == "measured"
                        else "%s created." % number)}


@app.get("/api/variations/{vo_id}")
def get_variation(vo_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return vo_dict(db, vo_or_404(db, client.id, vo_id), detail=True)


def apply_variation(db, vo):
    """Raise the order to match what was agreed.

    An existing line has its quantity lifted to the measured figure; a new item
    becomes a real order line so the book can be kept against it from now on.
    Done once, on approval, and never again - applied_at is the guard.
    """
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == vo.work_order_id).first()
    for l in db.query(models.DBVariationLine).filter(
            models.DBVariationLine.variation_order_id == vo.id).all():
        if l.line_id:
            line = db.query(models.DBWorkOrderLine).filter(
                models.DBWorkOrderLine.id == l.line_id).first()
            if not line:
                continue
            line.qty = money((line.qty or 0) + l.extra_qty)
            line.amount = money(line.qty * (line.rate or 0))
        else:
            db.add(models.DBWorkOrderLine(
                work_order_id=wo.id, fg_code=l.fg_code, item_name=l.description,
                description=l.description, qty=l.extra_qty, uom=l.uom,
                rate=l.rate, amount=l.amount))
    db.flush()
    total = sum(money(x.amount) for x in db.query(models.DBWorkOrderLine).filter(
        models.DBWorkOrderLine.work_order_id == wo.id).all())
    wo.total_value = money(total)
    vo.applied_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return wo


@app.post("/api/variations/{vo_id}/{action}")
def act_on_variation(vo_id: int, action: str, request: Request, body: dict = None,
                     db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    vo = vo_or_404(db, client.id, vo_id)
    move = (action or "").upper()
    allowed = VO_TRANSITIONS.get(vo.status or "DRAFT", {})
    if move not in allowed:
        raise HTTPException(
            409, "A %s variation cannot be %sed." % ((vo.status or "draft").lower(),
                                                     move.lower()))
    body = body or {}
    if move == "APPROVE":
        # Approving raises the contract value, so it is the approver's right
        # rather than the raiser's. Whoever may approve a subcontract may
        # approve a change to one.
        require_items_access(request, db, "subcontracts.approve")
        vo.approved_by_name = actor_name
        vo.approved_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if not vo.applied_at:
            apply_variation(db, vo)
    if move == "REJECT":
        reason = (body.get("comments") or "").strip()
        if not reason:
            raise HTTPException(400, "Say why it is going back.")
        vo.rejection_reason = reason

    was, vo.status = vo.status, allowed[move]
    vo.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_audit(db, client.id, "variation_%s" % move.lower(), "work_order",
              vo.work_order_id, vo.number or "", "%s -> %s" % (was, vo.status), request)
    db.commit()
    db.refresh(vo)
    if move in ("SUBMIT", "APPROVE"):
        notify(db, client.id, "variation_submitted" if move == "SUBMIT" else "variation_approved",
               ("%s is waiting for approval" if move == "SUBMIT" else "%s agreed") % vo.number,
               "%s of extra work." % inr(vo.value), view="measurement-view",
               ref_type="variation", ref_id=vo.id, severity="action" if move == "SUBMIT" else "money")
        db.refresh(vo)
    return {"ok": True, "variation": vo_dict(db, vo, detail=True),
            "message": "%s is now %s." % (vo.number, vo.status.lower())}


@app.delete("/api/variations/{vo_id}")
def delete_variation(vo_id: int, request: Request, db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    vo = vo_or_404(db, client.id, vo_id)
    if (vo.status or "DRAFT") != "DRAFT":
        raise HTTPException(409, "Only a draft can be deleted. Cancel it instead.")
    db.query(models.DBVariationLine).filter(
        models.DBVariationLine.variation_order_id == vo.id).delete()
    db.delete(vo)
    db.commit()
    return {"ok": True, "message": "Draft removed."}




# ============================================================================
# THE WORK ORDER STATEMENT
#
# Everything this app knows about one order, reconciled down a single column:
# what was ordered, what was agreed on top of it, what has been built, what
# has been claimed, what has been certified, what has been paid, and what is
# still being held back.
#
# Each of those numbers already existed, on a different screen. The question a
# contractor actually asks - "where are we on this order" - could only be
# answered by opening four of them and doing the subtraction by hand, which is
# the same arithmetic error this app was built to stop.
# ============================================================================

def work_order_statement(db, client, wo):
    lines = db.query(models.DBWorkOrderLine).filter(
        models.DBWorkOrderLine.work_order_id == wo.id).order_by(
            models.DBWorkOrderLine.id).all()
    measured = measured_to_date(db, wo.id)
    billed_qty = billed_qty_to_date(db, wo.id)

    # Variations that were agreed are already inside the order's own value -
    # approving one raises the lines - so the original is what is left when
    # they are taken back off. Counting them again here would double them.
    vos = db.query(models.DBVariationOrder).filter(
        models.DBVariationOrder.work_order_id == wo.id).all()
    agreed = money(sum(v.value or 0 for v in vos if (v.status or "") == "APPROVED"))
    pending_vo = money(sum(v.value or 0 for v in vos
                           if (v.status or "") in ("DRAFT", "SUBMITTED")))
    revised = money(wo.total_value)
    original = money(revised - agreed)

    rows, measured_value, unbilled_value, over_run = [], 0.0, 0.0, 0.0
    for l in lines:
        rate = unit_rate(l.rate)
        done = money(measured.get(l.id, 0.0))
        claimed = money(billed_qty.get(l.id, 0.0))
        ordered = money(l.qty)
        measured_value += done * rate
        unbilled_value += money(done - claimed) * rate
        if done > ordered:
            over_run += money(done - ordered) * rate
        rows.append({
            "fg_code": l.fg_code or "",
            "description": (l.description or l.item_name or "").split("\n")[0],
            "uom": l.uom or "", "ordered_qty": ordered, "rate": rate,
            "ordered_value": money(ordered * rate),
            "measured_qty": done, "measured_value": money(done * rate),
            "billed_qty": claimed, "billed_value": money(claimed * rate),
            "unbilled_qty": money(done - claimed),
            "unbilled_value": money(money(done - claimed) * rate),
            "percent_measured": round(done / ordered * 100, 1) if ordered else 0.0,
        })

    bills = db.query(models.DBRABill).filter(
        models.DBRABill.work_order_id == wo.id,
        models.DBRABill.status != "CANCELLED").all()
    claimed_value = money(sum(b.this_bill or 0 for b in bills))
    certified = money(sum(b.this_bill or 0 for b in bills
                          if (b.status or "") in ("CERTIFIED", "PAID")))
    paid = money(sum(b.net_payable or 0 for b in bills if (b.status or "") == "PAID"))
    awaiting = money(sum(b.net_payable or 0 for b in bills
                         if (b.status or "") == "CERTIFIED"))
    retention = money(sum(b.retention_amount or 0 for b in bills
                          if (b.status or "") in ("CERTIFIED", "PAID"))
                      - released_retention(db, wo.client_id, "client").get(wo.id, 0.0))
    tds = money(sum(b.tds_amount or 0 for b in bills if (b.status or "") == "PAID"))

    return {
        "work_order": work_order_to_dict(db, wo),
        "lines": rows,
        "order": {
            "original_value": original,
            "variations_agreed": agreed,
            "variations_pending": pending_vo,
            "revised_value": revised,
        },
        "progress": {
            "measured_value": money(measured_value),
            "percent_complete": round(measured_value / revised * 100, 1) if revised else 0.0,
            "left_to_build": money(revised - measured_value),
            "over_run_not_yet_varied": money(over_run),
        },
        "money": {
            "claimed": claimed_value,
            "certified": certified,
            "paid": paid,
            "awaiting_payment": awaiting,
            "retention_held": retention,
            "tds_deducted": tds,
            # Built, but not yet on any bill. The number worth chasing, because
            # it is work already paid for in wages and material.
            "measured_not_billed": money(unbilled_value),
        },
        "bills": [{
            "id": b.id, "number": b.number or "", "status": b.status or "",
            "this_bill": money(b.this_bill), "net_payable": money(b.net_payable),
        } for b in sorted(bills, key=lambda x: x.sequence or 0)],
        "variations": [{
            "id": v.id, "number": v.number or "", "status": v.status or "",
            "value": money(v.value),
        } for v in sorted(vos, key=lambda x: x.sequence or 0)],
    }


@app.get("/api/erp/work-orders/{wo_id}/statement")
def erp_work_order_statement(wo_id: int, request: Request,
                             db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return work_order_statement(db, client, work_order_or_404(db, client.id, wo_id))


@app.get("/api/erp/work-orders/{wo_id}/statement.xlsx")
def erp_work_order_statement_xlsx(wo_id: int, request: Request,
                                  db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, wo_id)
    s = work_order_statement(db, client, wo)
    o, p, m = s["order"], s["progress"], s["money"]

    preamble = [
        ("WORK ORDER STATEMENT", client.company_name or ""),
        ("Order", wo.number or "", "Status", wo.status or ""),
        ("Project", s["work_order"].get("job_name", "") or ""),
        (),
        ("Original order value", o["original_value"]),
        ("Variations agreed", o["variations_agreed"]),
        ("Revised order value", o["revised_value"]),
        ("Variations asked for, not agreed", o["variations_pending"]),
        (),
        ("Measured to date", p["measured_value"], "Complete", "%s%%" % p["percent_complete"]),
        ("Left to build", p["left_to_build"]),
        ("Built past the order, not yet varied", p["over_run_not_yet_varied"]),
        (),
        ("Claimed on bills", m["claimed"]),
        ("Certified", m["certified"]),
        ("Paid", m["paid"]),
        ("Certified, awaiting payment", m["awaiting_payment"]),
        ("Measured but not billed", m["measured_not_billed"]),
        ("Retention held", m["retention_held"]),
        ("TDS deducted", m["tds_deducted"]),
        (),
    ]
    headers = ("Item", "Description", "UOM", "Ordered", "Rate", "Ordered value",
               "Measured", "Measured value", "Billed", "Billed value",
               "Unbilled", "Unbilled value", "% measured")
    rows = [(l["fg_code"], l["description"], l["uom"], l["ordered_qty"], l["rate"],
             l["ordered_value"], l["measured_qty"], l["measured_value"],
             l["billed_qty"], l["billed_value"], l["unbilled_qty"],
             l["unbilled_value"], l["percent_measured"]) for l in s["lines"]]
    closing = [(), ("Totals", "", "", "", "", o["revised_value"], "",
                    p["measured_value"], "", m["claimed"], "", m["measured_not_billed"])]
    return sheet_response(headers, rows,
                          "statement_%s.xlsx" % (wo.number or "order").replace("/", "-"),
                          preamble=preamble, closing=closing)




# ============================================================================
# STOCK AND MATERIAL CONTROL
#
# The item master said what may be bought and the goods receipt said what
# arrived. Nothing said what is in the store, what went out to site, or what
# is left - so material could be received, paid for, and quietly walk off
# without a single figure changing anywhere in the app.
#
# Every movement is a signed row and the balance is their sum, the same shape
# as the measurement book. A miscount is corrected by posting the correction,
# never by editing history.
# ============================================================================

STOCK_KINDS = ("RECEIPT", "ISSUE", "RETURN", "ADJUSTMENT", "TRANSFER_OUT", "TRANSFER_IN")


def stock_movement(db, client_id, item_code, kind, quantity, rate, **kw):
    """Write one row. The only way stock ever changes."""
    item = db.query(models.DBItem).filter(
        models.DBItem.client_id == client_id,
        models.DBItem.item_code == item_code).first()
    row = models.DBStockMovement(
        client_id=client_id, item_code=item_code,
        item_name=kw.get("item_name") or (item.item_name if item else ""),
        uom=kw.get("uom") or (item.units_of_measure if item else ""),
        store=kw.get("store") or "Main store",
        kind=kind, quantity=money(quantity), rate=unit_rate(rate),
        value=money(money(quantity) * unit_rate(rate)),
        moved_on=kw.get("moved_on") or datetime.now().strftime("%Y-%m-%d"),
        source_type=kw.get("source_type") or "manual",
        source_id=kw.get("source_id"), source_ref=kw.get("source_ref") or "",
        work_order_id=kw.get("work_order_id"), job_id=kw.get("job_id"),
        remarks=(kw.get("remarks") or "")[:400],
        recorded_by=kw.get("recorded_by"),
        recorded_by_name=kw.get("recorded_by_name") or "")
    db.add(row)
    apply_to_balance(db, client_id, row)
    return row


def apply_to_balance(db, client_id, m):
    """Fold one movement into the item's running balance."""
    bal = db.query(models.DBStockBalance).filter(
        models.DBStockBalance.client_id == client_id,
        models.DBStockBalance.item_code == m.item_code).first()
    if bal is None:
        bal = models.DBStockBalance(client_id=client_id, item_code=m.item_code,
                                    item_name=m.item_name or "", uom=m.uom or "")
        db.add(bal)
    if m.item_name and not bal.item_name:
        bal.item_name = m.item_name
    if m.uom and not bal.uom:
        bal.uom = m.uom
    qty = m.quantity or 0.0
    moved = (m.kind or "").startswith("TRANSFER")
    bal.movements = (bal.movements or 0) + 1
    if qty > 0:
        if not moved:
            bal.received = money((bal.received or 0) + qty)
        bal.value = money((bal.value or 0) + (m.value or 0))
        bal.on_hand = money((bal.on_hand or 0) + qty)
        bal.rate = unit_rate(bal.value / bal.on_hand) if bal.on_hand else 0.0
    else:
        if not moved:
            bal.issued = money((bal.issued or 0) - qty)
        bal.on_hand = money((bal.on_hand or 0) + qty)
        bal.value = money(bal.on_hand * (bal.rate or 0))
    bal.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return bal


def rebuild_stock_balances(db, client_id):
    """Replay the ledger from the start and overwrite every balance.

    The one door for doubt: if a balance is ever questioned, this makes it
    agree with the ledger again, because the ledger is the truth.
    """
    replayed = replay_stock_ledger(db, client_id)
    db.query(models.DBStockBalance).filter(
        models.DBStockBalance.client_id == client_id).delete()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for code, a in replayed.items():
        db.add(models.DBStockBalance(
            client_id=client_id, item_code=code, item_name=a["item_name"],
            uom=a["uom"], on_hand=money(a["on_hand"]), rate=unit_rate(a["rate"]),
            value=money(a["value"]), received=money(a["received"]),
            issued=money(a["issued"]), movements=a["movements"], updated_at=now))
    db.flush()
    return len(replayed)


def stock_balances(db, client_id, item_code=None, store=None, item_codes=None):
    """On hand per item, from the running balance.

    Falls back to replaying the ledger only when asked for one store, which
    the balance does not split by, or when the balance table is empty and the
    ledger is not - which is the first request after this table was added.
    """
    if store:
        return replay_stock_ledger(db, client_id, item_code=item_code,
                                   store=store, item_codes=item_codes)
    q = db.query(models.DBStockBalance).filter(
        models.DBStockBalance.client_id == client_id)
    if item_code:
        q = q.filter(models.DBStockBalance.item_code == item_code)
    elif item_codes is not None:
        if not item_codes:
            return {}
        q = q.filter(models.DBStockBalance.item_code.in_(list(item_codes)))
    rows = q.all()
    if not rows and item_code is None and item_codes is None:
        # Nothing summarised yet. If there is a ledger, this is the migration
        # moment: build the balances once, then serve from them for ever.
        if db.query(models.DBStockMovement.id).filter(
                models.DBStockMovement.client_id == client_id).first():
            rebuild_stock_balances(db, client_id)
            db.commit()
            rows = q.all()
    return {b.item_code: {
        "item_code": b.item_code, "item_name": b.item_name or "", "uom": b.uom or "",
        "received": money(b.received), "issued": money(b.issued),
        "on_hand": money(b.on_hand), "value": money(b.value),
        "rate": unit_rate(b.rate), "movements": b.movements or 0,
    } for b in rows}


def replay_stock_ledger(db, client_id, item_code=None, store=None, item_codes=None):
    """On hand per item, replayed from every movement in order.

    The slow path, and the authoritative one. Valued at what it actually cost:

    Weighted average, not the last rate paid: cement bought at three prices
    over a month is one heap in the yard, and issuing it at whichever price
    happened to be last makes the job cost jump for no reason on site.
    """
    q = db.query(models.DBStockMovement).filter(
        models.DBStockMovement.client_id == client_id)
    if item_code:
        q = q.filter(models.DBStockMovement.item_code == item_code)
    elif item_codes is not None:
        # Only the heaps that were asked about. A five-line issue note used to
        # walk the whole year's ledger to price its five items.
        if not item_codes:
            return {}
        q = q.filter(models.DBStockMovement.item_code.in_(list(item_codes)))
    if store:
        q = q.filter(models.DBStockMovement.store == store)

    acc = {}
    for m in q.order_by(models.DBStockMovement.id).all():
        a = acc.setdefault(m.item_code, {
            "item_code": m.item_code, "item_name": m.item_name or "",
            "uom": m.uom or "", "received": 0.0, "issued": 0.0,
            "on_hand": 0.0, "value": 0.0, "rate": 0.0, "movements": 0})
        a["movements"] += 1
        if m.item_name and not a["item_name"]:
            a["item_name"] = m.item_name
        qty = m.quantity or 0.0
        moved = (m.kind or "").startswith("TRANSFER")
        if qty > 0:
            if not moved:
                a["received"] += qty
            # Incoming stock re-averages the heap.
            a["value"] = money(a["value"] + (m.value or 0.0))
            a["on_hand"] = money(a["on_hand"] + qty)
            a["rate"] = unit_rate(a["value"] / a["on_hand"]) if a["on_hand"] else 0.0
        else:
            if not moved:
                a["issued"] += -qty
            # Going out at the average, so the heap's rate does not move.
            a["on_hand"] = money(a["on_hand"] + qty)
            a["value"] = money(a["on_hand"] * a["rate"])
    return acc


def item_rate(db, client_id, item_code):
    """What one unit is currently worth, for issuing at cost."""
    bal = stock_balances(db, client_id, item_code=item_code).get(item_code)
    return unit_rate(bal["rate"]) if bal else 0.0


@app.get("/api/stock")
def stock_on_hand(request: Request, store: str = "", low_only: bool = False,
                  db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    balances = stock_balances(db, client.id, store=store or None)
    levels = {i.item_code: (i.reorder_level or 0.0)
              for i in db.query(models.DBItem).filter(
                  models.DBItem.client_id == client.id).all()}

    rows = []
    for code, a in balances.items():
        level = levels.get(code, 0.0)
        a = dict(a)
        a["received"] = money(a["received"])
        a["issued"] = money(a["issued"])
        a["reorder_level"] = money(level)
        # A level of zero means nobody set one, which is not the same as
        # "never warn" - so it stays quiet rather than shouting about
        # every item in the yard.
        a["below_level"] = bool(level) and a["on_hand"] < level
        a["negative"] = a["on_hand"] < 0
        rows.append(a)
    rows.sort(key=lambda r: (not r["below_level"], r["item_code"]))
    if low_only:
        rows = [r for r in rows if r["below_level"]]

    return {
        "stock": rows,
        "summary": {
            "items_held": len([r for r in rows if r["on_hand"] > 0]),
            "value_on_hand": money(sum(r["value"] for r in rows)),
            "below_reorder": len([r for r in rows if r["below_level"]]),
            # Issued more than was ever received: the store is telling you
            # its own records are wrong, which is worth surfacing loudly.
            "negative_lines": len([r for r in rows if r["negative"]]),
        },
    }


@app.post("/api/stock/rebuild")
def rebuild_balances(request: Request, db: Session = Depends(get_db)):
    """Replay the ledger and overwrite the running balances.

    Reports what changed, because a balance that had drifted from its ledger
    is worth knowing about - it means something wrote stock without going
    through the one door that should.
    """
    client, _, actor_name = wo_actor(request, db)
    before = {b.item_code: money(b.on_hand) for b in db.query(models.DBStockBalance).filter(
        models.DBStockBalance.client_id == client.id).all()}
    n = rebuild_stock_balances(db, client.id)
    after = {b.item_code: money(b.on_hand) for b in db.query(models.DBStockBalance).filter(
        models.DBStockBalance.client_id == client.id).all()}
    drift = [{"item_code": k, "was": before.get(k, 0.0), "now": v}
             for k, v in after.items() if money(before.get(k, 0.0)) != v]
    log_audit(db, client.id, "stock_rebuilt", "item", None, "",
              "%d items, %d drifted" % (n, len(drift)), request)
    db.commit()
    return {"ok": True, "items": n, "drift": drift,
            "message": ("Rebuilt %d balances from the ledger. " % n) +
                       ("All agreed." if not drift else
                        "%d had drifted and are corrected." % len(drift))}


@app.get("/api/stock/{item_code}/ledger")
def stock_ledger(item_code: str, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    rows = db.query(models.DBStockMovement).filter(
        models.DBStockMovement.client_id == client.id,
        models.DBStockMovement.item_code == item_code).order_by(
            models.DBStockMovement.id).all()
    running, out = 0.0, []
    for m in rows:
        running = money(running + (m.quantity or 0))
        out.append({
            "id": m.id, "kind": m.kind, "moved_on": m.moved_on or "",
            "quantity": money(m.quantity), "rate": unit_rate(m.rate),
            "value": money(m.value), "balance": running,
            "store": m.store or "", "source_type": m.source_type or "",
            "source_id": m.source_id, "source_ref": m.source_ref or "",
            "remarks": m.remarks or "", "recorded_by_name": m.recorded_by_name or "",
        })
    bal = stock_balances(db, client.id, item_code=item_code).get(item_code, {})
    return {"item_code": item_code, "item_name": bal.get("item_name", ""),
            "uom": bal.get("uom", ""), "on_hand": money(bal.get("on_hand", 0)),
            "rate": unit_rate(bal.get("rate", 0)), "value": money(bal.get("value", 0)),
            "movements": list(reversed(out))}


# --- Issuing to site ---------------------------------------------------------

def store_holding(db, client_id, lines):
    """The store an issue with no store named is drawn from: the one that
    holds enough of everything on it, else the one holding most of the first
    item. It used to be "Main store" whatever - material received into a site
    store was issued out of an empty main store, which went negative while
    the site store never went down."""
    wanted = {}
    for l in lines or []:
        code = (l.get("item_code") or l.get("code") or "").strip()
        try:
            qty = float(l.get("quantity") if l.get("quantity") is not None else l.get("qty") or 0)
        except (TypeError, ValueError):
            qty = 0.0
        if code and qty > 0:
            wanted[code] = wanted.get(code, 0.0) + qty
    if not wanted:
        return "Main store"
    names = sorted({s for (s,) in db.query(models.DBStockMovement.store).filter(
        models.DBStockMovement.client_id == client_id,
        models.DBStockMovement.item_code.in_(list(wanted))).distinct().all() if s})
    best, best_qty = "", -1.0
    first = next(iter(wanted))
    for name in names:
        held = replay_stock_ledger(db, client_id, store=name, item_codes=list(wanted))
        if all((held.get(c) or {}).get("on_hand", 0) >= q - 1e-9 for c, q in wanted.items()):
            return name
        have = (held.get(first) or {}).get("on_hand", 0)
        if have > best_qty:
            best, best_qty = name, have
    return best or "Main store"


class StockIssueIn(BaseModel):
    work_order_id: Optional[int] = None
    job_id: Optional[int] = None
    issued_on: Optional[str] = ""
    issued_to: Optional[str] = ""
    purpose: Optional[str] = ""
    store: Optional[str] = ""
    remarks: Optional[str] = ""
    lines: Optional[list] = None


def next_issue_number(db, client_id):
    n = db.query(models.DBStockIssue).filter(
        models.DBStockIssue.client_id == client_id).count() + 1
    return "ISS-%04d" % n


def issue_or_404(db, client_id, issue_id):
    row = db.query(models.DBStockIssue).filter(
        models.DBStockIssue.id == issue_id,
        models.DBStockIssue.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Issue note not found")
    return row


def issue_dict(db, issue, detail=False, wo_names=None):
    if wo_names is not None:
        wo = None
        wo_number = wo_names.get(issue.work_order_id, "")
    else:
        wo = db.query(models.DBWorkOrder).filter(
            models.DBWorkOrder.id == issue.work_order_id).first() if issue.work_order_id else None
        wo_number = wo.number if wo else ""
    row = {
        "id": issue.id, "number": issue.number or "",
        "work_order_id": issue.work_order_id,
        "work_order": wo_number,
        "issued_on": issue.issued_on or "", "store": issue.store or "",
        "status": issue.status or "DRAFT", "issued_to": issue.issued_to or "",
        "purpose": issue.purpose or "", "total_value": money(issue.total_value),
        "issued_by_name": issue.issued_by_name or "",
        "remarks": issue.remarks or "", "posted_at": issue.posted_at or "",
        "editable": (issue.status or "DRAFT") == "DRAFT",
        "created_at": issue.created_at or "",
    }
    if detail:
        lines = db.query(models.DBStockIssueLine).filter(
            models.DBStockIssueLine.stock_issue_id == issue.id).order_by(
                models.DBStockIssueLine.display_order,
                models.DBStockIssueLine.id).all()
        # One pass over the ledger for the items on the note - not one per line,
        # and not the whole year's movements for everything in the store.
        balances = stock_balances(db, issue.client_id,
                                  item_codes={l.item_code for l in lines}) if lines else {}
        row["lines"] = [{
            "id": l.id, "item_code": l.item_code or "", "item_name": l.item_name or "",
            "uom": l.uom or "", "quantity": money(l.quantity),
            "rate": unit_rate(l.rate), "amount": money(l.amount),
            "on_hand": money(balances.get(l.item_code, {}).get("on_hand", 0)),
        } for l in lines]
    return row


@app.get("/api/stock-issues")
def list_stock_issues(request: Request, work_order_id: int = 0,
                      db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBStockIssue).filter(
        models.DBStockIssue.client_id == client.id)
    if work_order_id:
        q = q.filter(models.DBStockIssue.work_order_id == work_order_id)
    issues = q.order_by(models.DBStockIssue.id.desc()).limit(200).all()
    wo_names = {w.id: (w.number or "") for w in db.query(
        models.DBWorkOrder.id, models.DBWorkOrder.number).filter(
            models.DBWorkOrder.client_id == client.id).all()}
    rows = [issue_dict(db, i, wo_names=wo_names) for i in issues]
    return {
        "issues": rows,
        "summary": {
            "notes": len(rows),
            "not_yet_posted": len([r for r in rows if r["status"] == "DRAFT"]),
            "issued_value": money(sum(r["total_value"] for r in rows
                                      if r["status"] == "POSTED")),
        },
    }


@app.post("/api/stock-issues")
def create_stock_issue(body: StockIssueIn, request: Request,
                       db: Session = Depends(get_db)):
    """Draw up an issue note, priced at what the store's stock actually cost."""
    client, actor_id, actor_name = wo_actor(request, db)
    wo = None
    if body.work_order_id:
        wo = work_order_or_404(db, client.id, body.work_order_id)
    # Material goes to a site before its order is placed - mobilisation, the
    # first pour on a letter of intent. Issued "not against an order" it was
    # charged to no project at all; the project can be named on its own.
    job_id = wo.job_id if wo else (job_or_404(db, client.id, body.job_id).id if body.job_id else None)

    issue = models.DBStockIssue(
        client_id=client.id, work_order_id=(wo.id if wo else None),
        job_id=job_id,
        number=next_issue_number(db, client.id),
        issued_on=(body.issued_on or datetime.now().strftime("%Y-%m-%d")),
        store=((body.store or "").strip() or store_holding(db, client.id, body.lines or [])),
        status="DRAFT",
        issued_to=(body.issued_to or "").strip(),
        purpose=(body.purpose or "").strip(),
        remarks=(body.remarks or "").strip(),
        issued_by=actor_id, issued_by_name=actor_name)
    db.add(issue)
    db.flush()
    _replace_issue_lines(db, client.id, issue, body.lines or [])
    db.commit()
    db.refresh(issue)
    return {"ok": True, "issue": issue_dict(db, issue, detail=True),
            "message": "%s opened." % issue.number}


def _replace_issue_lines(db, client_id, issue, lines):
    db.query(models.DBStockIssueLine).filter(
        models.DBStockIssueLine.stock_issue_id == issue.id).delete()
    total = 0.0
    kept, refused = 0, []
    for i, l in enumerate(lines[:400]):
        code = (l.get("item_code") or l.get("code") or "").strip()
        # Every other document in this app calls it qty. An issue note that
        # accepted only "quantity" dropped the line, saved an empty note and
        # still answered "opened" - the mistake is only found later, when the
        # note refuses to be posted.
        raw_qty = l.get("quantity")
        if raw_qty is None:
            raw_qty = l.get("qty")
        qty = money(raw_qty or 0)
        if not code:
            refused.append("line %d has no item code" % (i + 1))
            continue
        if not qty:
            refused.append("%s has no quantity" % code)
            continue
        item = db.query(models.DBItem).filter(
            models.DBItem.client_id == client_id,
            models.DBItem.item_code == code).first()
        if not item:
            refused.append("%s is not in the item master" % code)
            continue
        # Priced from the store, not typed in: an issue is a transfer of value
        # out of stock, and letting somebody name the rate makes the store and
        # the job cost disagree.
        rate = unit_rate(l.get("rate") if l.get("rate") is not None
                         else item_rate(db, client_id, code))
        amount = money(qty * rate)
        total += amount
        db.add(models.DBStockIssueLine(
            stock_issue_id=issue.id, item_code=code,
            item_name=(l.get("item_name") or (item.item_name if item else ""))[:300],
            uom=(l.get("uom") or (item.units_of_measure if item else ""))[:40],
            quantity=qty, rate=rate, amount=amount, display_order=i))
        kept += 1
    # Lines that were sent and did not land must not disappear behind a
    # cheerful message. An empty note that says it opened is found later, at
    # the store, by somebody holding a lorry.
    if lines and not kept:
        raise HTTPException(400, "Nothing could be issued: " + "; ".join(refused[:5]) + ".")
    if refused:
        logger.warning("Issue note %s: %s", issue.number, "; ".join(refused[:10]))
    issue.total_value = money(total)
    issue.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    db.flush()
    return issue


@app.get("/api/stock-issues/{issue_id}")
def get_stock_issue(issue_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return issue_dict(db, issue_or_404(db, client.id, issue_id), detail=True)


@app.put("/api/stock-issues/{issue_id}")
def update_stock_issue(issue_id: int, body: StockIssueIn, request: Request,
                       db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    issue = issue_or_404(db, client.id, issue_id)
    if (issue.status or "DRAFT") != "DRAFT":
        raise HTTPException(409, "A posted issue cannot be changed. "
                                 "Post a return instead.")
    for field in ("issued_on", "issued_to", "purpose", "store", "remarks"):
        val = getattr(body, field, None)
        if val is not None and val != "":
            setattr(issue, field, val)
    if body.lines is not None:
        _replace_issue_lines(db, client.id, issue, body.lines)
    db.commit()
    db.refresh(issue)
    return {"ok": True, "issue": issue_dict(db, issue, detail=True)}


@app.post("/api/stock-issues/{issue_id}/post")
def post_stock_issue(issue_id: int, request: Request, body: dict = None,
                     db: Session = Depends(get_db)):
    """Take it out of the store. This is where stock actually moves."""
    client, actor_id, actor_name = wo_actor(request, db)
    issue = issue_or_404(db, client.id, issue_id)
    if (issue.status or "DRAFT") != "DRAFT":
        raise HTTPException(409, "Only a draft can be posted.")
    lines = db.query(models.DBStockIssueLine).filter(
        models.DBStockIssueLine.stock_issue_id == issue.id).all()
    if not lines:
        raise HTTPException(400, "Nothing on this issue note.")

    allow_negative = bool((body or {}).get("allow_negative"))
    short = []
    for l in lines:
        on_hand = money(stock_balances(db, client.id, item_code=l.item_code).get(
            l.item_code, {}).get("on_hand", 0))
        if l.quantity > on_hand:
            short.append("%s: %s in store, %s asked for"
                         % (l.item_code, on_hand, money(l.quantity)))
    if short and not allow_negative:
        # Refused rather than silently going negative: material that is not
        # there has either not been booked in or has already gone, and both
        # want looking at before more is issued on paper.
        raise HTTPException(409, "Not enough in the store - %s. Book the "
                                 "delivery in first, or post it anyway if the "
                                 "store is behind." % "; ".join(short[:4]))

    # Handed to a gang whose rate includes the material: the order says which
    # project it was spent on, and it has to be known before the stock moves
    # or the movements are written against no project at all.
    recover_order = None
    recover_from = (body or {}).get("recover_from_order_id")
    if recover_from:
        recover_order = wo_or_404(db, client.id, int(recover_from))
        if (recover_order.status or "") not in ("APPROVED", "EXECUTED"):
            raise HTTPException(409, "%s is %s; material is charged to a live order."
                                     % (recover_order.wo_number,
                                        (recover_order.status or "").lower()))
        if not issue.job_id and recover_order.job_id:
            issue.job_id = recover_order.job_id

    for l in lines:
        stock_movement(db, client.id, l.item_code, "ISSUE", -l.quantity, l.rate,
                       item_name=l.item_name, uom=l.uom, store=issue.store,
                       moved_on=issue.issued_on, source_type="stock_issue",
                       source_id=issue.id, source_ref=issue.number,
                       work_order_id=issue.work_order_id, job_id=issue.job_id,
                       remarks=issue.purpose, recorded_by=actor_id,
                       recorded_by_name=actor_name)
    issue.status = "POSTED"
    issue.posted_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    # It is theirs to pay for, recovered from their next bill on its own.
    charged = 0.0
    if recover_order:
        charged = charge_issue_to_gang(db, client.id, issue, recover_order,
                                       float((body or {}).get("markup_percent") or 0))
        issue.issued_to = issue.issued_to or ("Recover from " + (recover_order.wo_number or ""))
    log_audit(db, client.id, "stock_issued", "stock_issue", issue.id,
              issue.number or "", "%s lines, %s" % (len(lines), inr(issue.total_value)),
              request)
    db.commit()
    db.refresh(issue)
    return {"ok": True, "issue": issue_dict(db, issue, detail=True),
            "message": "%s issued - %s of material has left the store."
                       % (issue.number, inr(issue.total_value))}


@app.post("/api/stock-issues/{issue_id}/cancel")
def cancel_stock_issue(issue_id: int, request: Request, body: dict = None,
                       db: Session = Depends(get_db)):
    """A posted issue is reversed by putting the material back, not erased."""
    client, actor_id, actor_name = wo_actor(request, db)
    issue = issue_or_404(db, client.id, issue_id)
    if (issue.status or "DRAFT") == "CANCELLED":
        raise HTTPException(409, "Already cancelled.")
    if (issue.status or "DRAFT") == "POSTED":
        for l in db.query(models.DBStockIssueLine).filter(
                models.DBStockIssueLine.stock_issue_id == issue.id).all():
            stock_movement(db, client.id, l.item_code, "RETURN", l.quantity, l.rate,
                           item_name=l.item_name, uom=l.uom, store=issue.store,
                           source_type="stock_issue", source_id=issue.id,
                           source_ref=issue.number + " cancelled",
                           work_order_id=issue.work_order_id, job_id=issue.job_id,
                           remarks="Issue cancelled", recorded_by=actor_id,
                           recorded_by_name=actor_name)
    issue.status = "CANCELLED"
    issue.remarks = ((body or {}).get("comments") or issue.remarks or "")
    db.commit()
    return {"ok": True, "message": "%s cancelled and the material put back."
                                   % issue.number}


class AdjustmentIn(BaseModel):
    item_code: str
    counted: float
    store: Optional[str] = ""
    remarks: Optional[str] = ""


@app.post("/api/stock/adjustments")
def adjust_stock(body: AdjustmentIn, request: Request,
                 db: Session = Depends(get_db)):
    """A physical count. The difference is posted, the history is left alone."""
    client, actor_id, actor_name = wo_actor(request, db)
    code = (body.item_code or "").strip()
    bal = stock_balances(db, client.id, item_code=code).get(code, {})
    on_hand = money(bal.get("on_hand", 0))
    difference = money(money(body.counted) - on_hand)
    if not difference:
        return {"ok": True, "difference": 0,
                "message": "The count agrees with the book. Nothing posted."}
    stock_movement(db, client.id, code, "ADJUSTMENT", difference,
                   bal.get("rate", 0), store=body.store or "Main store",
                   source_type="manual", source_ref="Physical count",
                   remarks=(body.remarks or "Physical count"),
                   recorded_by=actor_id, recorded_by_name=actor_name)
    log_audit(db, client.id, "stock_adjusted", "item", None, code,
              "book %s counted %s" % (on_hand, money(body.counted)), request)
    db.commit()
    return {"ok": True, "was": on_hand, "now": money(body.counted),
            "difference": difference,
            "message": "%s %s %s." % (code,
                                      "written down by" if difference < 0 else "written up by",
                                      abs(difference))}


# --- What the job was supposed to use, against what it did -------------------

@app.get("/api/stock/consumption/{work_order_id}")
def material_consumption(work_order_id: int, request: Request,
                         db: Session = Depends(get_db)):
    """BOM against actual issues - the wastage report.

    The BOM is what the contract was costed on. The issues are what the site
    actually drew. The gap between them is waste, theft, or a BOM that was
    wrong, and on a material-heavy contract it is the difference between the
    margin that was signed off and the one that turns up.
    """
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, work_order_id)

    planned = {}
    for b in db.query(models.DBBomLine).filter(
            models.DBBomLine.work_order_id == wo.id).all():
        p = planned.setdefault(b.rm_code, {
            "item_code": b.rm_code, "item_name": b.rm_name or "",
            "uom": b.uom or "", "planned_qty": 0.0, "planned_value": 0.0})
        p["planned_qty"] = money(p["planned_qty"] + (b.qty or 0))
        p["planned_value"] = money(p["planned_value"] + (b.amount or 0))

    actual = {}
    for m in db.query(models.DBStockMovement).filter(
            models.DBStockMovement.client_id == client.id,
            models.DBStockMovement.work_order_id == wo.id).all():
        a = actual.setdefault(m.item_code, {"qty": 0.0, "value": 0.0})
        # An issue is negative and a return positive, so consumption is the
        # negated sum and a cancelled issue costs the job nothing.
        a["qty"] = money(a["qty"] - (m.quantity or 0))
        a["value"] = money(a["value"] - (m.value or 0))

    rows = []
    for code in sorted(set(planned) | set(actual)):
        p = planned.get(code, {"item_code": code, "item_name": "", "uom": "",
                               "planned_qty": 0.0, "planned_value": 0.0})
        a = actual.get(code, {"qty": 0.0, "value": 0.0})
        over = money(a["qty"] - p["planned_qty"])
        rows.append({
            "item_code": code, "item_name": p["item_name"], "uom": p["uom"],
            "planned_qty": p["planned_qty"], "planned_value": p["planned_value"],
            "issued_qty": a["qty"], "issued_value": a["value"],
            "variance_qty": over,
            "variance_value": money(a["value"] - p["planned_value"]),
            "percent_used": (round(a["qty"] / p["planned_qty"] * 100, 1)
                             if p["planned_qty"] else 0.0),
            "over_consumed": over > 0,
            # Drawn without ever being budgeted: usually a BOM nobody updated
            # after a variation, occasionally something worse.
            "unplanned": p["planned_qty"] == 0 and a["qty"] > 0,
        })

    return {
        "work_order": work_order_to_dict(db, wo),
        "lines": rows,
        "summary": {
            "planned_value": money(sum(r["planned_value"] for r in rows)),
            "issued_value": money(sum(r["issued_value"] for r in rows)),
            "variance_value": money(sum(r["variance_value"] for r in rows)),
            "lines_over_consumed": len([r for r in rows if r["over_consumed"]]),
            "unplanned_items": len([r for r in rows if r["unplanned"]]),
        },
    }


@app.get("/api/stock.xlsx")
def stock_export(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    balances = stock_balances(db, client.id)
    levels = {i.item_code: (i.reorder_level or 0.0)
              for i in db.query(models.DBItem).filter(
                  models.DBItem.client_id == client.id).all()}
    rows = [(a["item_code"], a["item_name"], a["uom"], money(a["received"]),
             money(a["issued"]), a["on_hand"], unit_rate(a["rate"]), a["value"],
             money(levels.get(code, 0.0)),
             "yes" if levels.get(code, 0.0) and a["on_hand"] < levels[code] else "")
            for code, a in sorted(balances.items())]
    return sheet_response(
        ("Item code", "Description", "UOM", "Received", "Issued", "On hand",
         "Rate", "Value", "Reorder level", "Below level"),
        rows, "stock_on_hand.xlsx",
        preamble=[("STOCK ON HAND", client.company_name or ""),
                  ("As at", datetime.now().strftime("%Y-%m-%d")),
                  ()],
        closing=[(), ("Total value", "", "", "", "", "", "",
                      money(sum(r[7] for r in rows)))])




# ============================================================================
# THE SITE DIARY
#
# The daily record a site actually keeps. On a civil contract it is the
# document that settles a delay claim two years later, and it is also the
# only place the labour that went into the work is written down - so it is
# what turns "the job cost this much in material" into a real cost.
# ============================================================================

WEATHER = ("Clear", "Cloudy", "Rain", "Heavy rain")
TRADES = ("Mason", "Helper", "Carpenter", "Bar bender", "Fitter", "Electrician",
          "Plumber", "Painter", "Operator", "Driver", "Surveyor", "Supervisor")


def diary_or_404(db, client_id, diary_id):
    row = db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.id == diary_id,
        models.DBSiteDiary.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Diary not found")
    return row


def recost_diary(db, diary):
    """A manday is a head for the site's working day, not for a clock hour.

    Half a day is half a manday, and overtime shows up as more than one -
    which is what makes the labour histogram comparable across weeks where
    the site worked different hours.
    """
    labour = db.query(models.DBDiaryLabour).filter(
        models.DBDiaryLabour.site_diary_id == diary.id).all()
    plant = db.query(models.DBDiaryPlant).filter(
        models.DBDiaryPlant.site_diary_id == diary.id).all()
    day = diary.working_hours or 8.0

    mandays = 0.0
    for l in labour:
        heads = l.headcount or 0
        share = (l.hours or day) / day if day else 1.0
        mandays += heads * share
        l.amount = money(heads * share * (l.rate or 0))
    for p in plant:
        # Idle time is charged too. Plant that stood all day still costs
        # money, and hiding it is how a hire bill becomes a surprise.
        p.amount = money(((p.worked_hours or 0) + (p.idle_hours or 0)) * (p.rate or 0))

    diary.total_mandays = money(mandays)
    diary.labour_cost = money(sum(l.amount or 0 for l in labour))
    diary.plant_cost = money(sum(p.amount or 0 for p in plant))
    diary.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return diary


def diary_dict(db, d, detail=False):
    job = db.query(models.DBJob).filter(models.DBJob.id == d.job_id).first()
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == d.work_order_id).first() if d.work_order_id else None
    row = {
        "id": d.id, "job_id": d.job_id,
        "project": ("%s %s" % (job.number or "", job.name or "")).strip() if job else "",
        "work_order_id": d.work_order_id, "work_order": wo.number if wo else "",
        "diary_date": d.diary_date or "", "weather": d.weather or "Clear",
        "rain_hours": money(d.rain_hours), "working_hours": money(d.working_hours),
        "work_done": d.work_done or "", "holdups": d.holdups or "",
        "instructions": d.instructions or "", "visitors": d.visitors or "",
        "safety_note": d.safety_note or "",
        "labour_cost": money(d.labour_cost), "plant_cost": money(d.plant_cost),
        "day_cost": money((d.labour_cost or 0) + (d.plant_cost or 0)),
        "total_mandays": money(d.total_mandays),
        "status": d.status or "DRAFT", "prepared_by_name": d.prepared_by_name or "",
        "submitted_at": d.submitted_at or "",
        "editable": (d.status or "DRAFT") == "DRAFT",
        # A day the site was rained off is worth seeing at a glance.
        "lost_to_weather": bool((d.rain_hours or 0) >= (d.working_hours or 8) / 2),
        "created_at": d.created_at or "",
    }
    if detail:
        row["labour"] = [{
            "id": l.id, "trade": l.trade or "", "agency": l.agency or "Own",
            "headcount": money(l.headcount), "hours": money(l.hours),
            "rate": money(l.rate), "amount": money(l.amount),
        } for l in db.query(models.DBDiaryLabour).filter(
            models.DBDiaryLabour.site_diary_id == d.id).order_by(
                models.DBDiaryLabour.display_order, models.DBDiaryLabour.id).all()]
        row["plant"] = [{
            "id": p.id, "plant": p.plant or "",
            "worked_hours": money(p.worked_hours), "idle_hours": money(p.idle_hours),
            "rate": money(p.rate), "amount": money(p.amount),
            "remarks": p.remarks or "",
        } for p in db.query(models.DBDiaryPlant).filter(
            models.DBDiaryPlant.site_diary_id == d.id).order_by(
                models.DBDiaryPlant.display_order, models.DBDiaryPlant.id).all()]
    return row


class DiaryIn(BaseModel):
    job_id: Optional[int] = None
    work_order_id: Optional[int] = None
    diary_date: Optional[str] = ""
    weather: Optional[str] = ""
    rain_hours: Optional[float] = None
    working_hours: Optional[float] = None
    work_done: Optional[str] = None
    holdups: Optional[str] = None
    instructions: Optional[str] = None
    visitors: Optional[str] = None
    safety_note: Optional[str] = None
    labour: Optional[list] = None
    plant: Optional[list] = None


def _replace_diary_lines(db, diary, labour, plant):
    if labour is not None:
        db.query(models.DBDiaryLabour).filter(
            models.DBDiaryLabour.site_diary_id == diary.id).delete()
        for i, l in enumerate((labour or [])[:60]):
            heads = money(l.get("headcount") or 0)
            if not heads:
                continue
            db.add(models.DBDiaryLabour(
                site_diary_id=diary.id, trade=(l.get("trade") or "")[:80],
                agency=(l.get("agency") or "Own")[:120], headcount=heads,
                hours=money(l.get("hours") if l.get("hours") is not None
                            else (diary.working_hours or 8)),
                rate=money(l.get("rate") or 0), display_order=i))
    if plant is not None:
        db.query(models.DBDiaryPlant).filter(
            models.DBDiaryPlant.site_diary_id == diary.id).delete()
        for i, p in enumerate((plant or [])[:60]):
            name = (p.get("plant") or "").strip()
            if not name:
                continue
            db.add(models.DBDiaryPlant(
                site_diary_id=diary.id, plant=name[:160],
                worked_hours=money(p.get("worked_hours") or 0),
                idle_hours=money(p.get("idle_hours") or 0),
                rate=money(p.get("rate") or 0),
                remarks=(p.get("remarks") or "")[:300], display_order=i))
    db.flush()
    recost_diary(db, diary)


@app.get("/api/diary")
def list_diaries(request: Request, job_id: int = 0, date_from: str = "",
                 date_to: str = "", db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.client_id == client.id)
    if job_id:
        q = q.filter(models.DBSiteDiary.job_id == job_id)
    if date_from:
        q = q.filter(models.DBSiteDiary.diary_date >= date_from)
    if date_to:
        q = q.filter(models.DBSiteDiary.diary_date <= date_to)
    rows = [diary_dict(db, d) for d in q.order_by(
        models.DBSiteDiary.diary_date.desc(),
        models.DBSiteDiary.id.desc()).limit(400).all()]
    return {
        "diaries": rows,
        "summary": {
            "days_recorded": len(rows),
            "mandays": money(sum(r["total_mandays"] for r in rows)),
            "labour_cost": money(sum(r["labour_cost"] for r in rows)),
            "plant_cost": money(sum(r["plant_cost"] for r in rows)),
            "days_lost_to_weather": len([r for r in rows if r["lost_to_weather"]]),
            "not_yet_submitted": len([r for r in rows if r["status"] == "DRAFT"]),
        },
    }


@app.post("/api/diary")
def create_diary(body: DiaryIn, request: Request, db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    if not body.job_id:
        raise HTTPException(400, "A diary belongs to a site.")
    job = db.query(models.DBJob).filter(
        models.DBJob.id == body.job_id,
        models.DBJob.client_id == client.id).first()
    if not job:
        raise HTTPException(404, "Project not found")

    on = (body.diary_date or datetime.now().strftime("%Y-%m-%d"))[:10]
    # One diary per site per day. Two records for the same day is how a delay
    # claim gets thrown out, so the second attempt reopens the first rather
    # than quietly creating a rival.
    existing = db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.client_id == client.id,
        models.DBSiteDiary.job_id == job.id,
        models.DBSiteDiary.diary_date == on).first()
    if existing:
        raise HTTPException(
            409, "There is already a diary for %s on %s. Open that one."
                 % (job.name or "this site", on))

    diary = models.DBSiteDiary(
        client_id=client.id, job_id=job.id, work_order_id=body.work_order_id,
        diary_date=on,
        weather=(body.weather if body.weather in WEATHER else "Clear"),
        rain_hours=money(body.rain_hours or 0),
        working_hours=money(body.working_hours if body.working_hours else 8),
        work_done=(body.work_done or "").strip(),
        holdups=(body.holdups or "").strip(),
        instructions=(body.instructions or "").strip(),
        visitors=(body.visitors or "").strip(),
        safety_note=(body.safety_note or "").strip(),
        status="DRAFT", prepared_by=actor_id, prepared_by_name=actor_name)
    db.add(diary)
    db.flush()
    _replace_diary_lines(db, diary, body.labour, body.plant)
    db.commit()
    db.refresh(diary)
    return {"ok": True, "diary": diary_dict(db, diary, detail=True),
            "message": "Diary opened for %s." % on}


@app.get("/api/diary/{diary_id}")
def get_diary(diary_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return diary_dict(db, diary_or_404(db, client.id, diary_id), detail=True)


@app.put("/api/diary/{diary_id}")
def update_diary(diary_id: int, body: DiaryIn, request: Request,
                 db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    diary = diary_or_404(db, client.id, diary_id)
    if (diary.status or "DRAFT") != "DRAFT":
        raise HTTPException(
            409, "This day has been signed off. A diary that can be rewritten "
                 "afterwards is worth nothing in a claim.")
    if body.weather in WEATHER:
        diary.weather = body.weather
    for field in ("rain_hours", "working_hours"):
        val = getattr(body, field, None)
        if val is not None:
            setattr(diary, field, money(val))
    for field in ("work_done", "holdups", "instructions", "visitors",
                  "safety_note"):
        val = getattr(body, field, None)
        if val is not None:
            setattr(diary, field, val.strip())
    if body.work_order_id is not None:
        diary.work_order_id = body.work_order_id or None
    _replace_diary_lines(db, diary, body.labour, body.plant)
    db.commit()
    db.refresh(diary)
    return {"ok": True, "diary": diary_dict(db, diary, detail=True)}


@app.post("/api/diary/{diary_id}/submit")
def submit_diary(diary_id: int, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    diary = diary_or_404(db, client.id, diary_id)
    if (diary.status or "DRAFT") != "DRAFT":
        raise HTTPException(409, "Already signed off.")
    if not (diary.work_done or "").strip():
        raise HTTPException(
            400, "Say what was done. A day with no record of the work is not "
                 "a diary entry.")
    diary.status = "SUBMITTED"
    diary.submitted_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_audit(db, client.id, "diary_submitted", "site_diary", diary.id,
              diary.diary_date or "", actor_name, request)
    db.commit()
    db.refresh(diary)
    return {"ok": True, "diary": diary_dict(db, diary, detail=True),
            "message": "%s signed off." % diary.diary_date}


@app.delete("/api/diary/{diary_id}")
def delete_diary(diary_id: int, request: Request, db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    diary = diary_or_404(db, client.id, diary_id)
    if (diary.status or "DRAFT") != "DRAFT":
        raise HTTPException(409, "A signed off day cannot be deleted.")
    db.query(models.DBDiaryLabour).filter(
        models.DBDiaryLabour.site_diary_id == diary.id).delete()
    db.query(models.DBDiaryPlant).filter(
        models.DBDiaryPlant.site_diary_id == diary.id).delete()
    db.delete(diary)
    db.commit()
    return {"ok": True, "message": "Draft diary removed."}


@app.get("/api/diary-labour/{job_id}")
def labour_history(job_id: int, request: Request, db: Session = Depends(get_db)):
    """Who has been on this site, by trade, over its whole life.

    The question a project manager asks on a Monday - am I carrying more
    masons than the work needs - and it cannot be answered from one day.
    """
    client = require_erp_read(request, db)
    job = db.query(models.DBJob).filter(
        models.DBJob.id == job_id, models.DBJob.client_id == client.id).first()
    if not job:
        raise HTTPException(404, "Project not found")

    diaries = db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.client_id == client.id,
        models.DBSiteDiary.job_id == job.id).order_by(
            models.DBSiteDiary.diary_date).all()
    ids = [d.id for d in diaries]
    trades, agencies = {}, {}
    if ids:
        day_of = {d.id: (d.working_hours or 8.0) for d in diaries}
        for l in db.query(models.DBDiaryLabour).filter(
                models.DBDiaryLabour.site_diary_id.in_(ids)).all():
            day = day_of.get(l.site_diary_id, 8.0) or 8.0
            md = (l.headcount or 0) * ((l.hours or day) / day)
            t = trades.setdefault(l.trade or "Unstated",
                                  {"trade": l.trade or "Unstated",
                                   "mandays": 0.0, "cost": 0.0})
            t["mandays"] = money(t["mandays"] + md)
            t["cost"] = money(t["cost"] + (l.amount or 0))
            a = agencies.setdefault(l.agency or "Own",
                                    {"agency": l.agency or "Own",
                                     "mandays": 0.0, "cost": 0.0})
            a["mandays"] = money(a["mandays"] + md)
            a["cost"] = money(a["cost"] + (l.amount or 0))

    daily = [{"diary_date": d.diary_date or "", "mandays": money(d.total_mandays),
              "labour_cost": money(d.labour_cost), "plant_cost": money(d.plant_cost),
              "weather": d.weather or "", "rain_hours": money(d.rain_hours)}
             for d in diaries]
    worked = [d for d in daily if d["mandays"] > 0]
    return {
        "job": {"id": job.id, "number": job.number or "", "name": job.name or ""},
        "by_trade": sorted(trades.values(), key=lambda r: -r["mandays"]),
        "by_agency": sorted(agencies.values(), key=lambda r: -r["mandays"]),
        "daily": daily,
        "summary": {
            "days_recorded": len(daily),
            "days_worked": len(worked),
            "mandays": money(sum(r["mandays"] for r in daily)),
            "labour_cost": money(sum(r["labour_cost"] for r in daily)),
            "plant_cost": money(sum(r["plant_cost"] for r in daily)),
            "average_gang": (round(sum(r["mandays"] for r in worked) / len(worked), 1)
                             if worked else 0.0),
            "rain_hours": money(sum(r["rain_hours"] for r in daily)),
        },
    }


@app.get("/api/diary/{diary_id}/export.xlsx")
def diary_export(diary_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    d = diary_or_404(db, client.id, diary_id)
    row = diary_dict(db, d, detail=True)
    preamble = [
        ("DAILY PROGRESS REPORT", client.company_name or ""),
        ("Site", row["project"], "Date", row["diary_date"]),
        ("Weather", "%s (%s h rain)" % (row["weather"], row["rain_hours"]),
         "Working hours", row["working_hours"]),
        ("Prepared by", row["prepared_by_name"], "Status", row["status"]),
        (),
        ("Work done", row["work_done"]),
        ("Held up by", row["holdups"] or "-"),
        ("Instructions", row["instructions"] or "-"),
        ("Visitors", row["visitors"] or "-"),
        ("Safety", row["safety_note"] or "-"),
        (),
        ("LABOUR",),
    ]
    headers = ("Trade", "Agency", "Number", "Hours", "Rate", "Amount")
    rows = [(l["trade"], l["agency"], l["headcount"], l["hours"], l["rate"],
             l["amount"]) for l in row["labour"]]
    closing = [(), ("Mandays", row["total_mandays"], "", "", "Labour",
                    row["labour_cost"])]
    if row["plant"]:
        closing += [(), ("PLANT",),
                    ("Plant", "Worked", "Idle", "Rate", "Amount", "Remarks")]
        closing += [(p["plant"], p["worked_hours"], p["idle_hours"], p["rate"],
                     p["amount"], p["remarks"]) for p in row["plant"]]
        closing += [("", "", "", "Plant", row["plant_cost"])]
    closing += [(), ("Cost of the day", row["day_cost"])]
    return sheet_response(headers, rows,
                          "dpr_%s.xlsx" % (row["diary_date"] or "day"),
                          preamble=preamble, closing=closing)


# ============================================================================
# PROJECT PROFIT AND LOSS
#
# What a project earned against what it truly cost. The cost side had a hole
# in it until now: supplier bills were counted, but the material drawn out of
# the store and the labour standing on site were not, so a job could look
# profitable right up to the day the store was counted.
#
# Revenue is what has been certified, not what has been hoped for. A bill
# nobody has agreed to is not income, and treating it as such is how a
# contractor discovers a loss at the end instead of in the middle.
# ============================================================================

def stocked_share_of_bills(db, client_id):
    """{bill id: the share of the bill that paid for goods booked into the
    store} - its lines tied to order lines that carry a stock code and were
    received through a goods receipt. Bills typed in without lines are left
    whole; there is nothing to say what they bought."""
    bills = {b.id for b in db.query(models.DBBill.id).filter(
        models.DBBill.client_id == client_id,
        models.DBBill.purchase_order_id.isnot(None)).all()}
    if not bills:
        return {}
    stock_lines = {pl.id for pl in db.query(models.DBPurchaseOrderLineItem.id).join(
        models.DBPurchaseOrder, models.DBPurchaseOrder.id == models.DBPurchaseOrderLineItem.order_id).filter(
        models.DBPurchaseOrder.client_id == client_id,
        models.DBPurchaseOrderLineItem.item_code.isnot(None),
        models.DBPurchaseOrderLineItem.item_code != "").all()}
    received = {l.po_line_id for l in db.query(models.DBGoodsReceiptLine.po_line_id).join(
        models.DBGoodsReceipt, models.DBGoodsReceipt.id == models.DBGoodsReceiptLine.goods_receipt_id).filter(
        models.DBGoodsReceipt.client_id == client_id,
        models.DBGoodsReceipt.status == "POSTED").all() if l.po_line_id}
    whole, stock = {}, {}
    for l in db.query(models.DBBillLineItem).filter(models.DBBillLineItem.bill_id.in_(list(bills))).all():
        value = (l.qty or 0) * (l.price or 0)
        whole[l.bill_id] = whole.get(l.bill_id, 0.0) + value
        if l.po_line_id in stock_lines and l.po_line_id in received:
            stock[l.bill_id] = stock.get(l.bill_id, 0.0) + value
    return {b: min(1.0, stock[b] / whole[b]) for b in stock if whole.get(b)}


def preload_pnl_for_job(db, client_id, job_id):
    from collections import defaultdict
    def one(rows):
        return {job_id: rows}
    wos = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.client_id == client_id,
        models.DBWorkOrder.job_id == job_id).all()
    bom = defaultdict(float)
    ids = [w.id for w in wos]
    if ids:
        from sqlalchemy import func
        for wo_id, amt in db.query(models.DBBomLine.work_order_id,
                                   func.coalesce(func.sum(models.DBBomLine.amount), 0.0)).filter(
                models.DBBomLine.work_order_id.in_(ids)).group_by(
                    models.DBBomLine.work_order_id).all():
            bom[wo_id] = float(amt or 0)
    return {
        "wos": one(wos), "bom": bom,
        "invoices": one(db.query(models.DBInvoice).filter(
            models.DBInvoice.client_id == client_id, models.DBInvoice.job_id == job_id).all()),
        "ra": one(db.query(models.DBRABill).filter(
            models.DBRABill.job_id == job_id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all()),
        "bills": one(db.query(models.DBBill).filter(
            models.DBBill.client_id == client_id, models.DBBill.job_id == job_id).all()),
        "moves": one(db.query(models.DBStockMovement).filter(
            models.DBStockMovement.client_id == client_id,
            models.DBStockMovement.job_id == job_id,
            models.DBStockMovement.kind.in_(("ISSUE", "RETURN"))).all()),
        "diaries": one(db.query(models.DBSiteDiary).filter(
            models.DBSiteDiary.client_id == client_id, models.DBSiteDiary.job_id == job_id).all()),
        "pos": one(db.query(models.DBPurchaseOrder).filter(
            models.DBPurchaseOrder.client_id == client_id,
            models.DBPurchaseOrder.job_id == job_id).all()),
        "sub": one(db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client_id, models.DBSubBill.job_id == job_id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).all()),
        "released": one([r for r in _live_releases(db, client_id, "client") if r.job_id == job_id]),
        "equipment": {job_id: equipment_cost_by_job(db, client_id).get(job_id, 0.0)},
        "recovered": material_recovered_by_job(db, client_id, job_id),
        "stocked": stocked_share_of_bills(db, client_id),
    }


def preload_pnl(db, client_id):
    """Every table the P&L reads, loaded once and grouped by project.

    The portfolio used to ask nine questions per project, one project at a
    time; twenty projects was a hundred and eighty queries. Now it is nine,
    and the per-project figures come out of these dicts.
    """
    from collections import defaultdict
    def by_job(rows, key="job_id"):
        out = defaultdict(list)
        for r in rows:
            out[getattr(r, key)].append(r)
        return out
    wos = by_job(db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.client_id == client_id).all())
    wo_ids = [w.id for lst in wos.values() for w in lst]
    bom = defaultdict(float)
    if wo_ids:
        from sqlalchemy import func
        for wo_id, amt in db.query(models.DBBomLine.work_order_id,
                                   func.coalesce(func.sum(models.DBBomLine.amount), 0.0)).filter(
                models.DBBomLine.work_order_id.in_(wo_ids)).group_by(
                    models.DBBomLine.work_order_id).all():
            bom[wo_id] = float(amt or 0)
    return {
        "wos": wos, "bom": bom,
        "invoices": by_job(db.query(models.DBInvoice).filter(
            models.DBInvoice.client_id == client_id).all()),
        "ra": by_job(db.query(models.DBRABill).filter(
            models.DBRABill.client_id == client_id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all()),
        "bills": by_job(db.query(models.DBBill).filter(
            models.DBBill.client_id == client_id).all()),
        "moves": by_job(db.query(models.DBStockMovement).filter(
            models.DBStockMovement.client_id == client_id,
            models.DBStockMovement.kind.in_(("ISSUE", "RETURN"))).all()),
        "diaries": by_job(db.query(models.DBSiteDiary).filter(
            models.DBSiteDiary.client_id == client_id).all()),
        "pos": by_job(db.query(models.DBPurchaseOrder).filter(
            models.DBPurchaseOrder.client_id == client_id).all()),
        "sub": by_job(db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client_id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).all()),
        "released": by_job(_live_releases(db, client_id, "client")),
        "equipment": equipment_cost_by_job(db, client_id),
        "recovered": material_recovered_by_job(db, client_id),
        "stocked": stocked_share_of_bills(db, client_id),
    }


def project_pnl(db, client_id, job, pre=None):
    if pre is None:
        # A single project: the same nine questions, asked for one job only.
        pre = preload_pnl_for_job(db, client_id, job.id)
    wos = pre["wos"].get(job.id, [])
    live = [w for w in wos if (w.approval_status or "none") != "rejected"]
    wo_ids = [w.id for w in live]
    order_value = money(sum(w.total_value or 0 for w in live))

    # --- earned ----------------------------------------------------------
    invoices = [i for i in pre["invoices"].get(job.id, [])
                if (i.status or "") not in ("Draft", "Cancelled", "Void")]
    invoiced = money(sum(invoice_total(i) for i in invoices))
    collected = money(sum(i.paid or 0 for i in invoices))

    bills = pre["ra"].get(job.id, [])
    certified = money(sum(b.this_bill or 0 for b in bills))
    retention = money(sum(b.retention_amount or 0 for b in bills)
                      - sum(r.amount or 0 for r in (pre.get("released") or {}).get(job.id, [])))

    # --- what it cost ----------------------------------------------------
    supplier_bills = [b for b in pre["bills"].get(job.id, [])
                      if (b.approval_status or "none") != "rejected"
                      and (b.status or "") != "Cancelled"]
    # Material that went into the store is stock until it is issued, and the
    # issue is what charges it to the job. Counting the supplier's bill as
    # well charged it twice: 100 bags bought for a job and 60 issued showed
    # as 64,000 of cost for 24,000 of cement used. What a bill spent on
    # stocked items comes off here; its hire, transport and services stay.
    stocked = pre.get("stocked") or {}
    bill_cost = money(sum((b.total or 0) * (1.0 - stocked.get(b.id, 0.0)) for b in supplier_bills))

    # Material actually drawn from the store for this job. Issues are negative
    # and returns positive, so the negated sum is what the site consumed and a
    # cancelled issue costs nothing.
    material = money(-sum(m.value or 0 for m in pre["moves"].get(job.id, [])))

    diaries = pre["diaries"].get(job.id, [])
    labour = money(sum(d.labour_cost or 0 for d in diaries))
    plant = money(sum(d.plant_cost or 0 for d in diaries))
    mandays = money(sum(d.total_mandays or 0 for d in diaries))

    # A purchase order stops being a commitment the moment a bill references
    # it, so the same spend is never counted twice.
    billed_pos = {b.purchase_order_id for b in supplier_bills if b.purchase_order_id}
    committed = money(sum(
        p.total or 0 for p in pre["pos"].get(job.id, [])
        if p.id not in billed_pos
        and (p.status or "") in ("Approved", "Awaiting Approval")))

    # What the gangs have billed us for and we have agreed to pay. This was
    # missing entirely, which flattered every project by the whole of its
    # subcontract cost.
    subcontract = money(sum(b.this_bill or 0 for b in pre["sub"].get(job.id, [])))

    # Diesel, hire and repairs on the machines that worked this site - kept
    # in the equipment register, so the diary lists only plant that is not.
    equipment = money((pre.get("equipment") or {}).get(job.id, 0.0))

    # Material issued to a gang and taken back out of their bill: its cost is
    # inside what they billed, so it comes off here or it is counted twice.
    recovered = money((pre.get("recovered") or {}).get(job.id, 0.0))

    incurred = money(bill_cost + material + labour + plant + subcontract + equipment - recovered)
    budgeted = money(sum(pre["bom"].get(i, 0.0) for i in wo_ids)) if wo_ids else 0.0

    revenue = money(max(invoiced, certified))
    margin = money(revenue - incurred)

    return {
        "job": {"id": job.id, "number": job.number or "", "name": job.name or "",
                "customer_name": job.customer_name or "", "status": job.status or "",
                "site_address": job.site_address or ""},
        "value": {
            "order_value": order_value,
            "quoted_value": money(job.quoted_value),
            "budgeted_cost": budgeted,
        },
        "earned": {
            "invoiced": invoiced, "collected": collected,
            "outstanding": money(invoiced - collected),
            "certified": certified, "retention_held": retention,
            "revenue": revenue,
        },
        "cost": {
            "supplier_bills": bill_cost,
            "subcontractors": subcontract,
            "material_from_store": material,
            "labour": labour,
            "plant": plant,
            "equipment": equipment,
            "material_recovered_from_gangs": recovered,
            "incurred": incurred,
            "committed_not_yet_billed": committed,
            "forecast": money(incurred + committed),
        },
        "result": {
            "margin": margin,
            "margin_percent": round(margin / revenue * 100, 1) if revenue else 0.0,
            "cost_per_manday": money(incurred / mandays) if mandays else 0.0,
            "mandays": mandays,
            # Costing more than it was budgeted to is the earliest warning
            # there is, and it arrives long before the revenue does.
            "over_budget": bool(budgeted) and incurred > budgeted,
            "budget_used_percent": (round(incurred / budgeted * 100, 1)
                                    if budgeted else 0.0),
        },
    }


@app.get("/api/jobs/{job_id}/pnl")
def job_pnl(job_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    job = db.query(models.DBJob).filter(
        models.DBJob.id == job_id, models.DBJob.client_id == client.id).first()
    if not job:
        raise HTTPException(404, "Project not found")
    return project_pnl(db, client.id, job)


@app.get("/api/jobs-pnl")
def portfolio_pnl(request: Request, db: Session = Depends(get_db)):
    """Every live project on one line, worst margin first.

    An owner does not want to open eleven screens to find the one job that is
    losing money, so the one that is losing money is at the top.
    """
    client = require_erp_read(request, db)
    rows = []
    pre = preload_pnl(db, client.id)
    for job in db.query(models.DBJob).filter(
            models.DBJob.client_id == client.id).order_by(models.DBJob.id).all():
        p = project_pnl(db, client.id, job, pre=pre)
        rows.append({
            "job_id": job.id, "number": job.number or "", "name": job.name or "",
            "customer_name": job.customer_name or "", "status": job.status or "",
            "order_value": p["value"]["order_value"],
            "revenue": p["earned"]["revenue"],
            "incurred": p["cost"]["incurred"],
            "committed": p["cost"]["committed_not_yet_billed"],
            "margin": p["result"]["margin"],
            "margin_percent": p["result"]["margin_percent"],
            "mandays": p["result"]["mandays"],
            "over_budget": p["result"]["over_budget"],
            "outstanding": p["earned"]["outstanding"],
            "losing": p["result"]["margin"] < 0,
        })
    rows.sort(key=lambda r: r["margin"])
    return {
        "projects": rows,
        "summary": {
            "projects": len(rows),
            "order_value": money(sum(r["order_value"] for r in rows)),
            "revenue": money(sum(r["revenue"] for r in rows)),
            "incurred": money(sum(r["incurred"] for r in rows)),
            "margin": money(sum(r["margin"] for r in rows)),
            "losing_money": len([r for r in rows if r["losing"]]),
            "owed_to_us": money(sum(r["outstanding"] for r in rows)),
        },
    }


@app.get("/api/jobs/{job_id}/pnl.xlsx")
def job_pnl_export(job_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    job = db.query(models.DBJob).filter(
        models.DBJob.id == job_id, models.DBJob.client_id == client.id).first()
    if not job:
        raise HTTPException(404, "Project not found")
    p = project_pnl(db, client.id, job)
    e, c, r = p["earned"], p["cost"], p["result"]
    preamble = [
        ("PROJECT PROFIT AND LOSS", client.company_name or ""),
        ("Project", "%s %s" % (job.number or "", job.name or "")),
        ("Client", job.customer_name or "", "Status", job.status or ""),
        (),
    ]
    rows = [
        ("Order value", p["value"]["order_value"]),
        ("Invoiced", e["invoiced"]),
        ("Collected", e["collected"]),
        ("Certified on RA bills", e["certified"]),
        ("Retention held", e["retention_held"]),
        ("Revenue recognised", e["revenue"]),
        ("", ""),
        ("Supplier bills", c["supplier_bills"]),
        ("Material from the store", c["material_from_store"]),
        ("Labour", c["labour"]),
        ("Plant", c["plant"]),
        ("Incurred", c["incurred"]),
        ("Committed, not yet billed", c["committed_not_yet_billed"]),
        ("Forecast cost", c["forecast"]),
        ("", ""),
        ("Margin", r["margin"]),
        ("Margin %", r["margin_percent"]),
        ("Mandays", r["mandays"]),
        ("Cost per manday", r["cost_per_manday"]),
    ]
    return sheet_response(("Item", "Amount"), rows,
                          "pnl_%s.xlsx" % (job.number or "project"),
                          preamble=preamble)




# ============================================================================
# MONEY OWED, BOTH WAYS - AND THE RETENTION NOBODY CHASES
#
# The app could say what a project earned and what it cost. It could not say
# who owes what today, how long they have owed it, or how much of the money
# already earned is being held back as retention.
#
# On a contract that last one is the quiet killer: five per cent of every
# certified bill sits with the client, it is never invoiced, nobody diaries
# it, and a contractor can finish a job several lakhs down without once
# seeing the figure written anywhere.
# ============================================================================

AGEING_BUCKETS = ("Not due", "0-30", "31-60", "61-90", "90+")


def ageing_bucket(due_on, today=None):
    """Which column a debt belongs in.

    Not due is kept apart from nought to thirty on purpose: money that is not
    late yet is not a problem, and mixing the two makes a healthy ledger look
    like a chase list.
    """
    today = today or date.today()
    d = _parse_date(due_on)
    if not d:
        # No due date is not the same as not due - it cannot be chased on a
        # date, so it sits in the oldest bucket where somebody will see it.
        return "90+", None
    days = (today - d).days
    if days < 0:
        return "Not due", days
    if days <= 30:
        return "0-30", days
    if days <= 60:
        return "31-60", days
    if days <= 90:
        return "61-90", days
    return "90+", days


def _empty_buckets():
    return {b: 0.0 for b in AGEING_BUCKETS}


@app.get("/api/money/receivables")
def receivables(request: Request, db: Session = Depends(get_db)):
    """What customers owe, and how long they have owed it."""
    client = require_erp_read(request, db)
    today = date.today()
    jobs = {j.id: j for j in db.query(models.DBJob).filter(
        models.DBJob.client_id == client.id).all()}

    rows, buckets = [], _empty_buckets()
    for inv in db.query(models.DBInvoice).filter(
            models.DBInvoice.client_id == client.id).all():
        if (inv.status or "") in ("Draft", "Paid", "Cancelled", "Void"):
            continue
        outstanding = money(inv.due)
        if outstanding <= 0:
            continue
        bucket, days = ageing_bucket(inv.due_date, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(inv.job_id)
        rows.append({
            "id": inv.id, "number": inv.number or "",
            "customer": inv.to_contact or "", "project": job.name if job else "",
            "job_id": inv.job_id,
            "issue_date": inv.issue_date or "", "due_date": inv.due_date or "",
            "total": invoice_total(inv), "paid": money(inv.paid),
            "outstanding": outstanding, "bucket": bucket,
            "days_overdue": days if (days or 0) > 0 else 0,
            "status": inv.status or "",
        })
    # A client RA bill that has been certified and not paid is owed to us
    # just as an invoice is. Aged from certification. What has already been
    # received against it comes off - a part-paid bill owes what is left.
    settled = settled_amounts(db, client.id)
    for r in db.query(models.DBRABill).filter(
            models.DBRABill.client_id == client.id,
            models.DBRABill.status == "CERTIFIED").all():
        received = settled.get(("ra_bill", r.id), 0.0)
        outstanding = money((r.net_payable or 0) - received)
        if outstanding <= 0:
            continue
        # Due a month after the signature, as the dashboard already reads it -
        # a bill certified this morning was being shown as overdue by noon.
        due = days_after(r.certified_at, RA_CREDIT_DAYS)
        bucket, days = ageing_bucket(due or r.certified_at, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(r.job_id)
        rows.append({
            "id": r.id, "number": r.number or "", "kind": "RA bill",
            "customer": job.customer_name if job else "",
            "project": job.name if job else "", "job_id": r.job_id,
            "issue_date": (r.certified_at or "")[:10], "due_date": due or (r.certified_at or "")[:10],
            "total": money(r.net_payable), "paid": money(received), "outstanding": outstanding,
            "doc_type": "ra_bill",
            "bucket": bucket, "days_overdue": days if (days or 0) > 0 else 0,
            "status": r.status or "",
        })
    # Retention released and claimed is owed like any certified bill.
    for rel in db.query(models.DBRetentionRelease).filter(
            models.DBRetentionRelease.client_id == client.id,
            models.DBRetentionRelease.side == "client",
            models.DBRetentionRelease.status == "CERTIFIED").all():
        received = settled.get(("retention_release", rel.id), 0.0)
        outstanding = money((rel.net_amount or 0) - received)
        if outstanding <= 0:
            continue
        due = days_after(rel.release_on, RA_CREDIT_DAYS)
        bucket, days = ageing_bucket(due or rel.release_on, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(rel.job_id)
        rows.append({
            "id": rel.id, "number": rel.number or "", "kind": "Retention release",
            "customer": job.customer_name if job else "",
            "project": job.name if job else "", "job_id": rel.job_id,
            "issue_date": rel.release_on or "", "due_date": due or rel.release_on or "",
            "total": money(rel.net_amount), "paid": money(received), "outstanding": outstanding,
            "doc_type": "retention_release",
            "bucket": bucket, "days_overdue": days if (days or 0) > 0 else 0,
            "status": rel.status or "",
        })
    for r in rows:
        r.setdefault("kind", "Invoice")

    rows.sort(key=lambda r: -(r["days_overdue"] or 0))
    overdue = money(sum(r["outstanding"] for r in rows if r["bucket"] != "Not due"))
    return {
        "invoices": rows, "buckets": buckets,
        "summary": {
            "owed": money(sum(r["outstanding"] for r in rows)),
            "overdue": overdue,
            "invoices": len(rows),
            "worst_days": max([r["days_overdue"] for r in rows] or [0]),
            "over_90": buckets["90+"],
        },
    }


@app.get("/api/money/payables")
def payables(request: Request, db: Session = Depends(get_db)):
    """What the business owes: supplier bills, and bills it has certified.

    A certified RA bill is a promise already made - the work was measured and
    somebody signed for it - so it belongs here beside the supplier invoices
    rather than out of sight on the subcontract screen.
    """
    client = require_erp_read(request, db)
    today = date.today()
    jobs = {j.id: j for j in db.query(models.DBJob).filter(
        models.DBJob.client_id == client.id).all()}

    rows, buckets = [], _empty_buckets()
    for b in db.query(models.DBBill).filter(
            models.DBBill.client_id == client.id).all():
        if (b.status or "") in ("Paid", "Cancelled", "Rejected"):
            continue
        if (b.approval_status or "none") == "rejected":
            continue
        outstanding = money((b.total or 0) - (b.amount_paid or 0))
        if outstanding <= 0:
            continue
        bucket, days = ageing_bucket(b.due_date, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(b.job_id)
        rows.append({
            "kind": "Supplier bill", "doc_type": "supplier_bill", "id": b.id, "number": b.number or "",
            "party": b.vendor_name or "", "project": job.name if job else "",
            "due_date": b.due_date or "", "outstanding": outstanding,
            "bucket": bucket, "days_overdue": days if (days or 0) > 0 else 0,
            "status": b.status or "",
            "approved": (b.approval_status or "none") == "approved",
        })

    # A subcontractor's certified bill is money we owe the gang. Aged from
    # the day it was certified, because that is the day the promise was made.
    # (Client RA bills used to be listed here too, which was wrong - those are
    # money coming in and belong on the other page. Counting them on both
    # sides made the business look poorer than it was by exactly that sum.)
    contractors = {c.id: c for c in db.query(models.DBContractor).filter(
        models.DBContractor.client_id == client.id).all()}
    settled = settled_amounts(db, client.id)
    for r in db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client.id,
            models.DBSubBill.status == "CERTIFIED").all():
        outstanding = money((r.net_payable or 0) - settled.get(("sub_bill", r.id), 0.0))
        if outstanding <= 0:
            continue
        # The order says how many days after certification the gang is paid.
        terms = db.query(models.DBSubcontractOrder.payment_days).filter(
            models.DBSubcontractOrder.id == r.order_id).scalar() or 0
        due = days_after(r.certified_at, terms)
        bucket, days = ageing_bucket(due or r.certified_at, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(r.job_id)
        con = contractors.get(r.contractor_id)
        rows.append({
            "kind": "Subcontractor bill", "doc_type": "sub_bill", "id": r.id, "number": r.number or "",
            "party": con.company_name if con else "", "project": job.name if job else "",
            "due_date": due or (r.certified_at or "")[:10], "outstanding": outstanding,
            "bucket": bucket, "days_overdue": days if (days or 0) > 0 else 0,
            "status": r.status or "", "approved": True,
        })

    # A gang's retention, once released, is owed on their order's terms.
    for rel in db.query(models.DBRetentionRelease).filter(
            models.DBRetentionRelease.client_id == client.id,
            models.DBRetentionRelease.side == "contractor",
            models.DBRetentionRelease.status == "CERTIFIED").all():
        outstanding = money((rel.net_amount or 0) - settled.get(("retention_release", rel.id), 0.0))
        if outstanding <= 0:
            continue
        terms = db.query(models.DBSubcontractOrder.payment_days).filter(
            models.DBSubcontractOrder.id == rel.sub_order_id).scalar() or 0
        due = days_after(rel.release_on, terms)
        bucket, days = ageing_bucket(due or rel.release_on, today)
        buckets[bucket] = money(buckets[bucket] + outstanding)
        job = jobs.get(rel.job_id)
        con = contractors.get(rel.contractor_id)
        rows.append({
            "kind": "Retention release", "doc_type": "retention_release", "id": rel.id,
            "number": rel.number or "", "party": con.company_name if con else "",
            "project": job.name if job else "", "due_date": due or rel.release_on or "",
            "outstanding": outstanding, "bucket": bucket,
            "days_overdue": days if (days or 0) > 0 else 0,
            "status": rel.status or "", "approved": True,
        })

    rows.sort(key=lambda r: -(r["days_overdue"] or 0))
    return {
        "bills": rows, "buckets": buckets,
        "summary": {
            "owed": money(sum(r["outstanding"] for r in rows)),
            "overdue": money(sum(r["outstanding"] for r in rows
                                 if r["bucket"] != "Not due")),
            "bills": len(rows),
            # Sitting unapproved is different from sitting unpaid, and only
            # one of them is somebody's decision to make.
            "awaiting_approval": money(sum(r["outstanding"] for r in rows
                                           if not r["approved"])),
            "over_90": buckets["90+"],
        },
    }


@app.get("/api/money/retention")
def retention_register(request: Request, db: Session = Depends(get_db)):
    """Money already earned that is being held back.

    Held on every certified bill, invoiced on none of them. Half is normally
    released at practical completion and half at the end of the defects
    period, so a job that finished a year ago may still be owed the second
    half - and nothing in this app used to say so.
    """
    client = require_erp_read(request, db)
    jobs = {j.id: j for j in db.query(models.DBJob).filter(
        models.DBJob.client_id == client.id).all()}

    by_job = {}
    for b in db.query(models.DBRABill).filter(
            models.DBRABill.client_id == client.id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all():
        held = money(b.retention_amount)
        if held <= 0:
            continue
        job = jobs.get(b.job_id)
        row = by_job.setdefault(b.job_id or 0, {
            "job_id": b.job_id, "number": job.number if job else "",
            "project": job.name if job else "Unattached",
            "customer": job.customer_name if job else "",
            "job_status": job.status if job else "",
            "held": 0.0, "bills": [], "claimed_value": 0.0,
        })
        row["held"] = money(row["held"] + held)
        row["claimed_value"] = money(row["claimed_value"] + money(b.this_bill))
        row["bills"].append({
            "id": b.id, "number": b.number or "", "status": b.status or "",
            "this_bill": money(b.this_bill), "retention": held,
            "percent": b.retention_percent or 0,
            "certified_at": (b.certified_at or "")[:10],
        })

    # What has been released is no longer held; held is what is left.
    released = released_by_job(db, client.id)
    for r in by_job.values():
        r["retained"] = r["held"]
        r["released"] = money(released.get(r["job_id"], 0.0))
        r["held"] = money(max(0.0, r["retained"] - r["released"]))
    rows = sorted(by_job.values(), key=lambda r: -r["held"])
    for r in rows:
        # A finished job's retention is money that should be being chased;
        # a running job's is money that is simply not due yet.
        r["releasable"] = (r["job_status"] or "").lower() == JOB_FINISHED and r["held"] > 0
        r["effective_percent"] = (round(r["retained"] / r["claimed_value"] * 100, 2)
                                  if r["claimed_value"] else 0.0)
    return {
        "projects": rows,
        "summary": {
            "held": money(sum(r["held"] for r in rows)),
            "released": money(sum(r["released"] for r in rows)),
            "projects": len(rows),
            "on_finished_jobs": money(sum(r["held"] for r in rows
                                          if r["releasable"])),
            "bills": sum(len(r["bills"]) for r in rows),
        },
    }


@app.get("/api/money/receivables.xlsx")
def receivables_export(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    data = receivables(request, db)
