@app.get("/api/money/retention.xlsx")
def retention_export(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    data = retention_register(request, db)
    rows = [(r["number"], r["project"], r["customer"], r["job_status"],
             r["claimed_value"], r["retained"], r["released"], r["held"],
             r["effective_percent"], len(r["bills"]), "yes" if r["releasable"] else "")
            for r in data["projects"]]
    return sheet_response(
        ("Project", "Name", "Customer", "Status", "Claimed", "Retained", "Released",
         "Still held", "Effective %", "Bills", "Job finished"),
        rows, "retention_register.xlsx",
        preamble=[("RETENTION HELD", client.company_name or ""),
                  ("As at", date.today().strftime("%Y-%m-%d")),
                  ("Money already earned and not yet released",),
                  ()],
        closing=[(), ("Released", "", "", "", "", "", data["summary"]["released"]),
                 ("Still held", "", "", "", "", "", "", data["summary"]["held"]),
                 ("On finished jobs", "", "", "", "", "", "",
                  data["summary"]["on_finished_jobs"])])


# ============================================================================
# WHAT NEEDS LOOKING AT TODAY
#
# Every figure below already exists on some screen. The point of gathering
# them is that nobody opens eleven screens on a Monday morning, so the things
# that quietly cost money - work built and never billed, a bill sitting
# uncertified, a store that has gone negative, a site that has not filed a
# diary - were only ever found by accident.
#
# Ordered by what it costs to ignore, not by which module it came from.
# ============================================================================

def attention_items(db, client_id):
    items = []
    jobs = {j.id: j for j in db.query(models.DBJob).filter(
        models.DBJob.client_id == client_id).all()}

    # --- work built and not yet claimed ---------------------------------
    unbilled_total, unbilled_orders = 0.0, 0
    over_run_total, over_run_orders = 0.0, 0
    placed = {w.id for w in db.query(models.DBWorkOrder.id).filter(
        models.DBWorkOrder.client_id == client_id,
        models.DBWorkOrder.status != "Draft").all()}
    if placed:
        measured, billed = measured_and_billed_for_all(db, client_id)
        per_order = {}
        for l in db.query(models.DBWorkOrderLine).filter(
                models.DBWorkOrderLine.work_order_id.in_(list(placed))).all():
            rate = unit_rate(l.rate)
            done = money(measured.get(l.id, 0.0))
            acc = per_order.setdefault(l.work_order_id, [0.0, 0.0])
            acc[0] += money(done - money(billed.get(l.id, 0.0))) * rate
            if done > money(l.qty):
                acc[1] += money(done - money(l.qty)) * rate
        for unbilled, over in per_order.values():
            if unbilled > 0:
                unbilled_total += unbilled
                unbilled_orders += 1
            if over > 0:
                over_run_total += over
                over_run_orders += 1

    if unbilled_total > 0:
        items.append({
            "kind": "unbilled", "severity": "money", "value": money(unbilled_total),
            "count": unbilled_orders, "view": "measurement-view",
            "title": "Work measured but not billed",
            "detail": "%s across %d order%s. It is already paid for in wages "
                      "and material." % (inr(unbilled_total), unbilled_orders,
                                         "" if unbilled_orders == 1 else "s"),
        })
    if over_run_total > 0:
        items.append({
            "kind": "over_run", "severity": "money", "value": money(over_run_total),
            "count": over_run_orders, "view": "measurement-view",
            "title": "Built past the order",
            "detail": "%s of work nothing covers. Raise a variation and it "
                      "becomes billable." % inr(over_run_total),
        })

    # --- bills waiting on somebody --------------------------------------
    waiting = db.query(models.DBRABill).filter(
        models.DBRABill.client_id == client_id,
        models.DBRABill.status == "SUBMITTED").all()
    if waiting:
        items.append({
            "kind": "certify", "severity": "action",
            "value": money(sum(b.this_bill or 0 for b in waiting)),
            "count": len(waiting), "view": "measurement-view",
            "title": "RA bills awaiting certification",
            "detail": "%d bill%s worth %s cannot be paid until somebody signs."
                      % (len(waiting), "" if len(waiting) == 1 else "s",
                         inr(sum(b.this_bill or 0 for b in waiting))),
        })

    pending_vo = db.query(models.DBVariationOrder).filter(
        models.DBVariationOrder.client_id == client_id,
        models.DBVariationOrder.status == "SUBMITTED").all()
    if pending_vo:
        items.append({
            "kind": "variations", "severity": "action",
            "value": money(sum(v.value or 0 for v in pending_vo)),
            "count": len(pending_vo), "view": "measurement-view",
            "title": "Variations awaiting approval",
            "detail": "%s of extra work still to be agreed."
                      % inr(sum(v.value or 0 for v in pending_vo)),
        })

    # --- the store -------------------------------------------------------
    balances = stock_balances(db, client_id)
    levels = {i.item_code: (i.reorder_level or 0.0)
              for i in db.query(models.DBItem).filter(
                  models.DBItem.client_id == client_id).all()}
    negative = [a for a in balances.values() if a["on_hand"] < 0]
    low = [a for code, a in balances.items()
           if levels.get(code, 0) and 0 <= a["on_hand"] < levels[code]]
    if negative:
        items.append({
            "kind": "negative_stock", "severity": "wrong",
            "value": 0.0, "count": len(negative), "view": "stock-view",
            "title": "The store has gone negative",
            "detail": "%d item%s issued that was never booked in. Either a "
                      "delivery is unrecorded or something has walked."
                      % (len(negative), "" if len(negative) == 1 else "s"),
        })
    if low:
        items.append({
            "kind": "low_stock", "severity": "notice",
            "value": 0.0, "count": len(low), "view": "stock-view",
            "title": "Running low in the store",
            "detail": "%d item%s below the level somebody set."
                      % (len(low), "" if len(low) == 1 else "s"),
        })

    # --- the paperwork the site owes -------------------------------------
    drafts = db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.client_id == client_id,
        models.DBSiteDiary.status == "DRAFT").all()
    if drafts:
        items.append({
            "kind": "diaries", "severity": "notice", "value": 0.0,
            "count": len(drafts), "view": "diary-view",
            "title": "Site diaries not signed off",
            "detail": "%d day%s still in draft. An unsigned day is worth "
                      "nothing in a claim." % (len(drafts),
                                               "" if len(drafts) == 1 else "s"),
        })

    grn_drafts = db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.client_id == client_id,
        models.DBGoodsReceipt.status == "DRAFT").count()
    if grn_drafts:
        items.append({
            "kind": "receipts", "severity": "notice", "value": 0.0,
            "count": grn_drafts, "view": "stores-view",
            "title": "Deliveries not posted",
            "detail": "%d receipt%s open. Material is not in the store until "
                      "it is posted." % (grn_drafts,
                                         "" if grn_drafts == 1 else "s"),
        })

    # --- money -----------------------------------------------------------
    today = date.today()
    overdue_in = 0.0
    for inv in db.query(models.DBInvoice).filter(
            models.DBInvoice.client_id == client_id).all():
        if (inv.status or "") in ("Draft", "Paid", "Cancelled", "Void"):
            continue
        if money(inv.due) > 0 and ageing_bucket(inv.due_date, today)[0] != "Not due":
            overdue_in += money(inv.due)
    if overdue_in > 0:
        items.append({
            "kind": "receivables", "severity": "money", "value": money(overdue_in),
            "count": 0, "view": "money-view",
            "title": "Owed to us, past due",
            "detail": "%s the customer should already have paid." % inr(overdue_in),
        })

    held = money(sum(b.retention_amount or 0 for b in db.query(
        models.DBRABill).filter(
            models.DBRABill.client_id == client_id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all()))
    finished = {j.id for j in jobs.values()
                if (j.status or "").lower() == JOB_FINISHED}
    if held > 0 and finished:
        on_finished = money(sum(b.retention_amount or 0 for b in db.query(
            models.DBRABill).filter(
                models.DBRABill.client_id == client_id,
                models.DBRABill.job_id.in_(list(finished)),
                models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all()))
        gone = released_by_job(db, client_id)
        on_finished = money(on_finished - sum(v for k, v in gone.items() if k in finished))
        if on_finished > 0:
            items.append({
                "kind": "retention", "severity": "money", "value": on_finished,
                "count": len(finished), "view": "money-view",
                "title": "Retention on finished jobs",
                "detail": "%s earned and still held back on work that is done."
                          % inr(on_finished),
            })

    items.extend(attention_elsewhere(db, client_id, jobs, today))

    # Worth money first, then things that are simply wrong, then the rest.
    rank = {"money": 0, "wrong": 1, "action": 2, "notice": 3}
    items.sort(key=lambda i: (rank.get(i["severity"], 9), -i["value"]))
    return items


def setup_progress(db, client_id):
    """How far a new business has got through setting itself up.

    A brand new account used to open on "nothing needs chasing - everything
    measured has been billed", which is true in the way that an empty ledger
    balances. It read as reassurance when the person looking at it had no
    idea where to start. These are the steps in the order a site actually
    takes them, each one done or not, with where to go to do it.
    """
    n = lambda q: q.count()
    jobs = n(db.query(models.DBJob).filter(models.DBJob.client_id == client_id))
    items = n(db.query(models.DBItem).filter(models.DBItem.client_id == client_id))
    wos = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.client_id == client_id).all()
    placed = len([w for w in wos if (w.status or "") != "Draft"])
    measured = n(db.query(models.DBMeasurement).filter(
        models.DBMeasurement.client_id == client_id))
    billed = n(db.query(models.DBRABill).filter(
        models.DBRABill.client_id == client_id))
    received = n(db.query(models.DBGoodsReceipt).filter(
        models.DBGoodsReceipt.client_id == client_id,
        models.DBGoodsReceipt.status == "POSTED"))
    diaries = n(db.query(models.DBSiteDiary).filter(
        models.DBSiteDiary.client_id == client_id))

    tenders = n(db.query(models.DBEstimate).filter(
        models.DBEstimate.client_id == client_id))
    steps = [
        {"key": "tender", "done": tenders > 0, "view": "estimates-view",
         "title": "Price a tender",
         "hint": "Build each rate up from material, labour and plant, add the margin, and submit. Winning it makes the work order."},
        {"key": "project", "done": jobs > 0, "view": "jobs-view",
         "title": "Set up a project",
         "hint": "The site the work is on and the customer it is for. A won tender opens one for you."},
        {"key": "items", "done": items > 0, "view": "workorders-view",
         "title": "Name what you sell and what you buy",
         "hint": "Deliverables get a code when you first price one on a work order. Materials can be added from a spreadsheet under Store."},
        {"key": "order", "done": len(wos) > 0, "view": "workorders-view",
         "title": "Build a work order",
         "hint": "What was sold, line by line, with a rate against each."},
        {"key": "placed", "done": placed > 0, "view": "workorders-view",
         "title": "Place it",
         "hint": "Placing commits the prices. Until then it cannot be measured or billed."},
        {"key": "measured", "done": measured > 0, "view": "measurement-view",
         "title": "Record what has been built",
         "hint": "The measurement book. Bills are drawn from it, not typed."},
        {"key": "billed", "done": billed > 0, "view": "measurement-view",
         "title": "Draw up the first RA bill",
         "hint": "It claims whatever has been measured and not yet claimed."},
        {"key": "received", "done": received > 0, "view": "stores-view",
         "title": "Book a delivery into the store",
         "hint": "Raise a purchase order, then post the receipt when the lorry comes. Stock starts here."},
        {"key": "diary", "done": diaries > 0, "view": "diary-view",
         "title": "Keep the site diary",
         "hint": "Who turned up, what got built, what stopped it. Labour cost comes from here."},
    ]
    done = len([s for s in steps if s["done"]])
    return {"steps": steps, "done": done, "of": len(steps),
            "complete": done == len(steps),
            "next": next((s for s in steps if not s["done"]), None)}


@app.get("/api/attention")
def whats_worth_a_look(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    items = attention_items(db, client.id)
    return {
        "items": items,
        "setup": setup_progress(db, client.id),
        "summary": {
            "items": len(items),
            "money_at_stake": money(sum(i["value"] for i in items
                                        if i["severity"] == "money")),
            "needs_a_decision": len([i for i in items
                                     if i["severity"] == "action"]),
            "looks_wrong": len([i for i in items if i["severity"] == "wrong"]),
        },
    }




# ============================================================================
# THE HANDOFFS
#
# Every module in this app knew its own job and none of them handed over. The
# BOM knew a work order needed nine hundred bags of cement; nothing turned
# that into a purchase order. A posted receipt knew exactly what arrived and
# at what rate; somebody still retyped it as a supplier bill, which is where
# the figure quietly stops matching.
#
# Both of these are the same idea: the next document already exists inside
# the last one, so the app should draw it up and let a person correct it.
# ============================================================================

def material_required(db, client_id, wo):
    """What this order still needs bought, line by line.

    Needed by the BOM, less what is already in the store, less what is already
    on an open purchase order - so raising it twice is not the default
    behaviour of anybody who clicks the button twice.
    """
    needed = {}
    for b in db.query(models.DBBomLine).filter(
            models.DBBomLine.work_order_id == wo.id).all():
        row = needed.setdefault(b.rm_code, {
            "item_code": b.rm_code, "item_name": b.rm_name or "",
            "uom": b.uom or "", "needed": 0.0, "rate": unit_rate(b.rate)})
        row["needed"] = money(row["needed"] + (b.qty or 0))
        if b.rate:
            row["rate"] = unit_rate(b.rate)
    if not needed:
        return []

    balances = stock_balances(db, client_id, item_codes=set(needed))

    # Quantity sitting on purchase orders that have not been fully received.
    on_order = {}
    live = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.client_id == client_id,
        models.DBPurchaseOrder.status.in_(
            ("Draft", "Awaiting Approval", "Approved"))).all()
    if live:
        ids = [p.id for p in live]
        received = {}
        for grn in db.query(models.DBGoodsReceipt).filter(
                models.DBGoodsReceipt.client_id == client_id,
                models.DBGoodsReceipt.purchase_order_id.in_(ids),
                models.DBGoodsReceipt.status == "POSTED").all():
            for l in db.query(models.DBGoodsReceiptLine).filter(
                    models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all():
                received[l.item_code] = money(
                    received.get(l.item_code, 0.0) + (l.accepted_qty or 0))
        for l in db.query(models.DBPurchaseOrderLineItem).filter(
                models.DBPurchaseOrderLineItem.order_id.in_(ids)).all():
            code = (l.item_code or "").strip()
            if code:
                on_order[code] = money(on_order.get(code, 0.0) + (l.qty or 0))
        for code, got in received.items():
            if code in on_order:
                on_order[code] = money(max(0.0, on_order[code] - got))

    rows = []
    for code, r in sorted(needed.items()):
        in_store = money(balances.get(code, {}).get("on_hand", 0.0))
        ordered = money(on_order.get(code, 0.0))
        short = money(r["needed"] - in_store - ordered)
        # A rate the store has actually paid beats one typed into a budget
        # months ago; the budget rate is the fallback, not the truth.
        paid = unit_rate(balances.get(code, {}).get("rate", 0.0))
        rows.append({
            "item_code": code, "item_name": r["item_name"], "uom": r["uom"],
            "needed": r["needed"], "in_store": in_store, "on_order": ordered,
            "to_buy": max(0.0, short),
            "rate": paid or r["rate"], "budget_rate": r["rate"],
            "amount": money(max(0.0, short) * (paid or r["rate"])),
            "covered": short <= 0,
        })
    return rows


@app.get("/api/erp/work-orders/{wo_id}/requisition")
def material_requisition(wo_id: int, request: Request,
                         db: Session = Depends(get_db)):
    """What still has to be bought for this order. Asking does not buy it."""
    client = require_erp_read(request, db)
    wo = work_order_or_404(db, client.id, wo_id)
    rows = material_required(db, client.id, wo)
    short = [r for r in rows if not r["covered"]]
    return {
        "work_order": work_order_to_dict(db, wo),
        "lines": rows,
        "summary": {
            "items": len(rows),
            "to_buy": len(short),
            "value": money(sum(r["amount"] for r in short)),
            "already_covered": len(rows) - len(short),
        },
    }


class RaisePoIn(BaseModel):
    supplier_name: str
    supplier_email: Optional[str] = ""
    needed_by: Optional[str] = ""
    item_codes: Optional[list] = None      # omit to take everything short


@app.post("/api/erp/work-orders/{wo_id}/raise-po")
def raise_po_from_bom(wo_id: int, body: RaisePoIn, request: Request,
                      db: Session = Depends(get_db)):
    """Draw up the purchase order the budget already implies.

    It arrives as a draft, priced and quantified, for somebody to check and
    approve - the point is not to spend money automatically, it is that
    nobody should retype a schedule the app already holds.
    """
    client = require_workorder_access(request, db)
    wo = work_order_or_404(db, client.id, wo_id)
    if not (body.supplier_name or "").strip():
        raise HTTPException(400, "Who is this order with?")

    rows = [r for r in material_required(db, client.id, wo) if not r["covered"]]
    if body.item_codes:
        wanted = {str(c).strip().upper() for c in body.item_codes}
        rows = [r for r in rows if r["item_code"].upper() in wanted]
    if not rows:
        raise HTTPException(
            409, "Nothing on this order still needs buying. The budget is "
                 "covered by what is in the store and what is already on order.")

    amount = money(sum(r["amount"] for r in rows))
    order = models.DBPurchaseOrder(
        client_id=client.id, job_id=wo.job_id,
        number=allocate_po_number(db, client.id),
        supplier_name=body.supplier_name.strip(),
        supplier_email=(body.supplier_email or "").strip(),
        issue_date=datetime.now().strftime("%Y-%m-%d"),
        needed_by=(body.needed_by or ""),
        amount=amount, tax_amount=0.0, total=amount,
        status="Draft", category="material",
        reference=wo.number or "",
        notes="Raised from the budget for %s" % (wo.number or "this order"))
    db.add(order)
    db.flush()
    for r in rows:
        db.add(models.DBPurchaseOrderLineItem(
            order_id=order.id, description=r["item_name"] or r["item_code"],
            item_code=r["item_code"], uom=r["uom"],
            qty=r["to_buy"], price=r["rate"], tax_rate="18%"))
    log_audit(db, client.id, "po_raised_from_bom", "purchase_order", order.id,
              order.number or "", "%s - %d line(s) - %s"
              % (wo.number, len(rows), inr(amount)), request)
    db.commit()
    db.refresh(order)
    return {"ok": True, "order": purchase_order_to_dict(db, order),
            "message": "%s drawn up for %s - %d item%s, %s. Check it before "
                       "approving." % (order.number, body.supplier_name.strip(),
                                       len(rows), "" if len(rows) == 1 else "s",
                                       inr(amount))}


@app.post("/api/grn/{grn_id}/bill")
def bill_from_receipt(grn_id: int, request: Request, body: dict = None,
                      db: Session = Depends(get_db)):
    """The supplier bill for what actually arrived.

    Drawn from the accepted quantities, not the ordered ones, so the bill a
    supplier is paid against is the delivery the store signed for. Retyping
    it is where the three figures quietly stop matching, and the three-way
    match then reports a difference nobody caused.
    """
    client, actor_id, actor_name = grn_actor(request, db)
    grn = grn_or_404(db, client.id, grn_id)
    if (grn.status or "") != "POSTED":
        raise HTTPException(
            409, "Post the receipt first. A bill drawn from a draft is a bill "
                 "for material nobody has confirmed arrived.")

    existing = db.query(models.DBBill).filter(
        models.DBBill.client_id == client.id,
        models.DBBill.reference == (grn.number or "")).first()
    if existing and (grn.number or ""):
        raise HTTPException(
            409, "%s already has a bill (%s). Two bills against one delivery "
                 "is how a supplier gets paid twice."
                 % (grn.number, existing.number or "unnumbered"))

    lines = [l for l in db.query(models.DBGoodsReceiptLine).filter(
        models.DBGoodsReceiptLine.goods_receipt_id == grn.id).all()
        if (l.accepted_qty or 0) > 0]
    if not lines:
        raise HTTPException(
            400, "Nothing on this receipt was accepted, so there is nothing "
                 "to pay for.")

    amount = money(sum((l.accepted_qty or 0) * unit_rate(l.rate) for l in lines))
    # GST at the rate each line was ordered at. The bill used to carry none,
    # so a supplier's invoice for 2.37 lakh was booked at the 1.85 lakh of
    # goods alone: the payable, the ledger and the input credit all short.
    po_lines = db.query(models.DBPurchaseOrderLineItem).filter(
        models.DBPurchaseOrderLineItem.order_id == grn.purchase_order_id).all()
    po_rates = {pl.id: (pl.tax_rate or "0%") for pl in po_lines}
    po = db.query(models.DBPurchaseOrder).filter(
        models.DBPurchaseOrder.id == grn.purchase_order_id).first()
    # The lines' own rates, where they account for the tax the order was
    # actually agreed at. Orders saved before a rate was asked for carry a
    # label that does not; for those the order's own rate is the one used.
    by_lines = money(sum((pl.qty or 0) * (pl.price or 0) * tax_percent_of(pl.tax_rate) / 100.0
                         for pl in po_lines))
    agreed_tax = money(po.tax_amount or 0) if po else 0.0
    if po and abs(by_lines - agreed_tax) > 1.0:
        flat = round(agreed_tax / po.amount * 100.0, 2) if po.amount else 0.0
        po_rates = {k: "%g%%" % flat for k in po_rates}
    rate_of = {l.id: po_rates.get(l.po_line_id, "0%") for l in lines}
    tax = money(sum((l.accepted_qty or 0) * unit_rate(l.rate) * tax_percent_of(rate_of[l.id]) / 100.0
                    for l in lines))
    body = body or {}
    bill = models.DBBill(
        client_id=client.id, job_id=grn.job_id,
        number=next_sequence_number(db, models.DBBill, client.id, "BILL-"),
        vendor_name=grn.supplier_name or "",
        issue_date=datetime.now().strftime("%Y-%m-%d"),
        # Undated, a bill is filed as the oldest debt there is; the supplier's
        # own terms say when it is really due.
        due_date=(body.get("due_date") or days_after(
            datetime.now().strftime("%Y-%m-%d"),
            supplier_payment_days(db, client.id, grn.supplier_name))),
        amount=amount, tax_amount=tax, total=money(amount + tax),
        status="Draft", category="material",
        reference=grn.number or "",
        notes="Raised from %s%s" % (grn.number or "a receipt",
                                    " - challan %s" % grn.challan_number
                                    if grn.challan_number else ""),
        purchase_order_id=grn.purchase_order_id)
    db.add(bill)
    db.flush()
    for l in lines:
        db.add(models.DBBillLineItem(
            bill_id=bill.id, po_line_id=l.po_line_id,
            description=l.description or l.item_code or "",
            qty=money(l.accepted_qty), price=unit_rate(l.rate),
            tax_rate=rate_of[l.id] or "0%"))
    log_audit(db, client.id, "bill_from_receipt", "bill", bill.id,
              bill.number or "", "%s %s" % (grn.number, inr(amount)), request)
    db.commit()
    db.refresh(bill)
    return {"ok": True, "bill": {"id": bill.id, "number": bill.number or "",
                                 "vendor_name": bill.vendor_name or "",
                                 "total": money(bill.total),
                                 "status": bill.status or "",
                                 "reference": bill.reference or "",
                                 "purchase_order_id": bill.purchase_order_id},
            "message": "%s drawn up for %s from what actually arrived - %s "
                       "across %d line%s%s." % (bill.number, bill.vendor_name,
                                                inr(amount), len(lines),
                                                "" if len(lines) == 1 else "s",
                                                (", %s with GST" % inr(amount + tax)) if tax else "")}




# ============================================================================
# SUBCONTRACTOR MEASUREMENT AND BILLS - THE MONEY GOING OUT
#
# A work order is what the client buys from us; an RA bill against it is money
# coming in. A subcontract order is what we buy from a gang, and until now it
# could be signed but never measured or billed. The money going out to the
# people actually doing the work was not in the app, and the P&L was
# flattered by exactly that amount.
#
# Same shape as the client side on purpose. The difference is who holds the
# retention: here it is us, and TDS is what we withhold and remit.
# ============================================================================

SUB_TRANSITIONS = {
    "DRAFT":     {"SUBMIT": "SUBMITTED", "CANCEL": "CANCELLED"},
    "SUBMITTED": {"CERTIFY": "CERTIFIED", "REJECT": "DRAFT", "CANCEL": "CANCELLED"},
    "CERTIFIED": {"PAY": "PAID", "CANCEL": "CANCELLED"},
    "PAID":      {},
    "CANCELLED": {},
}


def sub_measured_to_date(db, order_id):
    totals = {}
    for m in db.query(models.DBSubMeasurement).filter(
            models.DBSubMeasurement.order_id == order_id).all():
        totals[m.item_id] = totals.get(m.item_id, 0.0) + (m.quantity or 0.0)
    return totals


def sub_billed_to_date(db, order_id, exclude_bill_id=None):
    live = db.query(models.DBSubBill).filter(
        models.DBSubBill.order_id == order_id,
        models.DBSubBill.status != "CANCELLED").all()
    ids = [b.id for b in live if b.id != exclude_bill_id]
    totals = {}
    if not ids:
        return totals
    for l in db.query(models.DBSubBillLine).filter(
            models.DBSubBillLine.sub_bill_id.in_(ids)).all():
        totals[l.item_id] = totals.get(l.item_id, 0.0) + (l.this_bill_qty or 0.0)
    return totals


def sub_bill_or_404(db, client_id, bill_id):
    row = db.query(models.DBSubBill).filter(
        models.DBSubBill.id == bill_id,
        models.DBSubBill.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Bill not found")
    return row


def recost_sub_bill(db, bill):
    """Retention off the work, GST on the remainder, TDS off the lot.

    Same order as the client side and for the same reason - it is the order
    the deductions are actually made in, and getting it wrong is real money
    on a large bill.
    """
    lines = db.query(models.DBSubBillLine).filter(
        models.DBSubBillLine.sub_bill_id == bill.id).all()
    this_bill = money(sum(l.amount or 0 for l in lines))
    bill.this_bill = this_bill
    bill.gross_to_date = money((bill.previously_billed or 0) + this_bill)
    bill.retention_amount = money(this_bill * (bill.retention_percent or 0) / 100.0)
    after = money(this_bill - bill.retention_amount -
                  (bill.advance_recovery or 0) - (bill.other_deductions or 0))
    supply = supply_state_for_job(db, bill.job_id)
    # It is the gang's supply, so it is their registration against the site
    # that decides the split - ours only when they have none on file.
    origin = contractor_state(db, bill.contractor_id) or our_state(db, bill.client_id)
    gst = split_gst(after, bill.gst_percent or 0, origin, supply)
    bill.gst_amount = gst["total"]
    bill.cgst_amount, bill.sgst_amount, bill.igst_amount = gst["cgst"], gst["sgst"], gst["igst"]
    bill.place_of_supply = supply
    bill.tds_amount = money(this_bill * (bill.tds_percent or 0) / 100.0)
    bill.labour_cess_amount = money(this_bill * (bill.labour_cess_percent or 0) / 100.0)
    bill.net_payable = money(after + bill.gst_amount - bill.tds_amount
                             - bill.labour_cess_amount)
    bill.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return bill


def sub_bill_dict(db, bill, detail=False):
    order = db.query(models.DBSubcontractOrder).filter(
        models.DBSubcontractOrder.id == bill.order_id).first()
    con = db.query(models.DBContractor).filter(
        models.DBContractor.id == bill.contractor_id).first() if bill.contractor_id else None
    job = db.query(models.DBJob).filter(models.DBJob.id == bill.job_id).first()
    row = {
        "id": bill.id, "number": bill.number or "", "sequence": bill.sequence or 1,
        "order_id": bill.order_id, "order": order.wo_number if order else "",
        "contractor": con.company_name if con else "",
        "job_id": bill.job_id,
        "project": ("%s %s" % (job.number, job.name)).strip() if job else "",
        "status": bill.status or "DRAFT",
        "period_from": bill.period_from or "", "period_to": bill.period_to or "",
        "gross_to_date": money(bill.gross_to_date),
        "previously_billed": money(bill.previously_billed),
        "this_bill": money(bill.this_bill),
        "retention_percent": bill.retention_percent or 0,
        "retention_amount": money(bill.retention_amount),
        "advance_recovery": money(bill.advance_recovery),
        "other_deductions": money(bill.other_deductions),
        "deduction_notes": bill.deduction_notes or "",
        "gst_percent": bill.gst_percent or 0, "gst_amount": money(bill.gst_amount),
        "cgst_amount": money(bill.cgst_amount), "sgst_amount": money(bill.sgst_amount),
        "igst_amount": money(bill.igst_amount), "place_of_supply": bill.place_of_supply or "",
        "tds_percent": bill.tds_percent or 0, "tds_amount": money(bill.tds_amount),
        "labour_cess_percent": bill.labour_cess_percent or 0,
        "labour_cess_amount": money(bill.labour_cess_amount),
        "net_payable": money(bill.net_payable),
        "certified_by_name": bill.certified_by_name or "",
        "certified_at": bill.certified_at or "", "paid_at": bill.paid_at or "",
        "paid_reference": bill.paid_reference or "", "remarks": bill.remarks or "",
        "editable": (bill.status or "DRAFT") == "DRAFT",
        "actions": sorted(SUB_TRANSITIONS.get(bill.status or "DRAFT", {}).keys()),
        "created_at": bill.created_at or "",
    }
    if detail:
        row["lines"] = [{
            "id": l.id, "item_id": l.item_id, "activity_no": l.activity_no or "",
            "description": (l.description or "").split("\n")[0], "uom": l.uom or "",
            "ordered_qty": money(l.ordered_qty), "measured_to_date": money(l.measured_to_date),
            "previously_billed_qty": money(l.previously_billed_qty),
            "this_bill_qty": money(l.this_bill_qty), "rate": unit_rate(l.rate),
            "amount": money(l.amount),
            "upto_date_amount": money(money(l.measured_to_date) * unit_rate(l.rate)),
        } for l in db.query(models.DBSubBillLine).filter(
            models.DBSubBillLine.sub_bill_id == bill.id).order_by(
                models.DBSubBillLine.display_order, models.DBSubBillLine.id).all()]
        row["our"] = our_party(db, bill.client_id)
        row["contractor_detail"] = ({"name": con.company_name or "", "gstin": con.gst_number or "",
                                     "pan": con.pan or "", "address": con.address or "",
                                     "contact": con.contact_person or ""} if con else {})
        row["site"] = job.site_address if job else ""
        row["place_of_supply_name"] = GST_STATES.get(bill.place_of_supply or "", "")
        row["amount_in_words"] = amount_in_words(bill.net_payable)
        row["order_detail"] = ({"number": order.wo_number, "subject": order.subject or "",
                                "value": money(order.net_order_value),
                                "retention_percent": order.retention_percent or 0,
                                "commencement_date": order.commencement_date or "",
                                "completion_date": order.completion_date or ""} if order else {})
    return row


# --- The subcontractor's measurement book -----------------------------------

class SubMeasurementIn(BaseModel):
    item_id: int
    quantity: Optional[float] = 0
    dimensions: Optional[List[DimensionIn]] = None
    measured_on: Optional[str] = ""
    mb_ref: Optional[str] = ""
    remarks: Optional[str] = ""


@app.get("/api/sub-mb/{order_id}")
def sub_measurement_book(order_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    order = wo_or_404(db, client.id, order_id)
    measured = sub_measured_to_date(db, order.id)
    billed = sub_billed_to_date(db, order.id)
    lines = []
    for it in db.query(models.DBSubcontractItem).filter(
            models.DBSubcontractItem.order_id == order.id).order_by(
                models.DBSubcontractItem.display_order, models.DBSubcontractItem.id).all():
        if it.is_header:
            lines.append({"item_id": it.id, "activity_no": it.activity_no or "",
                          "description": (it.item_description or "").split("\n")[0],
                          "is_header": True})
            continue
        done = money(measured.get(it.id, 0.0))
        claimed = money(billed.get(it.id, 0.0))
        ordered = money(it.quantity)
        lines.append({
            "item_id": it.id, "activity_no": it.activity_no or "",
            "description": (it.item_description or "").split("\n")[0],
            "uom": it.uom or "", "ordered_qty": ordered, "rate": unit_rate(it.unit_rate),
            "tolerance_percent": it.tolerance_percent or 0,
            "max_quantity": item_ceiling(it),
            "measured_to_date": done, "billed_to_date": claimed,
            "unbilled": money(done - claimed),
            "balance_to_measure": money(ordered - done),
            "percent_measured": round(done / ordered * 100, 1) if ordered else 0.0,
            "over_measured": money(done - ordered) if done > ordered else 0.0,
        })
    sub_rows = db.query(models.DBSubMeasurement).filter(
        models.DBSubMeasurement.order_id == order.id).order_by(
            models.DBSubMeasurement.id.desc()).limit(400).all()
    sub_dims = dimensions_for(db, [m.id for m in sub_rows],
                              models.DBMeasurementDimension.sub_measurement_id)
    entries = [{
        "id": m.id, "item_id": m.item_id, "activity_no": m.activity_no or "",
        "measured_on": m.measured_on or "", "quantity": money(m.quantity),
        "mb_ref": m.mb_ref or "", "remarks": m.remarks or "",
        "recorded_by_name": m.recorded_by_name or "", "billed": bool(m.sub_bill_id),
        "dimensions": sub_dims.get(m.id, []),
    } for m in sub_rows]
    return {
        "order": wo_dict(db, order), "lines": lines, "entries": entries,
        "summary": {
            "ordered_value": money(order.gross_amount),
            "measured_value": money(sum(l["measured_to_date"] * l["rate"]
                                        for l in lines if not l.get("is_header"))),
            "unbilled_value": money(sum(l["unbilled"] * l["rate"]
                                        for l in lines if not l.get("is_header"))),
            "lines_over_measured": len([l for l in lines
                                        if not l.get("is_header") and l["over_measured"] > 0]),
        },
    }


@app.post("/api/sub-mb/{order_id}/entries")
def record_sub_measurement(order_id: int, body: SubMeasurementIn, request: Request,
                           db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    order = wo_or_404(db, client.id, order_id)
    if (order.status or "") not in ("APPROVED", "EXECUTED"):
        raise HTTPException(
            409, "Nothing is measured against an order that has not been approved.")
    item = db.query(models.DBSubcontractItem).filter(
        models.DBSubcontractItem.id == body.item_id,
        models.DBSubcontractItem.order_id == order.id).first()
    if not item:
        raise HTTPException(404, "That item is not on this order")
    if item.is_header:
        raise HTTPException(400, "%s is a heading, not a measurable item."
                                 % (item.activity_no or "That line"))
    quantity = money(body.quantity or 0)
    if body.dimensions:
        quantity = money(dimension_total(body.dimensions))
    if not quantity:
        raise HTTPException(400, "A measurement of nothing is not a measurement")
    # The order plus its tolerance is the ceiling. Past it the order is amended
    # and the extra measured against the amendment - the book does not quietly
    # commit the business to more than anybody signed for. A correction
    # (a negative entry) always goes in.
    if quantity > 0:
        done = money(sub_measured_to_date(db, order.id).get(item.id, 0.0))
        ceiling = item_ceiling(item)
        if money(done + quantity) > ceiling + 0.0001:
            raise HTTPException(
                409, "%s: %s already measured; %s more would make %s against %s "
                     "ordered%s. Amend the order to measure beyond it."
                     % (item.activity_no or "Item", done, quantity,
                        money(done + quantity), money(item.quantity),
                        " (+%g%% tolerance = %s)" % (item.tolerance_percent, ceiling)
                        if item.tolerance_percent else ""))
    entry = models.DBSubMeasurement(
        client_id=client.id, order_id=order.id, item_id=item.id,
        activity_no=item.activity_no or "", quantity=quantity,
        measured_on=(body.measured_on or datetime.now().strftime("%Y-%m-%d")),
        mb_ref=(body.mb_ref or "").strip(), remarks=(body.remarks or "").strip(),
        recorded_by=actor_id, recorded_by_name=actor_name)
    db.add(entry)
    db.flush()
    write_dimensions(db, client.id, body.dimensions, sub_measurement_id=entry.id)
    log_audit(db, client.id, "sub_measurement_recorded", "subcontract_order", order.id,
              order.wo_number or "", "%s %s %s" % (item.activity_no, quantity,
                                                   item.uom or ""), request)
    db.commit()
    measured = money(sub_measured_to_date(db, order.id).get(item.id, 0.0))
    ordered = money(item.quantity)
    return {"ok": True, "measured_to_date": measured,
            "balance_to_measure": money(ordered - measured),
            "over_measured": money(measured - ordered) if measured > ordered else 0.0,
            "message": "Recorded. %s measured against %s of %s ordered."
                       % (qty_text(measured), ("activity " + item.activity_no) if item.activity_no
                          else "the item", qty_text(ordered))}


@app.delete("/api/sub-mb/entries/{entry_id}")
def delete_sub_measurement(entry_id: int, request: Request, db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    entry = db.query(models.DBSubMeasurement).filter(
        models.DBSubMeasurement.id == entry_id,
        models.DBSubMeasurement.client_id == client.id).first()
    if not entry:
        raise HTTPException(404, "Entry not found")
    if entry.sub_bill_id:
        raise HTTPException(409, "This measurement has been billed. Record a "
                                 "correcting entry instead.")
    db.query(models.DBMeasurementDimension).filter(
        models.DBMeasurementDimension.sub_measurement_id == entry.id).delete()
    db.delete(entry)
    db.commit()
    return {"ok": True, "message": "Entry removed."}


# --- The bills ---------------------------------------------------------------

class SubBillIn(BaseModel):
    order_id: int
    period_from: Optional[str] = ""
    period_to: Optional[str] = ""
    advance_recovery: Optional[float] = None
    other_deductions: Optional[float] = None
    deduction_notes: Optional[str] = ""


def sub_claimable_lines(db, order, exclude_bill_id=None):
    measured = sub_measured_to_date(db, order.id)
    billed = sub_billed_to_date(db, order.id, exclude_bill_id)
    out = []
    for it in db.query(models.DBSubcontractItem).filter(
            models.DBSubcontractItem.order_id == order.id).order_by(
                models.DBSubcontractItem.display_order, models.DBSubcontractItem.id).all():
        if it.is_header:
            continue
        done = money(measured.get(it.id, 0.0))
        prior = money(billed.get(it.id, 0.0))
        this = money(done - prior)
        if this <= 0:
            continue
        out.append((it, done, prior, this))
    return out


def draw_sub_bill_lines(db, bill, order):
    db.query(models.DBSubBillLine).filter(
        models.DBSubBillLine.sub_bill_id == bill.id).delete()
    for i, (it, done, prior, this) in enumerate(
            sub_claimable_lines(db, order, exclude_bill_id=bill.id)):
        rate = unit_rate(it.unit_rate)
        db.add(models.DBSubBillLine(
            sub_bill_id=bill.id, item_id=it.id, activity_no=it.activity_no or "",
            description=it.item_description or "", uom=it.uom or "",
            ordered_qty=money(it.quantity), measured_to_date=done,
            previously_billed_qty=prior, this_bill_qty=this, rate=rate,
            amount=money(this * rate), display_order=i))
    # Pin the measurements this bill claims.
    db.query(models.DBSubMeasurement).filter(
        models.DBSubMeasurement.order_id == order.id,
        models.DBSubMeasurement.sub_bill_id.is_(None)).update(
            {"sub_bill_id": bill.id}, synchronize_session=False)
    db.flush()


@app.get("/api/sub-bills")
def list_sub_bills(request: Request, order_id: int = 0, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBSubBill).filter(models.DBSubBill.client_id == client.id)
    if order_id:
        q = q.filter(models.DBSubBill.order_id == order_id)
    rows = [sub_bill_dict(db, b) for b in q.order_by(models.DBSubBill.id.desc()).limit(300).all()]
    live = [r for r in rows if r["status"] != "CANCELLED"]
    return {
        "bills": rows,
        "summary": {
            "claimed": money(sum(r["this_bill"] for r in live)),
            "awaiting_certification": len([r for r in rows if r["status"] == "SUBMITTED"]),
            "certified_unpaid": money(sum(r["net_payable"] for r in rows
                                          if r["status"] == "CERTIFIED")),
            "retention_held": money(sum(r["retention_amount"] for r in rows
                                        if r["status"] in ("CERTIFIED", "PAID"))
                                    - contractor_released(db, client.id, order_id)),
            "paid": money(sum(r["net_payable"] for r in rows if r["status"] == "PAID")),
        },
    }


@app.post("/api/sub-bills")
def create_sub_bill(body: SubBillIn, request: Request, db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    order = wo_or_404(db, client.id, body.order_id)
    if (order.status or "") not in ("APPROVED", "EXECUTED"):
        raise HTTPException(409, "Approve the order before billing against it.")
    open_bill = db.query(models.DBSubBill).filter(
        models.DBSubBill.order_id == order.id,
        models.DBSubBill.status.in_(("DRAFT", "SUBMITTED"))).first()
    if open_bill:
        raise HTTPException(
            409, "%s is still open on this order. Finish or cancel it before "
                 "raising another." % open_bill.number)
    if not sub_claimable_lines(db, order):
        raise HTTPException(
            409, "Nothing has been measured since the last bill. Record the work "
                 "in the measurement book first.")

    seq = db.query(models.DBSubBill).filter(models.DBSubBill.order_id == order.id).count() + 1
    prior = money(sum(b.this_bill or 0 for b in db.query(models.DBSubBill).filter(
        models.DBSubBill.order_id == order.id,
        models.DBSubBill.status != "CANCELLED").all()))
    bill = models.DBSubBill(
        client_id=client.id, order_id=order.id, job_id=order.job_id,
        contractor_id=order.contractor_id,
        number="%s/RA-%02d" % (order.wo_number or "SC", seq), sequence=seq,
        period_from=(body.period_from or ""), period_to=(body.period_to or
                                                          datetime.now().strftime("%Y-%m-%d")),
        status="DRAFT", previously_billed=prior,
        retention_percent=order.retention_percent or 0,
        advance_recovery=0.0,
        other_deductions=money(body.other_deductions or 0),
        deduction_notes=(body.deduction_notes or "").strip(),
        gst_percent=order.gst_rate or 0, tds_percent=order.tds_rate or 0,
        labour_cess_percent=order.labour_cess_percent or 0)
    db.add(bill)
    db.flush()
    draw_sub_bill_lines(db, bill, order)
    recost_sub_bill(db, bill)
    bill.advance_recovery = sub_advance_recovery(db, order, bill, body.advance_recovery)
    recost_sub_bill(db, bill)
    if apply_material_recovery(db, client.id, order, bill):
        recost_sub_bill(db, bill)
    log_audit(db, client.id, "sub_bill_raised", "subcontract_order", order.id,
              order.wo_number or "", "%s %s" % (bill.number, inr(bill.this_bill)), request)
    db.commit()
    db.refresh(bill)
    return {"ok": True, "bill": sub_bill_dict(db, bill, detail=True),
            "message": "%s drawn up from the measurement book - %s of work."
                       % (bill.number, inr(bill.this_bill))}


def sub_advance_recovery(db, order, bill, asked=None):
    """How much of the mobilisation advance this bill takes back.

    The instalment is the agreed share of the advance - unless the person
    raising the bill says otherwise - but never more than is still owed, and
    never more than the bill can bear after retention. A first bill for a
    small month's work does not come out negative; the shortfall waits for
    the next one.
    """
    # What was actually handed over, not what the order allows. Recovering
    # the agreed figure took an advance back out of a gang's bill that had
    # never been paid to them.
    advance = min(money(order.mobilization_advance_amount or 0),
                  advance_paid(db, order.client_id, order.id))
    if not advance:
        return 0.0
    recovered = money(sum((b.advance_recovery or 0) for b in db.query(models.DBSubBill).filter(
        models.DBSubBill.order_id == order.id, models.DBSubBill.id != bill.id,
        models.DBSubBill.status != "CANCELLED").all()))
    balance = max(0.0, money(advance - recovered))
    instalment = (money(asked) if asked is not None
                  else money(advance * (order.advance_recovery_percent or 0) / 100.0))
    # What the bill can bear: after retention and the other deductions, less
    # what TDS and cess will take off the whole bill regardless - grossed
    # down by the GST that is added on the remainder - so the net is never
    # below nought.
    withheld = ((bill.this_bill or 0) * ((bill.tds_percent or 0) + (bill.labour_cess_percent or 0))
                / 100.0)
    bearable = ((bill.this_bill or 0) - (bill.retention_amount or 0)
                - (bill.other_deductions or 0)
                - withheld / (1.0 + (bill.gst_percent or 0) / 100.0))
    bearable = max(0.0, money(bearable - 0.005))
    return money(max(0.0, min(instalment, balance, bearable)))


@app.get("/api/sub-bills/{bill_id}")
def get_sub_bill(bill_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return sub_bill_dict(db, sub_bill_or_404(db, client.id, bill_id), detail=True)


@app.post("/api/sub-bills/{bill_id}/{action}")
def act_on_sub_bill(bill_id: int, action: str, request: Request, body: dict = None,
                    db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    bill = sub_bill_or_404(db, client.id, bill_id)
    move = (action or "").upper()
    allowed = SUB_TRANSITIONS.get(bill.status or "DRAFT", {})
    if move not in allowed:
        raise HTTPException(409, "A %s bill cannot be %sed."
                                 % ((bill.status or "draft").lower(), move.lower()))
    body = body or {}
    comments = (body.get("comments") or "").strip()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    order = wo_or_404(db, client.id, bill.order_id)

    if move == "SUBMIT":
        # Redrawn from the book on the way out, so anything measured since
        # the draft was opened is on it.
        draw_sub_bill_lines(db, bill, order)
        recost_sub_bill(db, bill)
        if not bill.this_bill:
            raise HTTPException(409, "There is nothing on this bill to submit.")
    elif move == "CERTIFY":
        # Certifying a subcontractor's bill is agreeing to pay it.
        require_items_access(request, db, "subcontracts.approve")
        bill.certified_by, bill.certified_by_name, bill.certified_at = actor_id, actor_name, now
    elif move == "REJECT":
        if not comments:
            raise HTTPException(400, "Say why it is going back.")
        bill.remarks = comments
        db.query(models.DBSubMeasurement).filter(
            models.DBSubMeasurement.sub_bill_id == bill.id).update(
                {"sub_bill_id": None}, synchronize_session=False)
    elif move == "PAY":
        bill.paid_at = now
        bill.paid_reference = (body.get("reference") or "").strip()
    elif move == "CANCEL":
        if not comments:
            raise HTTPException(400, "Say why it is being cancelled.")
        refuse_cancel_with_money(db, client.id, "sub_bill", bill, "paid")
        bill.remarks = comments
        db.query(models.DBSubMeasurement).filter(
            models.DBSubMeasurement.sub_bill_id == bill.id).update(
                {"sub_bill_id": None}, synchronize_session=False)
        # Material it recovered goes back to waiting for the next bill.
        release_material_recovery(db, client.id, bill.id)

    was, bill.status = bill.status, allowed[move]
    bill.updated_at = now
    log_audit(db, client.id, "sub_bill_%s" % move.lower(), "sub_bill", bill.id,
              bill.number or "", "%s -> %s %s" % (was, bill.status, comments), request)
    db.commit()
    db.refresh(bill)
    if move in ("SUBMIT", "CERTIFY"):
        con = db.query(models.DBContractor).filter(models.DBContractor.id == bill.contractor_id).first() \
            if bill.contractor_id else None
        gang = (con.company_name if con else "") or "the gang"
        if move == "SUBMIT":
            notify(db, client.id, "sub_bill_submitted", "%s from %s is waiting to be certified" % (bill.number, gang),
                   "%s of work billed." % inr(bill.this_bill), view="subbills-view",
                   ref_type="sub_bill", ref_id=bill.id, severity="action")
        else:
            notify(db, client.id, "sub_bill_certified", "%s certified - %s to pay %s" % (
                bill.number, inr(bill.net_payable), gang), "Pay it from Subcontractor Bills.",
                   view="subbills-view", ref_type="sub_bill", ref_id=bill.id, severity="money")
        db.refresh(bill)
    return {"ok": True, "bill": sub_bill_dict(db, bill, detail=True),
            "message": "%s %s." % (bill.number, bill.status.lower())}


@app.get("/api/sub-bills/{bill_id}/export.xlsx")
def export_sub_bill(bill_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    b = sub_bill_dict(db, sub_bill_or_404(db, client.id, bill_id), detail=True)
    preamble = [("Subcontractor RA Bill", client.company_name or ""),
                ("No: %s   (%s)" % (b["number"], b["status"])),
                ("Subcontractor: %s" % b["contractor"]),
                ("Order: %s" % b["order"]), ("Project: %s" % b["project"]),
                ("Period to: %s" % b["period_to"]), ()]
    headers = ("Activity", "Description", "UOM", "Ordered", "Measured to date",
               "Previously billed", "This bill", "Rate", "Amount")
    rows = [(l["activity_no"], l["description"], l["uom"], l["ordered_qty"],
             l["measured_to_date"], l["previously_billed_qty"], l["this_bill_qty"],
             l["rate"], l["amount"]) for l in b["lines"]]
    closing = [(), ("This bill", b["this_bill"]),
               ("Retention held @ %s%%" % b["retention_percent"], -b["retention_amount"]),
               ("Advance recovery", -b["advance_recovery"]),
               ("Other deductions", -b["other_deductions"]),
               ("GST @ %s%%" % b["gst_percent"], b["gst_amount"]),
               ("TDS @ %s%%" % b["tds_percent"], -b["tds_amount"]),
               ("Net payable", b["net_payable"])]
    return sheet_response(headers, rows,
                          "sub_bill_%s.xlsx" % b["number"].replace("/", "-"),
                          preamble=preamble, closing=closing)




# ============================================================================
# ESTIMATION - THE FRONT OF THE CHAIN
#
# The chain used to start at a signed work order. Half of a contracting
# business happens before that: a tender arrives, somebody builds a rate for
# every item from material, labour, plant and overhead, adds a margin and
# submits a price. Win it and that priced schedule IS the work order - so
# winning creates one, line for line, with nothing retyped.
# ============================================================================

EST_TRANSITIONS = {
    "DRAFT":     {"SUBMIT": "SUBMITTED", "WITHDRAW": "WITHDRAWN"},
    "SUBMITTED": {"WIN": "WON", "LOSE": "LOST", "WITHDRAW": "WITHDRAWN", "REOPEN": "DRAFT"},
    "WON":       {},
    "LOST":      {"REOPEN": "DRAFT"},
    "WITHDRAWN": {"REOPEN": "DRAFT"},
}
RATE_KINDS = ("MATERIAL", "LABOUR", "PLANT", "OTHER")


def estimate_or_404(db, client_id, est_id):
    row = db.query(models.DBEstimate).filter(
        models.DBEstimate.id == est_id,
        models.DBEstimate.client_id == client_id).first()
    if not row:
        raise HTTPException(404, "Estimate not found")
    return row


def recost_estimate_item(db, item, est):
    """Cost from the analysis if there is one, then margin on top.

    Overhead is applied to cost and profit to the result, in that order,
    because overhead is a cost the business carries and profit is what is
    left after every cost - pricing them the other way round quietly
    understates the margin.
    """
    lines = db.query(models.DBRateAnalysis).filter(
        models.DBRateAnalysis.estimate_item_id == item.id).all()
    if lines:
        total = 0.0
        for l in lines:
            base = (l.quantity_per_unit or 0) * (l.rate or 0)
            l.amount_per_unit = money(base * (1 + (l.wastage_percent or 0) / 100.0))
            total += l.amount_per_unit
        item.cost_rate = unit_rate(total)
    oh = item.overhead_percent if item.overhead_percent is not None else (est.overhead_percent or 0)
    pf = item.profit_percent if item.profit_percent is not None else (est.profit_percent or 0)
    with_oh = (item.cost_rate or 0) * (1 + oh / 100.0)
    item.quoted_rate = unit_rate(with_oh * (1 + pf / 100.0))
    item.cost_amount = money((item.quantity or 0) * (item.cost_rate or 0))
    item.quoted_amount = money((item.quantity or 0) * item.quoted_rate)
    return item


def recost_estimate(db, est):
    items = db.query(models.DBEstimateItem).filter(
        models.DBEstimateItem.estimate_id == est.id).all()
    for it in items:
        recost_estimate_item(db, it, est)
    est.cost_total = money(sum(i.cost_amount or 0 for i in items))
    est.quoted_total = money(sum(i.quoted_amount or 0 for i in items))
    est.margin_amount = money(est.quoted_total - est.cost_total)
    est.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return est


def estimate_dict(db, est, detail=False):
    job = db.query(models.DBJob).filter(models.DBJob.id == est.job_id).first()
    wo = db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.id == est.work_order_id).first() if est.work_order_id else None
    row = {
        "id": est.id, "number": est.number or "", "title": est.title or "",
        "customer_name": est.customer_name or "",
        "tender_reference": est.tender_reference or "", "due_on": est.due_on or "",
        "job_id": est.job_id, "project": job.name if job else "",
        "status": est.status or "DRAFT",
        "overhead_percent": est.overhead_percent or 0,
        "profit_percent": est.profit_percent or 0,
        "cost_total": money(est.cost_total), "quoted_total": money(est.quoted_total),
        "margin_amount": money(est.margin_amount),
        "margin_percent": (round(est.margin_amount / est.quoted_total * 100, 1)
                           if est.quoted_total else 0.0),
        "work_order_id": est.work_order_id, "work_order": wo.number if wo else "",
        "decided_at": est.decided_at or "", "lost_reason": est.lost_reason or "",
        "notes": est.notes or "", "prepared_by_name": est.prepared_by_name or "",
        "editable": (est.status or "DRAFT") == "DRAFT",
        "actions": sorted(EST_TRANSITIONS.get(est.status or "DRAFT", {}).keys()),
        "item_count": db.query(models.DBEstimateItem).filter(
            models.DBEstimateItem.estimate_id == est.id).count(),
        "created_at": est.created_at or "",
    }
    if detail:
        row["items"] = []
        for it in db.query(models.DBEstimateItem).filter(
                models.DBEstimateItem.estimate_id == est.id).order_by(
                    models.DBEstimateItem.display_order, models.DBEstimateItem.id).all():
            row["items"].append({
                "id": it.id, "item_no": it.item_no or "", "fg_code": it.fg_code or "",
                "description": it.description or "", "uom": it.uom or "",
                "quantity": money(it.quantity), "cost_rate": unit_rate(it.cost_rate),
                "overhead_percent": it.overhead_percent,
                "profit_percent": it.profit_percent,
                "quoted_rate": unit_rate(it.quoted_rate),
                "cost_amount": money(it.cost_amount), "quoted_amount": money(it.quoted_amount),
                "analysis": [{
                    "id": a.id, "kind": a.kind or "MATERIAL", "item_code": a.item_code or "",
                    "description": a.description or "", "uom": a.uom or "",
                    "quantity_per_unit": a.quantity_per_unit or 0, "rate": unit_rate(a.rate),
                    "wastage_percent": a.wastage_percent or 0,
                    "amount_per_unit": unit_rate(a.amount_per_unit),
                } for a in db.query(models.DBRateAnalysis).filter(
                    models.DBRateAnalysis.estimate_item_id == it.id).order_by(
                        models.DBRateAnalysis.display_order, models.DBRateAnalysis.id).all()],
            })
    return row


class EstimateIn(BaseModel):
    title: str
    customer_name: Optional[str] = ""
    tender_reference: Optional[str] = ""
    due_on: Optional[str] = ""
    job_id: Optional[int] = None
    overhead_percent: Optional[float] = None
    profit_percent: Optional[float] = None
    notes: Optional[str] = ""


class EstimateItemIn(BaseModel):
    item_no: Optional[str] = ""
    fg_code: Optional[str] = ""
    description: str
    uom: Optional[str] = ""
    quantity: float = 0.0
    cost_rate: Optional[float] = None
    overhead_percent: Optional[float] = None
    profit_percent: Optional[float] = None


class RateLineIn(BaseModel):
    kind: str = "MATERIAL"
    item_code: Optional[str] = ""
    description: str
    uom: Optional[str] = ""
    quantity_per_unit: float = 0.0
    rate: float = 0.0
    wastage_percent: Optional[float] = 0.0


@app.get("/api/estimates")
def list_estimates(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    rows = [estimate_dict(db, e) for e in db.query(models.DBEstimate).filter(
        models.DBEstimate.client_id == client.id).order_by(
            models.DBEstimate.id.desc()).limit(300).all()]
    decided = [r for r in rows if r["status"] in ("WON", "LOST")]
    won = [r for r in rows if r["status"] == "WON"]
    return {
        "estimates": rows,
        "summary": {
            "open": len([r for r in rows if r["status"] in ("DRAFT", "SUBMITTED")]),
            "out_for_decision": money(sum(r["quoted_total"] for r in rows
                                          if r["status"] == "SUBMITTED")),
            "won_value": money(sum(r["quoted_total"] for r in won)),
            # Strike rate by count, which is what an estimator is judged on.
            "strike_rate": (round(len(won) / len(decided) * 100, 1) if decided else 0.0),
        },
    }


