def grade_fck(grade):
    m = re.search(r"(\d{2,3})", grade or "")
    return float(m.group(1)) if m else 25.0


def next_number(db, model, client_id, stem):
    n = db.query(model).filter(model.client_id == client_id).count() + 1
    return "%s-%04d" % (stem, n)


