class CubeResultIn(BaseModel):
    age_days: int
    strengths: str                  # "31.2, 29.8, 30.5"
    tested_on: Optional[str] = ""
    lab: Optional[str] = ""


@app.post("/api/qc/cubes/{sid}/results")
def add_cube_result(sid: int, body: CubeResultIn, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    s = db.query(models.DBCubeSet).filter(models.DBCubeSet.id == sid,
                                          models.DBCubeSet.client_id == client.id).first()
    if not s:
        raise HTTPException(404, "Cube set not found")
    vals = [float(x) for x in re.findall(r"\d+(?:\.\d+)?", body.strengths or "")]
    if not vals or any(v <= 0 or v > 150 for v in vals):
        raise HTTPException(400, "The crushing strengths in N/mm2, one per cube: 31.2, 29.8, 30.5")
    if not 1 <= body.age_days <= 90:
        raise HTTPException(400, "Age in days - 7 or 28 as a rule.")
    if db.query(models.DBCubeResult).filter(models.DBCubeResult.set_id == s.id,
                                            models.DBCubeResult.age_days == body.age_days).first():
        raise HTTPException(409, "%s already has its %d-day result." % (s.number, body.age_days))
    db.add(models.DBCubeResult(set_id=s.id, age_days=body.age_days,
                               tested_on=(body.tested_on or date.today().isoformat())[:10],
                               strengths=", ".join("%g" % v for v in vals),
                               average=round(sum(vals) / len(vals), 2), lab=(body.lab or "").strip(),
                               recorded_by_name=actor_name))
    db.commit()
    d = cube_dict(db, s)
    got = [r for r in d["results"] if r["age_days"] == body.age_days][0]
    if not got["ok"]:
        notify(db, client.id, "qc_failed", "%s %s at %d days: %s N/mm2" % (s.number, s.grade, body.age_days, got["average"]),
               "%s, cast %s. %s." % (s.location or "", s.cast_on, got["verdict"].capitalize()),
               view="quality-view", ref_type="cube_set", ref_id=s.id, severity="wrong")
    return {"cube_set": d}


# --- Non-conformances -------------------------------------------------------

def ncr_dict(n):
    today = date.today().isoformat()
    return {"id": n.id, "job_id": n.job_id, "number": n.number, "raised_on": n.raised_on or "",
            "raised_by": n.raised_by or "", "location": n.location or "", "description": n.description or "",
            "severity": n.severity or "Minor", "responsible": n.responsible or "",
            "corrective_action": n.corrective_action or "", "target_date": n.target_date or "",
            "source_type": n.source_type or "", "source_id": n.source_id, "status": n.status,
            "closed_on": n.closed_on or "", "closure_note": n.closure_note or "", "closed_by": n.closed_by or "",
            "overdue": n.status == "OPEN" and bool(n.target_date) and n.target_date < today}


class NcrIn(BaseModel):
    job_id: Optional[int] = None
    location: Optional[str] = ""
    description: Optional[str] = ""
    severity: Optional[str] = "Minor"
    responsible: Optional[str] = ""
    corrective_action: Optional[str] = ""
    target_date: Optional[str] = ""
    source_type: Optional[str] = ""
    source_id: Optional[int] = None


@app.get("/api/qc/ncrs")
def list_ncrs(request: Request, job_id: int = 0, status: str = "", db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    q = db.query(models.DBNcr).filter(models.DBNcr.client_id == client.id)
    if job_id:
        q = q.filter(models.DBNcr.job_id == job_id)
    if status:
        q = q.filter(models.DBNcr.status == status.upper())
    rows = [ncr_dict(n) for n in q.order_by(models.DBNcr.id.desc()).all()]
    return {"ncrs": rows, "summary": {"open": len([r for r in rows if r["status"] == "OPEN"]),
                                      "overdue": len([r for r in rows if r["overdue"]]),
                                      "major_open": len([r for r in rows if r["status"] == "OPEN"
                                                         and r["severity"] == "Major"])}}


@app.post("/api/qc/ncrs")
def raise_ncr(body: NcrIn, request: Request, db: Session = Depends(get_db)):
    """By hand, or from a failed inspection or a set of cubes below grade -
    which fills in what went wrong from the record."""
    client, _, actor_name = wo_actor(request, db)
    job_id, location, desc = body.job_id, (body.location or "").strip(), (body.description or "").strip()
    if body.source_type == "inspection" and body.source_id:
        i = _inspection_or_404(db, client.id, body.source_id)
        d = inspection_dict(i)
        job_id = i.job_id
        location = location or i.location
        desc = desc or "%s (%s) failed: %s" % (i.number, i.checklist, "; ".join(
            x["item"] + (" - " + x["remark"] if x["remark"] else "") for x in d["items"] if x["result"] == "not ok"))
    elif body.source_type == "cube_set" and body.source_id:
        s = db.query(models.DBCubeSet).filter(models.DBCubeSet.id == body.source_id,
                                              models.DBCubeSet.client_id == client.id).first()
        if not s:
            raise HTTPException(404, "Cube set not found")
        d = cube_dict(db, s)
        job_id = s.job_id
        location = location or s.location
        low = [r for r in d["results"] if not r["ok"]]
        desc = desc or "%s %s cast %s: %s" % (s.number, s.grade, s.cast_on, "; ".join(
            "%d-day average %s N/mm2 (%s)" % (r["age_days"], r["average"], r["verdict"]) for r in low))
    if not job_id:
        raise HTTPException(400, "Which project is it on?")
    job = _qc_job(db, client.id, job_id)
    if not desc:
        raise HTTPException(400, "Say what is not as specified.")
    n = models.DBNcr(client_id=client.id, job_id=job.id, number=next_number(db, models.DBNcr, client.id, "NCR"),
                     raised_on=date.today().isoformat(), raised_by=actor_name, location=location[:200],
                     description=desc[:3000], severity="Major" if body.severity == "Major" else "Minor",
                     responsible=(body.responsible or "").strip(), corrective_action=(body.corrective_action or "").strip(),
                     target_date=(body.target_date or "")[:10], source_type=body.source_type or "manual",
                     source_id=body.source_id)
    db.add(n)
    db.commit()
    notify(db, client.id, "qc_failed", "%s raised - %s" % (n.number, n.location or job.name),
           n.description[:300], view="quality-view", ref_type="ncr", ref_id=n.id,
           severity="wrong" if n.severity == "Major" else "action")
    return {"ncr": ncr_dict(n)}


class NcrCloseIn(BaseModel):
    closure_note: str


@app.post("/api/qc/ncrs/{nid}/close")
def close_ncr(nid: int, body: NcrCloseIn, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    n = db.query(models.DBNcr).filter(models.DBNcr.id == nid, models.DBNcr.client_id == client.id).first()
    if not n:
        raise HTTPException(404, "NCR not found")
    if n.status == "CLOSED":
        raise HTTPException(409, "%s is already closed." % n.number)
    if not (body.closure_note or "").strip():
        raise HTTPException(400, "Say what was done to put it right.")
    n.status, n.closed_on, n.closed_by = "CLOSED", date.today().isoformat(), actor_name
    n.closure_note = body.closure_note.strip()
    db.commit()
    return {"ncr": ncr_dict(n)}


# ============================================================================
# SAFETY: INCIDENTS, TOOLBOX TALKS AND PERMITS TO WORK
#
# A near miss written down is the cheapest lesson a site will ever get; the
# same one not written down is the next accident. Every incident is logged
# with what was done and why it happened, the morning toolbox talk with who
# stood through it, and dangerous work - hot work, heights, confined spaces -
# only on a permit that says until when, on which precautions, and is closed
# when the work stops.
# ============================================================================

INCIDENT_KINDS = ("Near miss", "First aid", "Medical treatment", "Lost time injury",
                  "Property damage", "Dangerous occurrence", "Fatality")
SERIOUS_KINDS = ("Lost time injury", "Dangerous occurrence", "Fatality")
PERMIT_PRECAUTIONS = {
    "Work at height": ["Full body harness, anchored", "Scaffold tagged and inspected", "Guard rails and toe boards",
                       "Safety net or fall arrest below", "Area below barricaded", "Ladders tied and footed"],
    "Hot work": ["Combustibles cleared 11 m around", "Fire extinguisher at hand", "Fire watch posted, stays 30 min after",
                 "Gas cylinders upright, flashback arrestors fitted", "Welding screens in place"],
    "Confined space": ["Atmosphere tested - oxygen, gas", "Forced ventilation running", "Standby person at the entry",
                       "Rescue tripod and harness ready", "Entry and exit logged"],
    "Excavation": ["Underground services located and marked", "Shoring or benching per depth", "Spoil kept 1 m back from the edge",
                   "Edge barricaded and lit", "Ladder within reach every 30 m", "Dewatering arranged"],
    "Electrical isolation": ["Isolated at source", "Locked and tagged out", "Tested dead before touching",
                             "Earthed", "Authorised electrician only"],
    "Lifting": ["Crane certificate and operator licence checked", "Load within the chart", "Slings and shackles inspected",
                "Tag lines on the load", "Area cleared under the lift", "Signaller appointed"],
}


def incident_dict(i):
    return {"id": i.id, "job_id": i.job_id, "number": i.number, "happened_on": i.happened_on or "",
            "happened_at": i.happened_at or "", "kind": i.kind, "location": i.location or "",
            "description": i.description or "", "injured_name": i.injured_name or "", "injury": i.injury or "",
            "treatment": i.treatment or "", "lost_days": i.lost_days or 0,
            "immediate_action": i.immediate_action or "", "root_cause": i.root_cause or "",
            "corrective_action": i.corrective_action or "", "reported_by": i.reported_by or "",
            "status": i.status, "closed_on": i.closed_on or "", "closure_note": i.closure_note or "",
            "serious": i.kind in SERIOUS_KINDS}


def permit_dict(p):
    try:
        pre = json.loads(p.precautions or "[]")
    except ValueError:
        pre = []
    now = datetime.now().strftime("%Y-%m-%d %H:%M")
    return {"id": p.id, "job_id": p.job_id, "number": p.number, "kind": p.kind, "location": p.location or "",
            "description": p.description or "", "valid_from": p.valid_from or "", "valid_to": p.valid_to or "",
            "issued_by": p.issued_by or "", "receiver": p.receiver or "", "precautions": pre,
            "status": p.status, "closed_at": p.closed_at or "", "closed_by": p.closed_by or "",
            "closure_note": p.closure_note or "",
            "expired": p.status == "ACTIVE" and bool(p.valid_to) and p.valid_to < now}


class IncidentIn(BaseModel):
    job_id: int
    kind: str
    description: str
    happened_on: Optional[str] = ""
    happened_at: Optional[str] = ""
    location: Optional[str] = ""
    injured_name: Optional[str] = ""
    injury: Optional[str] = ""
    treatment: Optional[str] = ""
    lost_days: Optional[float] = 0
    immediate_action: Optional[str] = ""
    root_cause: Optional[str] = ""
    corrective_action: Optional[str] = ""


@app.get("/api/safety")
def safety_overview(request: Request, job_id: int = 0, db: Session = Depends(get_db)):
    """Everything on the safety screen for one project, or every project."""
    client = require_erp_read(request, db)

    def scoped(model):
        q = db.query(model).filter(model.client_id == client.id)
        return q.filter(model.job_id == job_id) if job_id else q
    incidents = [incident_dict(i) for i in scoped(models.DBSafetyIncident).order_by(models.DBSafetyIncident.id.desc()).all()]
    talks = scoped(models.DBToolboxTalk).order_by(models.DBToolboxTalk.held_on.desc(), models.DBToolboxTalk.id.desc()).all()
    permits = [permit_dict(p) for p in scoped(models.DBWorkPermit).order_by(models.DBWorkPermit.id.desc()).all()]
    today = date.today()
    ltis = sorted([i["happened_on"] for i in incidents if i["kind"] in ("Lost time injury", "Fatality") and i["happened_on"]])
    try:
        since = (today - datetime.strptime(ltis[-1], "%Y-%m-%d").date()).days if ltis else None
    except ValueError:
        since = None
    month = today.strftime("%Y-%m")
    week_ago = (today - timedelta(days=7)).isoformat()
    return {"incidents": incidents,
            "talks": [{"id": t.id, "job_id": t.job_id, "held_on": t.held_on, "topic": t.topic,
                       "conducted_by": t.conducted_by or "", "attendees": t.attendees or 0,
                       "attendee_names": t.attendee_names or "", "minutes": t.minutes or 0,
                       "notes": t.notes or ""} for t in talks],
            "permits": permits, "kinds": list(INCIDENT_KINDS), "permit_kinds": PERMIT_PRECAUTIONS,
            "summary": {"days_without_lti": since,
                        "incidents_this_month": len([i for i in incidents if (i["happened_on"] or "")[:7] == month]),
                        "near_misses": len([i for i in incidents if i["kind"] == "Near miss"]),
                        "open": len([i for i in incidents if i["status"] == "OPEN"]),
                        "talks_this_week": len([t for t in talks if (t.held_on or "") >= week_ago]),
                        "active_permits": len([p for p in permits if p["status"] == "ACTIVE" and not p["expired"]]),
                        "expired_open": len([p for p in permits if p["expired"]])}}


@app.post("/api/safety/incidents")
def report_incident(body: IncidentIn, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    job = job_or_404(db, client.id, body.job_id)
    if body.kind not in INCIDENT_KINDS:
        raise HTTPException(400, "What kind: " + ", ".join(INCIDENT_KINDS))
    if not (body.description or "").strip():
        raise HTTPException(400, "Say what happened.")
    if body.kind in ("First aid", "Medical treatment", "Lost time injury", "Fatality") and not (body.injured_name or "").strip():
        raise HTTPException(400, "Who was hurt?")
    i = models.DBSafetyIncident(
        client_id=client.id, job_id=job.id, number=next_number(db, models.DBSafetyIncident, client.id, "INC"),
        happened_on=(body.happened_on or date.today().isoformat())[:10], happened_at=(body.happened_at or "")[:5],
        kind=body.kind, location=(body.location or "").strip(), description=body.description.strip(),
        injured_name=(body.injured_name or "").strip(), injury=(body.injury or "").strip(),
        treatment=(body.treatment or "").strip(), lost_days=max(0.0, float(body.lost_days or 0)),
        immediate_action=(body.immediate_action or "").strip(), root_cause=(body.root_cause or "").strip(),
        corrective_action=(body.corrective_action or "").strip(), reported_by=actor_name)
    db.add(i)
    db.commit()
    notify(db, client.id, "safety_incident", "%s on %s: %s" % (i.kind, job.name, i.number),
           i.description[:300], view="safety-view", ref_type="incident", ref_id=i.id,
           severity="wrong" if i.kind in SERIOUS_KINDS else "action")
    return {"incident": incident_dict(i)}


class IncidentCloseIn(BaseModel):
    root_cause: Optional[str] = ""
    corrective_action: Optional[str] = ""
    closure_note: Optional[str] = ""


@app.post("/api/safety/incidents/{iid}/close")
def close_incident(iid: int, body: IncidentCloseIn, request: Request, db: Session = Depends(get_db)):
    """Closed only with why it happened and what stops it happening again."""
    client, _, _ = wo_actor(request, db)
    i = db.query(models.DBSafetyIncident).filter(models.DBSafetyIncident.id == iid,
                                                 models.DBSafetyIncident.client_id == client.id).first()
    if not i:
        raise HTTPException(404, "Incident not found")
    if i.status == "CLOSED":
        raise HTTPException(409, "%s is already closed." % i.number)
    i.root_cause = (body.root_cause or "").strip() or i.root_cause
    i.corrective_action = (body.corrective_action or "").strip() or i.corrective_action
    if not (i.root_cause and i.corrective_action):
        raise HTTPException(400, "Close it with why it happened and what stops it happening again.")
    i.status, i.closed_on, i.closure_note = "CLOSED", date.today().isoformat(), (body.closure_note or "").strip()
    db.commit()
    return {"incident": incident_dict(i)}


class TalkIn(BaseModel):
    job_id: int
    topic: str
    held_on: Optional[str] = ""
    attendees: Optional[int] = 0
    attendee_names: Optional[str] = ""
    minutes: Optional[int] = 15
    notes: Optional[str] = ""


@app.post("/api/safety/talks")
def record_talk(body: TalkIn, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    job = job_or_404(db, client.id, body.job_id)
    if not (body.topic or "").strip():
        raise HTTPException(400, "What was the talk about?")
    names = [n.strip() for n in re.split(r"[,\n]+", body.attendee_names or "") if n.strip()]
    count = max(int(body.attendees or 0), len(names))
    if count < 1:
        raise HTTPException(400, "How many stood through it?")
    t = models.DBToolboxTalk(client_id=client.id, job_id=job.id, held_on=(body.held_on or date.today().isoformat())[:10],
                             topic=body.topic.strip(), conducted_by=actor_name, attendees=count,
                             attendee_names=", ".join(names), minutes=max(1, int(body.minutes or 15)),
                             notes=(body.notes or "").strip())
    db.add(t)
    db.commit()
    return {"ok": True, "id": t.id}


class PermitIn(BaseModel):
    job_id: int
    kind: str
    location: Optional[str] = ""
    description: Optional[str] = ""
    valid_from: Optional[str] = ""
    valid_to: str
    receiver: Optional[str] = ""
    precautions: Optional[list] = None


@app.post("/api/safety/permits")
def issue_permit(body: PermitIn, request: Request, db: Session = Depends(get_db)):
    """Issued only with every precaution for that kind of work ticked, and
    for one shift at most."""
    client, _, actor_name = wo_actor(request, db)
    job = job_or_404(db, client.id, body.job_id)
    if body.kind not in PERMIT_PRECAUTIONS:
        raise HTTPException(400, "Which permit: " + ", ".join(PERMIT_PRECAUTIONS))
    start = (body.valid_from or datetime.now().strftime("%Y-%m-%d %H:%M")).replace("T", " ")[:16]
    end = (body.valid_to or "").replace("T", " ")[:16]
    try:
        a, b = datetime.strptime(start, "%Y-%m-%d %H:%M"), datetime.strptime(end, "%Y-%m-%d %H:%M")
    except ValueError:
        raise HTTPException(400, "When it runs from and to, as date and time.")
    if b <= a or b - a > timedelta(hours=12):
        raise HTTPException(400, "A permit runs for one shift at most - twelve hours - and ends after it starts.")
    given = {(x.get("item") if isinstance(x, dict) else str(x)): bool(x.get("done")) if isinstance(x, dict) else True
             for x in (body.precautions or [])}
    missing = [p for p in PERMIT_PRECAUTIONS[body.kind] if not given.get(p)]
    if missing:
        raise HTTPException(409, "Not issued - still to be in place: %s." % "; ".join(missing))
    if not (body.receiver or "").strip():
        raise HTTPException(400, "Who is doing the work?")
    p = models.DBWorkPermit(client_id=client.id, job_id=job.id, number=next_number(db, models.DBWorkPermit, client.id, "PTW"),
                            kind=body.kind, location=(body.location or "").strip(), description=(body.description or "").strip(),
                            valid_from=start, valid_to=end, issued_by=actor_name, receiver=body.receiver.strip(),
                            precautions=json.dumps([{"item": x, "done": True} for x in PERMIT_PRECAUTIONS[body.kind]]))
    db.add(p)
    db.commit()
    return {"permit": permit_dict(p)}


class PermitCloseIn(BaseModel):
    note: Optional[str] = ""
    cancel: Optional[bool] = False


@app.post("/api/safety/permits/{pid}/close")
def close_permit(pid: int, body: PermitCloseIn, request: Request, db: Session = Depends(get_db)):
    client, _, actor_name = wo_actor(request, db)
    p = db.query(models.DBWorkPermit).filter(models.DBWorkPermit.id == pid,
                                             models.DBWorkPermit.client_id == client.id).first()
    if not p:
        raise HTTPException(404, "Permit not found")
    if p.status != "ACTIVE":
        raise HTTPException(409, "%s is already %s." % (p.number, p.status.lower()))
    p.status = "CANCELLED" if body.cancel else "CLOSED"
    p.closed_at, p.closed_by = datetime.now().strftime("%Y-%m-%d %H:%M"), actor_name
    p.closure_note = (body.note or "").strip()
    db.commit()
    return {"permit": permit_dict(p)}


# ============================================================================
# RETENTION RELEASED
#
# The register above says how much is being held. This is what brings it
# back: a release on the client at practical completion or at the end of the
# defects period, and the same thing the other way for the gangs whose
# retention we hold. A release is a bill in its own right - it goes in the
# party's ledger, is received or paid through the same box as any other, ages
# in what is owed, and carries the GST the RA bills left off, because each of
# them charged tax only on what it asked for after the retention came off.
# ============================================================================

RETENTION_STAGES = ("Practical completion", "End of defects period",
                    "Against a bank guarantee", "Part release")


def months_after(on, months):
    """The date `months` calendar months after `on`, or "" when it is not a
    date. The last day of a short month stands in for a day it lacks."""
    try:
        d = datetime.strptime(str(on or "")[:10], "%Y-%m-%d").date()
    except ValueError:
        return ""
    m = d.month - 1 + int(months or 0)
    year, month = d.year + m // 12, m % 12 + 1
    return date(year, month, min(d.day, calendar.monthrange(year, month)[1])).isoformat()


def _live_releases(db, client_id, side=None):
    q = db.query(models.DBRetentionRelease).filter(
        models.DBRetentionRelease.client_id == client_id,
        models.DBRetentionRelease.status != "CANCELLED")
    if side:
        q = q.filter(models.DBRetentionRelease.side == side)
    return q.all()


def released_retention(db, client_id, side):
    """{order id: retention released on it} - the client's work orders, or
    the gangs' subcontract orders. Cancelled releases gave nothing back."""
    out = {}
    for r in _live_releases(db, client_id, side):
        key = r.work_order_id if side == "client" else r.sub_order_id
        out[key] = money(out.get(key, 0.0) + (r.amount or 0))
    return out


def released_by_job(db, client_id, side="client"):
    out = {}
    for r in _live_releases(db, client_id, side):
        out[r.job_id] = money(out.get(r.job_id, 0.0) + (r.amount or 0))
    return out


def contractor_released(db, client_id, order_id=0):
    return money(sum(r.amount or 0 for r in _live_releases(db, client_id, "contractor")
                     if not order_id or r.sub_order_id == order_id))


def release_or_404(db, client_id, release_id):
    r = db.query(models.DBRetentionRelease).filter(
        models.DBRetentionRelease.id == release_id,
        models.DBRetentionRelease.client_id == client_id).first()
    if not r:
        raise HTTPException(404, "Release not found")
    return r


def release_party(db, r):
    """(party type, name, id) - the client of the job, or the gang."""
    if r.side == "client":
        job = db.query(models.DBJob).filter(models.DBJob.id == r.job_id).first()
        return "client", (job.customer_name if job else ""), None
    con = db.query(models.DBContractor).filter(
        models.DBContractor.id == r.contractor_id).first() if r.contractor_id else None
    return "contractor", (con.company_name if con else ""), r.contractor_id


def _order_number(db, r):
    if r.side == "client":
        wo = db.query(models.DBWorkOrder).filter(models.DBWorkOrder.id == r.work_order_id).first()
        return wo.number if wo else ""
    o = db.query(models.DBSubcontractOrder).filter(
        models.DBSubcontractOrder.id == r.sub_order_id).first()
    return (o.wo_number or "") if o else ""


def release_dict(db, r, settled=None):
    got = (settled.get(("retention_release", r.id), 0.0) if settled is not None
           else settled_on(db, r.client_id, "retention_release", r.id))
    job = db.query(models.DBJob).filter(models.DBJob.id == r.job_id).first()
    party_type, party, _ = release_party(db, r)
    return {
        "id": r.id, "number": r.number or "", "side": r.side,
        "stage": r.stage or "", "release_on": r.release_on or "",
        "order_id": r.work_order_id if r.side == "client" else r.sub_order_id,
        "order_number": _order_number(db, r),
        "job_id": r.job_id, "project": ("%s %s" % (job.number or "", job.name or "")).strip() if job else "",
        "party": party, "party_type": party_type,
        "amount": money(r.amount), "gst_percent": r.gst_percent or 0,
        "gst_amount": money(r.gst_amount), "cgst_amount": money(r.cgst_amount),
        "sgst_amount": money(r.sgst_amount), "igst_amount": money(r.igst_amount),
        "place_of_supply": r.place_of_supply or "",
        "net_amount": money(r.net_amount),
        "settled": money(got),
        "outstanding": money(max(0.0, (r.net_amount or 0) - got)) if r.status != "CANCELLED" else 0.0,
        "status": r.status or "CERTIFIED", "notes": r.notes or "",
        "cancel_reason": r.cancel_reason or "",
        "created_by_name": r.created_by_name or "", "paid_at": r.paid_at or "",
        "created_at": r.created_at or "",
    }


def retention_positions(db, client_id, today=None):
    """Every order with retention on it, both ways: what its certified bills
    held back, what has been released, and what the next release would be.

    Half at practical completion and the rest at the end of the defects
    period is how most contracts read, so that is what is suggested - the
    amount stays the user's to change, and any release up to the balance can
    be raised."""
    today = today or date.today()
    jobs = {j.id: j for j in db.query(models.DBJob).filter(models.DBJob.client_id == client_id).all()}
    out = []

    def position(side, order_id, order_number, job, party, bills, rate_of, released, extra):
        held = money(sum(b.retention_amount or 0 for b in bills))
        if held <= 0:
            return
        gone = money(released.get(order_id, 0.0))
        balance = money(max(0.0, held - gone))
        latest = max(bills, key=lambda b: (b.sequence or 0, b.id))
        if gone <= 0:
            stage, suggest = "Practical completion", money(held / 2.0)
        else:
            stage, suggest = "End of defects period", balance
        row = {
            "side": side, "order_id": order_id, "order_number": order_number or "",
            "job_id": job.id if job else None,
            "project": ("%s %s" % (job.number or "", job.name or "")).strip() if job else "",
            "job_status": (job.status or "") if job else "",
            "finished": bool(job and (job.status or "").lower() == JOB_FINISHED),
            "completed_at": ((job.completed_at or "")[:10]) if job else "",
            "party": party or "",
            "bills": len(bills), "claimed": money(sum(b.this_bill or 0 for b in bills)),
            "held": held, "released": gone, "balance": balance,
            "gst_percent": rate_of(latest) or 0,
            "suggest": {"stage": stage, "amount": min(suggest, balance)} if balance > 0 else None,
            "dlp_ends": "", "dlp_over": False,
        }
        row.update(extra)
        out.append(row)

    # The client's side: retention on our RA bills, per work order.
    ra_by_wo = {}
    for b in db.query(models.DBRABill).filter(
            models.DBRABill.client_id == client_id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).all():
        ra_by_wo.setdefault(b.work_order_id, []).append(b)
    wos = {w.id: w for w in db.query(models.DBWorkOrder).filter(
        models.DBWorkOrder.client_id == client_id).all()}
    released = released_retention(db, client_id, "client")
    for wo_id, bills in ra_by_wo.items():
        wo = wos.get(wo_id)
        job = jobs.get(wo.job_id if wo else bills[0].job_id)
        position("client", wo_id, wo.number if wo else "", job,
                 job.customer_name if job else "", bills,
                 lambda b: b.tax_percent, released, {})

    # The gangs' side: retention we held on their bills, per subcontract order.
    sub_by_order = {}
    for b in db.query(models.DBSubBill).filter(
            models.DBSubBill.client_id == client_id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).all():
        sub_by_order.setdefault(b.order_id, []).append(b)
    orders = {o.id: o for o in db.query(models.DBSubcontractOrder).filter(
        models.DBSubcontractOrder.client_id == client_id).all()}
    contractors = {c.id: c for c in db.query(models.DBContractor).filter(
        models.DBContractor.client_id == client_id).all()}
    released = released_retention(db, client_id, "contractor")
    for order_id, bills in sub_by_order.items():
        o = orders.get(order_id)
        job = jobs.get(o.job_id if o else bills[0].job_id)
        con = contractors.get(o.contractor_id if o else bills[0].contractor_id)
        # The defects period runs from the order's completion; the second
        # half is theirs once it has run out.
        ends = months_after(o.completion_date, o.defect_liability_months) \
            if o and o.completion_date and (o.defect_liability_months or 0) > 0 else ""
        position("contractor", order_id, (o.wo_number if o else ""), job,
                 con.company_name if con else "", bills, lambda b: b.gst_percent, released,
                 {"contractor_id": con.id if con else None, "dlp_ends": ends,
                  "dlp_months": (o.defect_liability_months or 0) if o else 0,
                  "dlp_over": bool(ends and ends <= today.isoformat())})

    out.sort(key=lambda r: (r["side"] != "client", -r["balance"]))
    return out


@app.get("/api/retention")
def retention_overview(request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    positions = retention_positions(db, client.id)
    settled = settled_amounts(db, client.id)
    releases = [release_dict(db, r, settled) for r in db.query(models.DBRetentionRelease).filter(
        models.DBRetentionRelease.client_id == client.id).order_by(
            models.DBRetentionRelease.id.desc()).limit(500).all()]
    ours = [p for p in positions if p["side"] == "client"]
    theirs = [p for p in positions if p["side"] == "contractor"]
    live = [r for r in releases if r["status"] != "CANCELLED"]
    return {
        "positions": positions, "releases": releases, "stages": list(RETENTION_STAGES),
        "summary": {
            "client_held": money(sum(p["balance"] for p in ours)),
            "client_released": money(sum(p["released"] for p in ours)),
            "client_on_finished": money(sum(p["balance"] for p in ours if p["finished"])),
            "client_to_receive": money(sum(r["outstanding"] for r in live if r["side"] == "client")),
            "contractor_held": money(sum(p["balance"] for p in theirs)),
            "contractor_released": money(sum(p["released"] for p in theirs)),
            "contractor_dlp_over": money(sum(p["balance"] for p in theirs if p["dlp_over"])),
            "contractor_to_pay": money(sum(r["outstanding"] for r in live if r["side"] == "contractor")),
        },
    }


class RetentionReleaseIn(BaseModel):
    side: str = "client"
    order_id: int
    stage: Optional[str] = "Practical completion"
    amount: float
    release_on: Optional[str] = ""
    gst_percent: Optional[float] = None
    notes: Optional[str] = ""


@app.post("/api/retention/releases")
def create_release(body: RetentionReleaseIn, request: Request, db: Session = Depends(get_db)):
    """Release retention: claim it from the client, or owe it to a gang.

    Never more than is still held on that order. The tax is worked out the
    way the order's own bills worked theirs out - the site's state against
    ours, or against the gang's for their side."""
    side = (body.side or "").strip().lower()
    if side not in ("client", "contractor"):
        raise HTTPException(400, "Is this retention the client holds, or retention we hold from a gang?")
    # Owing a gang money is a decision, as certifying their bill is.
    client, actor_id, actor_name = wo_actor(
        request, db, "workorders.manage" if side == "client" else "subcontracts.approve")
    stage = (body.stage or "").strip()
    if stage not in RETENTION_STAGES:
        raise HTTPException(400, "Which stage is this - %s?" % ", ".join(RETENTION_STAGES))
    amount = money(body.amount or 0)
    if amount <= 0:
        raise HTTPException(400, "How much is being released?")
    pos = next((p for p in retention_positions(db, client.id)
                if p["side"] == side and p["order_id"] == body.order_id), None)
    if not pos:
        raise HTTPException(404, "No retention is held on that order.")
    if amount > pos["balance"] + 0.009:
        raise HTTPException(400, "Only %s is still held on %s; %s is more than that."
                                 % (inr(pos["balance"]), pos["order_number"] or "that order", inr(amount)))
    on = (body.release_on or date.today().isoformat())[:10]
    if not _parse_date(on):
        raise HTTPException(400, "Release date should be YYYY-MM-DD.")
    rate = pos["gst_percent"] if body.gst_percent is None else max(0.0, min(28.0, float(body.gst_percent)))

    supply = supply_state_for_job(db, pos["job_id"]) if pos["job_id"] else ""
    if side == "client":
        origin = our_state(db, client.id)
    else:
        origin = contractor_state(db, pos.get("contractor_id")) or our_state(db, client.id)
    gst = split_gst(amount, rate, origin, supply)

    stem = "RET" if side == "client" else "RETG"
    n = db.query(models.DBRetentionRelease).filter(
        models.DBRetentionRelease.client_id == client.id,
        models.DBRetentionRelease.side == side).count() + 1
    r = models.DBRetentionRelease(
        client_id=client.id, side=side,
        work_order_id=body.order_id if side == "client" else None,
        sub_order_id=body.order_id if side == "contractor" else None,
        job_id=pos["job_id"], contractor_id=pos.get("contractor_id"),
        number="%s-%04d" % (stem, n), stage=stage, release_on=on, amount=amount,
        gst_percent=rate, gst_amount=gst["total"], cgst_amount=gst["cgst"],
        sgst_amount=gst["sgst"], igst_amount=gst["igst"], place_of_supply=supply,
        net_amount=money(amount + gst["total"]), status="CERTIFIED",
        notes=(body.notes or "").strip()[:500], created_by_name=actor_name or "")
    db.add(r)
    db.flush()
    log_audit(db, client.id, "retention_released", "retention_release", r.id, r.number,
              "%s %s on %s" % (stage, inr(amount), pos["order_number"]), request)
    db.commit()
    db.refresh(r)
    if side == "client":
        notify(db, client.id, "retention_released", "%s - retention to claim from %s" % (r.number, pos["party"] or "the client"),
               "%s released at %s on %s, %s with GST." % (inr(amount), stage.lower(), pos["project"], inr(r.net_amount)),
               view="money-view", ref_type="retention_release", ref_id=r.id, severity="money")
    else:
        notify(db, client.id, "retention_released", "%s - retention due to %s" % (r.number, pos["party"] or "the gang"),
               "%s released at %s on %s, %s with GST." % (inr(amount), stage.lower(), pos["order_number"], inr(r.net_amount)),
               view="money-view", ref_type="retention_release", ref_id=r.id, severity="action")
    db.refresh(r)
    return {"release": release_dict(db, r),
            "message": "%s raised: %s released, %s with GST." % (r.number, inr(amount), inr(r.net_amount))}


@app.get("/api/retention/releases/{release_id}")
def get_release(release_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    return release_dict(db, release_or_404(db, client.id, release_id))


@app.post("/api/retention/releases/{release_id}/cancel")
def cancel_release(release_id: int, request: Request, body: dict = None,
                   db: Session = Depends(get_db)):
    """A release raised in error goes back to being held. Not once money has
    moved against it - that is voided first, as with any bill."""
    client, actor_id, actor_name = wo_actor(request, db)
    r = release_or_404(db, client.id, release_id)
    reason = ((body or {}).get("reason") or "").strip()
    if not reason:
        raise HTTPException(400, "Say why it is being cancelled.")
    if r.status == "CANCELLED":
        raise HTTPException(409, "%s is already cancelled." % r.number)
    refuse_cancel_with_money(db, client.id, "retention_release", r,
                             "received" if r.side == "client" else "paid")
    refuse_cancel_with_irn(db, client.id, "retention_release", r)
    r.status, r.cancel_reason = "CANCELLED", reason[:300]
    log_audit(db, client.id, "retention_release_cancelled", "retention_release", r.id, r.number, reason, request)
    db.commit()
    return {"release": release_dict(db, r), "message": "%s cancelled; the retention is held again." % r.number}


@app.get("/api/retention/releases/{release_id}/export.xlsx")
def export_release(release_id: int, request: Request, db: Session = Depends(get_db)):
    """The release as a bill: the RA bills whose retention it gives back,
    then what was held, released before, released now, and the tax."""
    client = require_erp_read(request, db)
    r = release_or_404(db, client.id, release_id)
    d = release_dict(db, r)
    if r.side == "client":
        bills = db.query(models.DBRABill).filter(
            models.DBRABill.work_order_id == r.work_order_id,
            models.DBRABill.status.in_(("CERTIFIED", "PAID"))).order_by(models.DBRABill.id).all()
    else:
        bills = db.query(models.DBSubBill).filter(
            models.DBSubBill.order_id == r.sub_order_id,
            models.DBSubBill.status.in_(("CERTIFIED", "PAID"))).order_by(models.DBSubBill.id).all()
    held = money(sum(b.retention_amount or 0 for b in bills))
    before = money(sum(x.amount or 0 for x in _live_releases(db, client.id, r.side)
                       if x.id < r.id and (x.work_order_id, x.sub_order_id) == (r.work_order_id, r.sub_order_id)))
    rows = [(b.number or "", (b.certified_at or "")[:10], money(b.this_bill),
             b.retention_percent or 0, money(b.retention_amount)) for b in bills]
    tax = []
    if r.cgst_amount or r.sgst_amount:
        tax = [("CGST @ %s%%" % (d["gst_percent"] / 2), "", "", "", d["cgst_amount"]),
               ("SGST @ %s%%" % (d["gst_percent"] / 2), "", "", "", d["sgst_amount"])]
    elif r.igst_amount:
        tax = [("IGST @ %s%%" % d["gst_percent"], "", "", "", d["igst_amount"])]
    title = "RETENTION RELEASE" if r.side == "client" else "RETENTION RELEASED TO SUBCONTRACTOR"
    return sheet_response(
        ("Bill", "Certified", "Bill value", "Retention %", "Retention held"),
        rows, "%s.xlsx" % (r.number or "release"),
        preamble=[(title, client.company_name or ""),
                  ("Number", d["number"]), ("Date", d["release_on"]),
                  ("To" if r.side == "client" else "Payable to", d["party"]),
                  ("Project", d["project"]), ("Order", d["order_number"]),
                  ("Stage", d["stage"]),
                  ("Place of supply", d["place_of_supply"]), ("SAC", WORKS_CONTRACT_SAC),
                  ()],
        closing=[(), ("Retention held on these bills", "", "", "", held),
                 ("Released before", "", "", "", -before),
                 ("Released now", "", "", "", d["amount"])] + tax +
                [("Total %s" % ("claimed" if r.side == "client" else "payable"), "", "", "", d["net_amount"])] +
                ([(), ("Note", d["notes"])] if d["notes"] else []))


def release_ledger_rows(db, client_id):
    """Releases in the party ledgers: a claim on the client, or a sum owed to
    a gang, the day it was raised."""
    rows = []
    for r in db.query(models.DBRetentionRelease).filter(
            models.DBRetentionRelease.client_id == client_id,
            models.DBRetentionRelease.status.in_(("CERTIFIED", "PAID"))).all():
        party_type, party, _ = release_party(db, r)
        rows.append({"party_type": party_type, "party": party, "date": r.release_on or (r.created_at or "")[:10],
                     "kind": "Retention released" if r.side == "client" else "Their retention released",
                     "number": r.number, "doc_type": "retention_release", "doc_id": r.id,
                     "billed": money(r.net_amount), "moved": 0.0, "job_id": r.job_id})
    return rows


def release_gst_rows(db, client_id, side, date_from="", date_to=""):
    """Releases as supplies for the GST registers - ours outward, the gangs'
    inward. Taxable is the retention released; the bills taxed the rest."""
    rows = []
    for r in db.query(models.DBRetentionRelease).filter(
            models.DBRetentionRelease.client_id == client_id,
            models.DBRetentionRelease.side == side,
            models.DBRetentionRelease.status.in_(("CERTIFIED", "PAID"))).all():
        on = (r.release_on or r.created_at or "")[:10]
        if (date_from and on < date_from) or (date_to and on > date_to):
            continue
        party_type, party, party_id = release_party(db, r)
        job = db.query(models.DBJob).filter(models.DBJob.id == r.job_id).first()
        row = {"kind": "Retention release", "number": r.number or "", "date": on,
               "party": party, "project": job.name if job else "",
               "place_of_supply": r.place_of_supply or "",
               "sac": WORKS_CONTRACT_SAC, "rate": r.gst_percent or 0,
               "taxable": money(r.amount), "cgst": money(r.cgst_amount), "sgst": money(r.sgst_amount),
               "igst": money(r.igst_amount), "tax": money(r.gst_amount),
               "total": money(r.net_amount)}
        if side == "contractor":
            con = db.query(models.DBContractor).filter(models.DBContractor.id == party_id).first() if party_id else None
            row["party_gstin"] = (con.gst_number or "") if con else ""
        rows.append(row)
    return rows


def release_attention(db, client_id, today):
    """A gang's defects period that has run out with their retention still
    held: they will be asking for it, and should be paid it on time."""
    over = [p for p in retention_positions(db, client_id, today)
            if p["side"] == "contractor" and p["dlp_over"] and p["balance"] > 0]
    if not over:
        return []
    return [{"kind": "retention_gangs", "severity": "action",
             "value": money(sum(p["balance"] for p in over)), "count": len(over),
             "view": "money-view", "title": "Gangs' retention due back",
             "detail": "%s held on %d order%s whose defects period has run out."
                       % (inr(sum(p["balance"] for p in over)), len(over), "" if len(over) == 1 else "s")}]


# ============================================================================
# FIXED ASSETS AND DEPRECIATION
#
# The equipment register says where a machine is and what it burned. It did
# not say what it is worth: an excavator bought for forty lakhs three years
# ago was carried at forty lakhs for ever, and the depreciation schedule the
# auditor asks for every March was built by hand from the purchase bills.
#
# Two books, because the law keeps two. The company's own (Schedule II:
# straight line or written-down value over a useful life, pro rata from the
# day the asset was put to use) and the income-tax one (blocks of assets at
# a rate, half the rate on anything used for less than 180 days in the year
# it was bought). The lives and rates below are the usual ones and are only
# where each asset starts - every one of them can be changed.
# ============================================================================

# Category -> (useful life in years, income-tax block).
ASSET_BOOK_DEFAULTS = {
    "Earthmoving": (9, "Plant & machinery"),
    "Concrete": (12, "Plant & machinery"),
    "Lifting": (15, "Plant & machinery"),
    "Compaction": (12, "Plant & machinery"),
    "Transport": (8, "Motor vehicles"),
    "Vehicle": (8, "Motor vehicles"),
    "Power": (15, "Plant & machinery"),
    "Pumping": (15, "Plant & machinery"),
    "Shuttering": (12, "Plant & machinery"),
    "Survey": (15, "Plant & machinery"),
    "Tools": (15, "Plant & machinery"),
    "Computers": (3, "Computers"),
    "Furniture": (10, "Furniture & fittings"),
    "Office equipment": (5, "Plant & machinery"),
    "Building": (60, "Buildings"),
    "Other": (15, "Plant & machinery"),
}
TAX_BLOCK_DEFAULTS = (("Plant & machinery", 15.0), ("Motor vehicles", 15.0),
                      ("Lorries used on hire", 30.0), ("Computers", 40.0),
                      ("Furniture & fittings", 10.0), ("Buildings", 10.0),
                      ("Intangible assets", 25.0))
BOOK_METHODS = ("WDV", "SLM")
HALF_RATE_DAYS = 180


def fy_label(y):
    return "%d-%02d" % (y, (y + 1) % 100)


def fy_start_year(value):
    """The year a financial year starts in, from "2026-27", a date, or a
    date object. April to March."""
    if isinstance(value, date):
        return value.year if value.month >= 4 else value.year - 1
    text = str(value or "").strip()
    m = re.match(r"^(\d{4})-(\d{2})$", text)
    if m and int(m.group(2)) == (int(m.group(1)) + 1) % 100:
        return int(m.group(1))
    d = _parse_date(text)
    return fy_start_year(d) if d else None


def fy_bounds(y):
    return date(y, 4, 1), date(y + 1, 3, 31)


def ensure_tax_blocks(db, client_id):
    have = {b.name for b in db.query(models.DBTaxBlock).filter(
        models.DBTaxBlock.client_id == client_id).all()}
    added = False
    for name, rate in TAX_BLOCK_DEFAULTS:
        if name not in have:
            db.add(models.DBTaxBlock(client_id=client_id, name=name, rate=rate))
            added = True
    if added:
        db.flush()
    return db.query(models.DBTaxBlock).filter(
        models.DBTaxBlock.client_id == client_id).order_by(models.DBTaxBlock.id).all()


def wdv_rate(book):
    """The written-down rate that brings cost to its residual over the life:
    1 - (residual / cost) ^ (1 / life)."""
    cost = book.cost or 0
    residual = cost * (book.residual_percent or 0) / 100.0
    if cost <= 0 or residual <= 0 or (book.life_years or 0) <= 0:
        return 0.0
    return 1.0 - (residual / cost) ** (1.0 / float(book.life_years))


def book_schedule(book, upto_year):
    """Year by year, from the year the book starts to `upto_year`: opening,
    added, depreciation, what it fetched if it went, and closing."""
    rows = []
    put = _parse_date(book.put_to_use_on)
    cost = money(book.cost or 0)
    if not put or cost <= 0 or (book.life_years or 0) <= 0:
        return rows
    residual = money(cost * (book.residual_percent or 0) / 100.0)
    rate = wdv_rate(book)
    annual = (cost - residual) / float(book.life_years)
    opening_year = fy_start_year(book.opening_fy) if book.opening_fy else None
    if opening_year is not None and opening_year <= fy_start_year(put):
        opening_year = None          # an opening no earlier than purchase is just the purchase
    start = opening_year if opening_year is not None else fy_start_year(put)
    gone = _parse_date(book.disposed_on)
    closing = 0.0
    for y in range(start, upto_year + 1):
        fy_from, fy_to = fy_bounds(y)
        days_in = (fy_to - fy_from).days + 1
        if y == start and opening_year is not None:
            opening, added, from_day = money(book.opening_book_value or 0), 0.0, fy_from
        elif y == start:
            opening, added, from_day = 0.0, cost, put
        else:
            opening, added, from_day = closing, 0.0, fy_from
        if gone and gone < from_day:
            break
        to_day = gone if gone and gone <= fy_to else fy_to
        used = max(0, (to_day - from_day).days + 1)
        base = money(opening + added)
        room = max(0.0, base - residual)
        if book.method == "SLM":
            dep = min(annual * used / days_in, room)
        else:
            dep = min(base * rate * used / days_in, room)
        dep = money(dep)
        closing = money(base - dep)
        row = {"fy": fy_label(y), "opening": opening, "added": added, "depreciation": dep,
               "closing": closing, "accumulated": money(cost - closing),
               "days": used, "disposed": False, "disposal_value": 0.0, "gain": 0.0}
        if gone and fy_from <= gone <= fy_to:
            row.update({"disposed": True, "disposal_value": money(book.disposal_value or 0),
                        "book_value_at_sale": closing,
                        "gain": money((book.disposal_value or 0) - closing), "closing": 0.0,
                        "accumulated": money(cost - closing)})
            rows.append(row)
            break
        rows.append(row)
    return rows


def book_dict(book, a, fy_year):
    rows = book_schedule(book, fy_year)
    row = next((r for r in rows if r["fy"] == fy_label(fy_year)), None)
    before = rows[-1] if rows and not row else None
    return {
        "asset_id": a.id, "code": a.code or "", "name": a.name or "", "category": a.category or "",
        "status": a.status or "", "method": book.method or "WDV",
        "life_years": book.life_years or 0, "residual_percent": book.residual_percent or 0,
        "rate_percent": round(wdv_rate(book) * 100, 2) if book.method != "SLM"
        else (round(100.0 / book.life_years, 2) if book.life_years else 0),
        "put_to_use_on": book.put_to_use_on or "", "cost": money(book.cost),
        "opening_fy": book.opening_fy or "", "opening_book_value": money(book.opening_book_value),
        "tax_block": book.tax_block or "", "disposed_on": book.disposed_on or "",
        "disposal_value": money(book.disposal_value), "disposal_note": book.disposal_note or "",
        # The year asked for; an asset gone before it, or not yet bought, has none.
        "year": row,
        "in_year": bool(row),
        "gone_before": bool(before and before.get("disposed")),
    }


def asset_book_or_none(db, client_id, asset_id):
    return db.query(models.DBAssetBook).filter(
        models.DBAssetBook.client_id == client_id,
        models.DBAssetBook.asset_id == asset_id).first()


def default_book(a):
    life, block = ASSET_BOOK_DEFAULTS.get(a.category or "Other", ASSET_BOOK_DEFAULTS["Other"])
    return {"method": "WDV", "life_years": life, "residual_percent": 5.0,
            "put_to_use_on": a.purchase_date or "", "cost": money(a.purchase_value),
            "tax_block": block}


@app.get("/api/fixed-assets")
def fixed_asset_register(request: Request, fy: str = "", db: Session = Depends(get_db)):
    """The fixed asset register for one financial year: every owned asset
    with a book, what it opened at, what was added, the year's depreciation,
    what went, and what it closes at."""
    client = require_erp_read(request, db)
    year = fy_start_year(fy) if fy else fy_start_year(date.today())
    if year is None:
        raise HTTPException(400, "Financial year should read like 2026-27.")
    blocks = ensure_tax_blocks(db, client.id)
    db.commit()
    books = {b.asset_id: b for b in db.query(models.DBAssetBook).filter(
        models.DBAssetBook.client_id == client.id).all()}
    rows, unset = [], []
    first = year
    for a in db.query(models.DBAsset).filter(models.DBAsset.client_id == client.id).order_by(
            models.DBAsset.code).all():
        if (a.ownership or "Owned") != "Owned":
            continue
        b = books.get(a.id)
        if not b:
            d = default_book(a)
            unset.append({"asset_id": a.id, "code": a.code or "", "name": a.name or "",
                          "category": a.category or "", "status": a.status or "",
                          "suggest": d, "ready": bool(d["cost"] > 0 and d["put_to_use_on"])})
            continue
        d = book_dict(b, a, year)
        start = fy_start_year(b.opening_fy) if b.opening_fy else fy_start_year(b.put_to_use_on)
        if start is not None:
            first = min(first, start)
        if d["in_year"]:
            rows.append(d)
    ys = [r["year"] for r in rows]
    return {
        "fy": fy_label(year), "fys": [fy_label(y) for y in range(max(first, year - 15), fy_start_year(date.today()) + 2)][::-1],
        "assets": rows, "not_set_up": unset,
        "methods": list(BOOK_METHODS), "blocks": [b.name for b in blocks],
        "defaults": {k: {"life_years": v[0], "tax_block": v[1]} for k, v in ASSET_BOOK_DEFAULTS.items()},
        "totals": {
            "cost": money(sum(r["cost"] for r in rows)),
            "opening": money(sum(y["opening"] for y in ys)),
            "added": money(sum(y["added"] for y in ys)),
            "depreciation": money(sum(y["depreciation"] for y in ys)),
            "disposed": money(sum(y["disposal_value"] for y in ys)),
            "gain": money(sum(y["gain"] for y in ys)),
            "closing": money(sum(y["closing"] for y in ys)),
            "accumulated": money(sum(y["accumulated"] for y in ys if not y["disposed"])),
            "assets": len(rows), "not_set_up": len(unset),
        },
    }


class AssetBookIn(BaseModel):
    method: Optional[str] = "WDV"
    life_years: Optional[float] = None
    residual_percent: Optional[float] = 5.0
    put_to_use_on: Optional[str] = ""
    cost: Optional[float] = None
    opening_fy: Optional[str] = ""
    opening_book_value: Optional[float] = 0
    tax_block: Optional[str] = ""


def _apply_book(db, client_id, a, b, body):
    method = (body.method or "WDV").upper()
    if method not in BOOK_METHODS:
        raise HTTPException(400, "Method is WDV (written-down value) or SLM (straight line).")
    d = default_book(a)
    life = float(body.life_years if body.life_years is not None else d["life_years"])
    if not 0 < life <= 100:
        raise HTTPException(400, "Useful life should be between a year and a hundred.")
    residual = float(body.residual_percent if body.residual_percent is not None else 5.0)
    if not 0 <= residual < 100:
        raise HTTPException(400, "Residual value is a percentage of cost, under a hundred.")
    if method == "WDV" and residual <= 0:
        raise HTTPException(400, "Written-down value needs a residual above nought - five per cent is usual.")
    cost = money(body.cost if body.cost is not None else d["cost"])
    if cost <= 0:
        raise HTTPException(400, "What did it cost? The purchase bill value, with anything spent to bring it into use.")
    put = (body.put_to_use_on or d["put_to_use_on"] or "")[:10]
    if not _parse_date(put):
        raise HTTPException(400, "When was it put to use? (YYYY-MM-DD)")
    opening_fy = (body.opening_fy or "").strip()
    opening_value = money(body.opening_book_value or 0)
    if opening_fy:
        y = fy_start_year(opening_fy)
        if y is None:
            raise HTTPException(400, "Opening year should read like 2025-26.")
        opening_fy = fy_label(y)
        if y > fy_start_year(put):
            if opening_value <= 0:
                raise HTTPException(400, "What was its book value at the start of %s? The last audited "
                                         "accounts carry it." % opening_fy)
            if opening_value > cost + 0.009:
                raise HTTPException(400, "The opening book value cannot be more than it cost.")
        else:
            opening_fy, opening_value = "", 0.0
    blocks = {x.name for x in ensure_tax_blocks(db, client_id)}
    block = (body.tax_block or d["tax_block"]).strip()
    if block not in blocks:
        raise HTTPException(400, "Unknown income-tax block: %s" % block)
    b.method, b.life_years, b.residual_percent = method, life, residual
    b.cost, b.put_to_use_on, b.tax_block = cost, put, block
    b.opening_fy, b.opening_book_value = opening_fy, opening_value
    b.updated_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return b


@app.put("/api/fixed-assets/{asset_id}/book")
def save_asset_book(asset_id: int, body: AssetBookIn, request: Request, db: Session = Depends(get_db)):
    client, actor_id, actor_name = wo_actor(request, db)
    a = asset_or_404(db, client.id, asset_id)
    if (a.ownership or "Owned") != "Owned":
        raise HTTPException(409, "%s is hired in. Only what the business owns is depreciated." % a.code)
    b = asset_book_or_none(db, client.id, a.id)
    if b and b.disposed_on:
        raise HTTPException(409, "%s was disposed of on %s; its book is closed." % (a.code, b.disposed_on))
    new = b is None
    if new:
        b = models.DBAssetBook(client_id=client.id, asset_id=a.id)
        db.add(b)
    _apply_book(db, client.id, a, b, body)
    log_audit(db, client.id, "asset_book_" + ("set" if new else "changed"), "asset", a.id, a.code,
              "%s %s yrs, cost %s" % (b.method, b.life_years, inr(b.cost)), request)
    db.commit()
    return {"book": book_dict(b, a, fy_start_year(date.today())),
            "message": "%s: %s over %g years from %s." % (a.code, b.method, b.life_years, b.put_to_use_on)}


@app.post("/api/fixed-assets/set-up-all")
def set_up_all_books(request: Request, db: Session = Depends(get_db)):
    """Every owned asset with a purchase value and date gets a book on its
    category's defaults. Anything missing either is left to be done by hand."""
    client, _, _ = wo_actor(request, db)
    have = {b.asset_id for b in db.query(models.DBAssetBook).filter(
        models.DBAssetBook.client_id == client.id).all()}
    made, skipped = [], []
    for a in db.query(models.DBAsset).filter(models.DBAsset.client_id == client.id).all():
        if (a.ownership or "Owned") != "Owned" or a.id in have:
            continue
        if not (a.purchase_value or 0) > 0 or not _parse_date(a.purchase_date):
            skipped.append(a.code)
            continue
        b = models.DBAssetBook(client_id=client.id, asset_id=a.id)
        db.add(b)
        _apply_book(db, client.id, a, b, AssetBookIn())
        made.append(a.code)
    log_audit(db, client.id, "asset_books_set_up", "asset", 0, "", "%d set up" % len(made), request)
    db.commit()
    return {"made": made, "skipped": skipped,
            "message": "%d asset%s set up on the usual lives%s." % (
                len(made), "" if len(made) == 1 else "s",
                ("; %d need a purchase value and date first" % len(skipped)) if skipped else "")}


@app.get("/api/fixed-assets/{asset_id}/schedule")
def asset_book_schedule(asset_id: int, request: Request, db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    a = asset_or_404(db, client.id, asset_id)
    b = asset_book_or_none(db, client.id, a.id)
    if not b:
        raise HTTPException(404, "%s has no book yet." % a.code)
    upto = fy_start_year(date.today())
    if b.disposed_on:
        upto = fy_start_year(b.disposed_on) or upto
    return {"book": book_dict(b, a, upto), "rows": book_schedule(b, upto)}


class AssetDisposalIn(BaseModel):
    disposed_on: str
    disposal_value: Optional[float] = 0
    note: Optional[str] = ""


@app.post("/api/fixed-assets/{asset_id}/dispose")
def dispose_booked_asset(asset_id: int, body: AssetDisposalIn, request: Request,
                         db: Session = Depends(get_db)):
    """Sold or scrapped: depreciation stops that day, and what it fetched
    against what the books still carried is the gain or the loss."""
    client, _, actor_name = wo_actor(request, db)
    a = asset_or_404(db, client.id, asset_id)
    b = asset_book_or_none(db, client.id, a.id)
    if not b:
        raise HTTPException(404, "%s has no book yet. Set it up first, so the sale is set against "
                                 "what it was worth." % a.code)
    if b.disposed_on:
        raise HTTPException(409, "%s was already disposed of on %s." % (a.code, b.disposed_on))
    if a.current_job_id:
        raise HTTPException(409, "%s is still on a site. Bring it back to the yard first." % a.code)
    on = _parse_date(body.disposed_on)
    if not on:
        raise HTTPException(400, "When did it go? (YYYY-MM-DD)")
    if on < _parse_date(b.put_to_use_on):
        raise HTTPException(400, "It cannot go before it was put to use (%s)." % b.put_to_use_on)
    if on > date.today():
        raise HTTPException(400, "That date has not come yet.")
    value = money(body.disposal_value or 0)
    if value < 0:
        raise HTTPException(400, "What it fetched cannot be less than nothing.")
    b.disposed_on, b.disposal_value = on.isoformat(), value
    b.disposal_note = (body.note or "").strip()[:300]
    a.status = "Disposed"
    a.notes = ((a.notes or "") + "\nDisposed %s for %s%s" % (
        on.isoformat(), inr(value), (": " + b.disposal_note) if b.disposal_note else "")).strip()
    rows = book_schedule(b, fy_start_year(on))
    last = rows[-1] if rows else {"book_value_at_sale": 0.0, "gain": value}
    log_audit(db, client.id, "asset_disposed", "asset", a.id, a.code,
              "for %s, book %s" % (inr(value), inr(last.get("book_value_at_sale", 0))), request)
    db.commit()
    gain = last.get("gain", 0.0)
    return {"book": book_dict(b, a, fy_start_year(on)), "book_value": last.get("book_value_at_sale", 0.0),
            "gain": gain,
            "message": "%s disposed of for %s against a book value of %s: a %s of %s." % (
                a.code, inr(value), inr(last.get("book_value_at_sale", 0.0)),
                "profit" if gain >= 0 else "loss", inr(abs(gain)))}


def tax_block_schedule(db, client_id, year):
    """Income-tax depreciation, block by block, for one year.

    Opening WDV, plus what was bought (at the full rate if used 180 days or
    more that year, half the rate if less), less what anything sold fetched.
    Where sales take a block below nothing, the excess is a short-term gain
    and the block closes at nought; where every asset in a block has gone,
    what is left is a short-term loss and no depreciation is due on it."""
    blocks = ensure_tax_blocks(db, client_id)
    books = db.query(models.DBAssetBook).filter(models.DBAssetBook.client_id == client_id).all()
    out = []
    for blk in blocks:
        mine = [b for b in books if b.tax_block == blk.name and _parse_date(b.put_to_use_on)]
        open_year = fy_start_year(blk.opening_fy) if blk.opening_fy else None
        years = [fy_start_year(b.put_to_use_on) for b in mine]
        start = open_year if open_year is not None else (min(years) if years else year)
        closing = money(blk.opening_wdv or 0) if open_year is not None else 0.0
        row = None
        for y in range(start, year + 1):
            fy_from, fy_to = fy_bounds(y)
            opening = closing
            full = half = deleted = 0.0
            counted = []
            for b in mine:
                put = _parse_date(b.put_to_use_on)
                # Bought before the block's opening: already inside that WDV.
                if open_year is not None and fy_start_year(put) < open_year:
                    pass
                elif fy_from <= put <= fy_to:
                    if (fy_to - put).days + 1 >= HALF_RATE_DAYS:
                        full += b.cost or 0
                    else:
                        half += b.cost or 0
                gone = _parse_date(b.disposed_on)
                if gone and fy_from <= gone <= fy_to:
                    deleted += b.disposal_value or 0
                    counted.append(b)
            base = money(opening + full + half - deleted)
            left = [b for b in mine if not (_parse_date(b.disposed_on) and _parse_date(b.disposed_on) <= fy_to)]
            ceased = bool(mine) and not left and not (blk.opening_wdv or 0)
            gain = loss = dep = 0.0
            if base < 0:
                gain, closing = money(-base), 0.0
            elif ceased:
                loss, closing = base, 0.0
            else:
                half_part = min(money(half), base)
                full_part = money(base - half_part)
                dep = money(full_part * blk.rate / 100.0 + half_part * blk.rate / 200.0)
                closing = money(base - dep)
            row = {"block_id": blk.id, "block": blk.name, "rate": blk.rate, "fy": fy_label(y),
                   "opening": opening, "added_full": money(full), "added_half": money(half),
                   "deleted": money(deleted), "depreciation": dep, "closing": closing,
                   "short_term_gain": gain, "short_term_loss": loss,
                   "opening_fy": blk.opening_fy or "", "opening_wdv": money(blk.opening_wdv),
                   "assets": len(left)}
        if row is None:
            row = {"block_id": blk.id, "block": blk.name, "rate": blk.rate, "fy": fy_label(year),
                   "opening": 0.0, "added_full": 0.0, "added_half": 0.0, "deleted": 0.0,
                   "depreciation": 0.0, "closing": 0.0, "short_term_gain": 0.0, "short_term_loss": 0.0,
                   "opening_fy": blk.opening_fy or "", "opening_wdv": money(blk.opening_wdv), "assets": 0}
        out.append(row)
    return out


@app.get("/api/fixed-assets/tax-blocks")
def tax_blocks(request: Request, fy: str = "", db: Session = Depends(get_db)):
    client = require_erp_read(request, db)
    year = fy_start_year(fy) if fy else fy_start_year(date.today())
    if year is None:
        raise HTTPException(400, "Financial year should read like 2026-27.")
    rows = tax_block_schedule(db, client.id, year)
    db.commit()
    return {"fy": fy_label(year), "blocks": rows, "totals": {
        k: money(sum(r[k] for r in rows)) for k in
        ("opening", "added_full", "added_half", "deleted", "depreciation", "closing",
         "short_term_gain", "short_term_loss")}}


class TaxBlockIn(BaseModel):
    rate: Optional[float] = None
    opening_fy: Optional[str] = ""
    opening_wdv: Optional[float] = 0


@app.put("/api/fixed-assets/tax-blocks/{block_id}")
def save_tax_block(block_id: int, body: TaxBlockIn, request: Request, db: Session = Depends(get_db)):
    client, _, _ = wo_actor(request, db)
    blk = db.query(models.DBTaxBlock).filter(models.DBTaxBlock.id == block_id,
                                             models.DBTaxBlock.client_id == client.id).first()
    if not blk:
        raise HTTPException(404, "Block not found")
    if body.rate is not None:
        if not 0 <= body.rate <= 100:
            raise HTTPException(400, "A rate is a percentage.")
        blk.rate = float(body.rate)
    if body.opening_fy:
        y = fy_start_year(body.opening_fy)
        if y is None:
            raise HTTPException(400, "Opening year should read like 2025-26.")
        if (body.opening_wdv or 0) < 0:
            raise HTTPException(400, "The written-down value cannot be below nought.")
        blk.opening_fy, blk.opening_wdv = fy_label(y), money(body.opening_wdv or 0)
    else:
        blk.opening_fy, blk.opening_wdv = "", 0.0
    log_audit(db, client.id, "tax_block_changed", "tax_block", blk.id, blk.name,
              "%s%% from %s at %s" % (blk.rate, blk.opening_fy or "purchase", inr(blk.opening_wdv)), request)
    db.commit()
    return {"ok": True, "message": "%s saved." % blk.name}


